(function () {
    const D = window.DAU_DATA = window.DAU_DATA || {};
    D.etsReadingTests = D.etsReadingTests || [];
    D.readingExercises = D.readingExercises || [];
    const meta = {"id":"reading-lv6-test-1","level":6,"year":"2026","code":"Test 01","title":"Đề Luyện đọc Level 6 (900–990) - Test 01"};
    if (!D.etsReadingTests.some(x => x.id === meta.id)) D.etsReadingTests.push(meta);
    D.readingExercises.push(...[{"id":"reading-lv6-test-1-q101","questionNumber":101,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 101 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"Because the subsidiary's quarterly ledger contained several unreconciled entries, the external auditor declined to _______ the financial statements without supplementary documentation.","options":[{"key":"A","text":"(A) extrapolate"},{"key":"B","text":"(B) disseminate"},{"key":"C","text":"(C) certify"},{"key":"D","text":"(D) proliferate"}],"correct":"C","translation":"Vì sổ cái hằng quý của công ty con chứa nhiều bút toán chưa được đối chiếu, kiểm toán viên bên ngoài từ chối xác nhận báo cáo tài chính khi chưa có tài liệu bổ sung.","explanation":"Động từ 'certify' mang nghĩa xác nhận, chứng thực tính chính xác của báo cáo tài chính (certify financial statements). 'disseminate' (phổ biến rộng rãi), 'extrapolate' (ngoại suy) và 'proliferate' (gia tăng nhanh chóng) không hợp ngữ cảnh kiểm toán.","vocab":[{"word":"unreconciled","pos":"adj.","meaning":"chưa được đối chiếu"},{"word":"certify","pos":"v.","meaning":"chứng thực, xác nhận"},{"word":"supplementary","pos":"adj.","meaning":"bổ sung"}]},{"id":"reading-lv6-test-1-q102","questionNumber":102,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 102 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"Not only _______ the merger agreement fail to address liability caps, but it also omitted any provision for post-closing adjustments.","options":[{"key":"A","text":"(A) had"},{"key":"B","text":"(B) was"},{"key":"C","text":"(C) would"},{"key":"D","text":"(D) did"}],"correct":"D","translation":"Không những thỏa thuận sáp nhập không đề cập đến các giới hạn trách nhiệm mà còn bỏ sót mọi điều khoản về điều chỉnh sau khi hoàn tất giao dịch.","explanation":"Khi 'Not only' đứng đầu câu, mệnh đề theo sau phải đảo trợ động từ lên trước chủ ngữ. Động từ chính 'fail' ở dạng nguyên mẫu và vế sau dùng quá khứ đơn 'omitted', nên trợ động từ đúng là 'did'. 'had' đòi hỏi V3, 'was' không đi với nguyên mẫu 'fail', và 'would' sai nghĩa giả định.","vocab":[{"word":"liability cap","pos":"n.","meaning":"giới hạn trách nhiệm"},{"word":"provision","pos":"n.","meaning":"điều khoản"},{"word":"post-closing","pos":"adj.","meaning":"sau khi hoàn tất giao dịch"}]},{"id":"reading-lv6-test-1-q103","questionNumber":103,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 103 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"_______ to repeated delays in customs clearance, the electronics manufacturer diversified its air-freight routing through two secondary regional hubs.","options":[{"key":"A","text":"(A) Subjecting"},{"key":"B","text":"(B) Subjected"},{"key":"C","text":"(C) Having subjected"},{"key":"D","text":"(D) To subject"}],"correct":"B","translation":"Do phải hứng chịu nhiều lần chậm trễ trong khâu thông quan, nhà sản xuất điện tử đã đa dạng hóa tuyến vận chuyển hàng không qua hai trung tâm khu vực phụ.","explanation":"Rút gọn mệnh đề trạng ngữ mang nghĩa bị động (Because the manufacturer was subjected to...): lược bỏ liên từ và chủ ngữ, giữ quá khứ phân từ 'Subjected'. 'Subjecting' và 'Having subjected' mang nghĩa chủ động (sai logic), còn 'To subject' chỉ mục đích.","vocab":[{"word":"be subjected to","pos":"phr.","meaning":"phải hứng chịu, trải qua"},{"word":"customs clearance","pos":"n.","meaning":"thủ tục thông quan"},{"word":"diversify","pos":"v.","meaning":"đa dạng hóa"}]},{"id":"reading-lv6-test-1-q104","questionNumber":104,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 104 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"Legal counsel advised the spokesperson to refrain from speculating on pending litigation, _______ such remarks be construed as an admission of liability.","options":[{"key":"A","text":"(A) unless"},{"key":"B","text":"(B) provided"},{"key":"C","text":"(C) whereas"},{"key":"D","text":"(D) lest"}],"correct":"D","translation":"Cố vấn pháp lý khuyên người phát ngôn tránh suy đoán về vụ kiện đang chờ xét xử, kẻo những phát ngôn như vậy bị diễn giải là sự thừa nhận trách nhiệm pháp lý.","explanation":"Liên từ 'lest' mang nghĩa 'kẻo mà, phòng khi' và đi với thức giả định ('such remarks be construed' dùng động từ nguyên mẫu 'be'). 'unless', 'whereas' và 'provided' không dùng thức giả định và sai quan hệ ngữ nghĩa.","vocab":[{"word":"litigation","pos":"n.","meaning":"vụ kiện tụng"},{"word":"lest","pos":"conj.","meaning":"kẻo mà, để tránh"},{"word":"construe","pos":"v.","meaning":"diễn giải, hiểu là"}]},{"id":"reading-lv6-test-1-q105","questionNumber":105,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 105 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"In the event of any inconsistency between this addendum and the master services agreement, the provisions of the master agreement shall _______ those of the addendum.","options":[{"key":"A","text":"(A) supersede"},{"key":"B","text":"(B) surmount"},{"key":"C","text":"(C) supplant"},{"key":"D","text":"(D) subordinate"}],"correct":"A","translation":"Trong trường hợp có bất kỳ sự mâu thuẫn nào giữa phụ lục này và hợp đồng dịch vụ khung, các điều khoản của hợp đồng khung sẽ có hiệu lực thay thế và cao hơn các điều khoản của phụ lục.","explanation":"'Supersede' là thuật ngữ pháp lý chuẩn mang nghĩa có giá trị pháp lý cao hơn hoặc thay thế hiệu lực của điều khoản khác. 'surmount' (vượt qua trở ngại), 'subordinate' (đặt ở vị trí thấp hơn — ngược chiều) và 'supplant' (chiếm chỗ, thường dùng cho con người/công nghệ) không hợp ngữ cảnh.","vocab":[{"word":"addendum","pos":"n.","meaning":"phụ lục bổ sung"},{"word":"supersede","pos":"v.","meaning":"thay thế hiệu lực, ưu tiên hơn"},{"word":"inconsistency","pos":"n.","meaning":"sự mâu thuẫn, không nhất quán"}]},{"id":"reading-lv6-test-1-q106","questionNumber":106,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 106 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"The compliance director insisted that every regional subsidiary _______ its data-retention schedule audited by an independent assessor prior to the fourth quarter.","options":[{"key":"A","text":"(A) has"},{"key":"B","text":"(B) have"},{"key":"C","text":"(C) had"},{"key":"D","text":"(D) would have"}],"correct":"B","translation":"Giám đốc tuân thủ kiên quyết yêu cầu mọi công ty con khu vực phải thu xếp cho lịch trình lưu giữ dữ liệu của mình được kiểm toán bởi một bên đánh giá độc lập trước quý bốn.","explanation":"Sau 'insisted that' phải dùng giả định cách (mandative subjunctive): động từ nguyên mẫu không 'to' cho mọi chủ ngữ, nên dùng 'have' trong cấu trúc 'have something done'. 'has', 'had' và 'would have' đều là dạng chia thì không đúng trong giả định cách.","vocab":[{"word":"subsidiary","pos":"n.","meaning":"công ty con"},{"word":"data-retention","pos":"n.","meaning":"việc lưu giữ dữ liệu"},{"word":"assessor","pos":"n.","meaning":"chuyên viên đánh giá"}]},{"id":"reading-lv6-test-1-q107","questionNumber":107,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 107 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"The redevelopment bid was withdrawn after independent surveyors determined that soil remediation at the coastal parcel would be _______ expensive.","options":[{"key":"A","text":"(A) tentatively"},{"key":"B","text":"(B) ostensibly"},{"key":"C","text":"(C) marginally"},{"key":"D","text":"(D) prohibitively"}],"correct":"D","translation":"Hồ sơ dự thầu tái phát triển đã bị rút lại sau khi các chuyên gia khảo sát độc lập xác định rằng việc xử lý ô nhiễm đất tại khu đất ven biển sẽ đắt đỏ đến mức không thể kham nổi.","explanation":"Cụm kết hợp từ 'prohibitively expensive' nghĩa là đắt đỏ tới mức ngăn cản không thể thực hiện dự án, khớp với kết quả 'bid was withdrawn'. 'tentatively' (tạm thời), 'ostensibly' (bề ngoài có vẻ) và 'marginally' (không đáng kể) đều không giải thích được việc rút thầu.","vocab":[{"word":"remediation","pos":"n.","meaning":"việc khắc phục, xử lý ô nhiễm"},{"word":"prohibitively","pos":"adv.","meaning":"đến mức không thể kham nổi"},{"word":"parcel","pos":"n.","meaning":"lô đất, khu đất"}]},{"id":"reading-lv6-test-1-q108","questionNumber":108,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 108 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"The consortium ratified a cross-licensing framework _______ participating laboratories may exchange proprietary test protocols without incurring royalty charges.","options":[{"key":"A","text":"(A) whose"},{"key":"B","text":"(B) which"},{"key":"C","text":"(C) whereby"},{"key":"D","text":"(D) whom"}],"correct":"C","translation":"Liên minh đã phê chuẩn một khuôn khổ cấp phép chéo, theo đó các phòng thí nghiệm tham gia có thể trao đổi các quy trình thử nghiệm độc quyền mà không phải chịu phí bản quyền.","explanation":"Mệnh đề phía sau ('participating laboratories may exchange proprietary test protocols') đã đủ chủ ngữ và tân ngữ nên cần trạng từ quan hệ mang nghĩa 'theo đó, bằng cách đó' là 'whereby'. 'which' thiếu giới từ đi kèm ('under/by which'), còn 'whose' và 'whom' sai cấu trúc.","vocab":[{"word":"consortium","pos":"n.","meaning":"liên minh, tập đoàn hợp tác"},{"word":"whereby","pos":"adv.","meaning":"theo đó, nhờ đó mà"},{"word":"royalty","pos":"n.","meaning":"tiền bản quyền"}]},{"id":"reading-lv6-test-1-q109","questionNumber":109,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 109 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"Had the clinical analytics team validated the underlying dataset last quarter, the regulatory submission _______ substantially fewer procedural objections today.","options":[{"key":"A","text":"(A) would face"},{"key":"B","text":"(B) would have faced"},{"key":"C","text":"(C) will have faced"},{"key":"D","text":"(D) had faced"}],"correct":"A","translation":"Nếu nhóm phân tích lâm sàng đã xác thực bộ dữ liệu nền vào quý trước thì hồ sơ trình cơ quan quản lý hôm nay sẽ gặp ít phản đối về thủ tục hơn đáng kể.","explanation":"Câu điều kiện hỗn hợp loại 3–2: mệnh đề giả định ở quá khứ ('Had ... validated ... last quarter'), nhưng hệ quả kéo dài đến hiện tại (dấu hiệu 'today'), nên mệnh đề chính dùng 'would + V nguyên mẫu' là 'would face'.","vocab":[{"word":"validate","pos":"v.","meaning":"xác thực, kiểm chứng"},{"word":"procedural","pos":"adj.","meaning":"thuộc về quy trình, thủ tục"},{"word":"submission","pos":"n.","meaning":"hồ sơ đệ trình"}]},{"id":"reading-lv6-test-1-q110","questionNumber":110,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 110 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"Although the logistics division's third-quarter operating margin improved markedly, it still _______ the benchmark established in the annual strategic plan.","options":[{"key":"A","text":"(A) stopped short of"},{"key":"B","text":"(B) fell short of"},{"key":"C","text":"(C) ran afoul of"},{"key":"D","text":"(D) made light of"}],"correct":"B","translation":"Mặc dù biên lợi nhuận hoạt động quý ba của bộ phận logistics đã cải thiện rõ rệt, nó vẫn không đạt ngưỡng chuẩn được thiết lập trong kế hoạch chiến lược hằng năm.","explanation":"'Fall short of' (quá khứ 'fell short of') mang nghĩa không đạt tới một mức tiêu chuẩn hay mục tiêu. 'stop short of' là dừng lại trước khi làm hành động nào đó; 'run afoul of' là vi phạm quy định; 'make light of' là xem nhẹ.","vocab":[{"word":"operating margin","pos":"n.","meaning":"biên lợi nhuận hoạt động"},{"word":"benchmark","pos":"n.","meaning":"ngưỡng chuẩn, chuẩn mực"},{"word":"markedly","pos":"adv.","meaning":"một cách rõ rệt"}]},{"id":"reading-lv6-test-1-q111","questionNumber":111,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 111 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"_______ the central bank to tighten credit conditions further next quarter, capital-intensive infrastructure projects would likely face prolonged refinancing delays.","options":[{"key":"A","text":"(A) Were"},{"key":"B","text":"(B) Had"},{"key":"C","text":"(C) Should"},{"key":"D","text":"(D) If"}],"correct":"A","translation":"Giả sử ngân hàng trung ương thắt chặt thêm các điều kiện tín dụng trong quý tới, các dự án hạ tầng thâm dụng vốn nhiều khả năng sẽ gặp chậm trễ kéo dài trong việc tái cấp vốn.","explanation":"Đảo ngữ câu điều kiện loại 2 diễn tả giả định ở tương lai: 'Were + S + to V, S + would + V'. 'Should' phải đi với động từ nguyên mẫu không 'to', 'Had' dùng với V3 cho loại 3, và 'If' không đi với 'to tighten' chưa chia thì.","vocab":[{"word":"capital-intensive","pos":"adj.","meaning":"thâm dụng vốn lớn"},{"word":"refinancing","pos":"n.","meaning":"việc tái cấp vốn"},{"word":"tighten","pos":"v.","meaning":"thắt chặt"}]},{"id":"reading-lv6-test-1-q112","questionNumber":112,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 112 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"The board acknowledged that frequent executive turnover is rarely _______ to long-term institutional stability, yet it declined to revise the compensation structure.","options":[{"key":"A","text":"(A) detrimental"},{"key":"B","text":"(B) impervious"},{"key":"C","text":"(C) tantamount"},{"key":"D","text":"(D) conducive"}],"correct":"D","translation":"Hội đồng quản trị thừa nhận rằng sự thay đổi nhân sự cấp cao thường xuyên hiếm khi có lợi cho sự ổn định lâu dài của tổ chức, thế nhưng họ vẫn từ chối sửa đổi cơ cấu đãi ngộ.","explanation":"Cả bốn tính từ đều đi với giới từ 'to', nhưng xét quan hệ tương phản với vế sau ('yet it declined to revise...'): thay đổi lãnh đạo liên tục hiếm khi có lợi ('conducive to') cho sự ổn định. 'detrimental to' (có hại cho) ngược logic với 'rarely', 'impervious to' (miễn nhiễm với) và 'tantamount to' (tương đương với) sai nghĩa.","vocab":[{"word":"conducive to","pos":"adj.","meaning":"có lợi cho, tạo điều kiện cho"},{"word":"turnover","pos":"n.","meaning":"tỷ lệ thay đổi nhân sự"},{"word":"institutional","pos":"adj.","meaning":"thuộc về tổ chức, thể chế"}]},{"id":"reading-lv6-test-1-q113","questionNumber":113,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 113 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"The incident report _______ to the regulator before the statutory deadline, yet the compliance team postponed its submission twice.","options":[{"key":"A","text":"(A) should have been submitted"},{"key":"B","text":"(B) should be submitted"},{"key":"C","text":"(C) must have been submitted"},{"key":"D","text":"(D) might have submitted"}],"correct":"A","translation":"Báo cáo sự cố lẽ ra đã phải được trình lên cơ quan quản lý trước hạn định luật định, vậy mà bộ phận tuân thủ đã hoãn việc nộp báo cáo tới hai lần.","explanation":"Cấu trúc 'should have been + V3' diễn tả nghĩa vụ trong quá khứ lẽ ra phải được thực hiện nhưng thực tế không xảy ra (bị hoãn hai lần). 'should be submitted' chỉ nói về hiện tại/tương lai, còn 'must have been submitted' suy đoán rằng việc đó đã được nộp rồi — trái vế sau.","vocab":[{"word":"statutory","pos":"adj.","meaning":"theo luật định"},{"word":"regulator","pos":"n.","meaning":"cơ quan quản lý"},{"word":"postpone","pos":"v.","meaning":"hoãn lại"}]},{"id":"reading-lv6-test-1-q114","questionNumber":114,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 114 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"_______ mounting pressure from activist shareholders to defer the vote, the board proceeded with the divestiture of its underperforming subsidiary.","options":[{"key":"A","text":"(A) Although"},{"key":"B","text":"(B) Notwithstanding"},{"key":"C","text":"(C) Inasmuch as"},{"key":"D","text":"(D) Provided that"}],"correct":"B","translation":"Bất chấp áp lực ngày càng tăng từ các cổ đông tích cực đòi hoãn bỏ phiếu, hội đồng quản trị vẫn tiến hành thoái vốn khỏi công ty con hoạt động kém hiệu quả.","explanation":"Phía sau chỗ trống là một cụm danh từ ('mounting pressure from activist shareholders to defer the vote') không chứa động từ chia thì, nên cần giới từ phức 'Notwithstanding' (bất chấp). 'Although', 'Inasmuch as' và 'Provided that' đều là liên từ bắt buộc theo sau là mệnh đề đầy đủ.","vocab":[{"word":"notwithstanding","pos":"prep.","meaning":"bất chấp, mặc dù"},{"word":"divestiture","pos":"n.","meaning":"việc thoái vốn, bán bớt tài sản"},{"word":"activist shareholder","pos":"n.","meaning":"cổ đông tích cực can thiệp quản trị"}]},{"id":"reading-lv6-test-1-q115","questionNumber":115,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 115 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"Before executing the joint-venture charter, legal counsel sought to _______ any ambiguity regarding each partner's ownership of jointly developed patents.","options":[{"key":"A","text":"(A) perpetuate"},{"key":"B","text":"(B) precipitate"},{"key":"C","text":"(C) preclude"},{"key":"D","text":"(D) protract"}],"correct":"C","translation":"Trước khi ký kết điều lệ liên doanh, cố vấn pháp lý tìm cách loại trừ trước mọi sự mơ hồ liên quan đến quyền sở hữu của mỗi đối tác đối với các bằng sáng chế đồng phát triển.","explanation":"'Preclude' mang nghĩa ngăn chặn từ trước hoặc loại bỏ khả năng xảy ra của điều gì ('preclude ambiguity'). 'perpetuate' (duy trì mãi), 'precipitate' (làm bùng phát bất ngờ) và 'protract' (kéo dài lê thê) đều trái với mục tiêu làm rõ văn bản pháp lý.","vocab":[{"word":"preclude","pos":"v.","meaning":"ngăn chặn từ trước, loại trừ"},{"word":"ambiguity","pos":"n.","meaning":"sự mơ hồ, nhập nhằng"},{"word":"charter","pos":"n.","meaning":"điều lệ, hiến chương"}]},{"id":"reading-lv6-test-1-q116","questionNumber":116,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 116 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"The manufacturer agreed to maintain fixed unit pricing for three consecutive years _______ that quarterly order volumes remain above the contractual minimum.","options":[{"key":"A","text":"(A) whereas"},{"key":"B","text":"(B) provided"},{"key":"C","text":"(C) albeit"},{"key":"D","text":"(D) lest"}],"correct":"B","translation":"Nhà sản xuất đồng ý duy trì đơn giá cố định trong ba năm liên tiếp với điều kiện khối lượng đơn hàng hằng quý vẫn duy trì trên mức tối thiểu theo hợp đồng.","explanation":"'Provided that + mệnh đề' mang nghĩa 'với điều kiện là'. 'whereas' diễn tả tương phản, 'lest' là 'kẻo mà', còn 'albeit' là 'mặc dù' và không đi với mệnh đề bắt đầu bằng 'that'.","vocab":[{"word":"provided that","pos":"conj.","meaning":"với điều kiện là"},{"word":"consecutive","pos":"adj.","meaning":"liên tiếp"},{"word":"contractual","pos":"adj.","meaning":"theo hợp đồng"}]},{"id":"reading-lv6-test-1-q117","questionNumber":117,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 117 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"The biotechnology startup lacked sufficient working capital to sustain existing laboratory trials, _______ finance an unbudgeted expansion into Southeast Asia.","options":[{"key":"A","text":"(A) much less"},{"key":"B","text":"(B) all the more"},{"key":"C","text":"(C) none the less"},{"key":"D","text":"(D) even so"}],"correct":"A","translation":"Công ty khởi nghiệp công nghệ sinh học thiếu vốn lưu động để duy trì các thử nghiệm phòng thí nghiệm hiện tại, chứ chưa nói đến việc tài trợ cho kế hoạch mở rộng ngoài ngân sách sang Đông Nam Á.","explanation":"Sau mệnh đề phủ định hoặc mang nghĩa thiếu hụt ('lacked sufficient working capital'), dùng 'much less + V nguyên mẫu' để nhấn mạnh điều thứ hai càng bất khả thi hơn ('chứ chưa nói đến'). Các cụm còn lại không dùng trong cấu trúc tăng tiến phủ định này.","vocab":[{"word":"working capital","pos":"n.","meaning":"vốn lưu động"},{"word":"much less","pos":"phr.","meaning":"chứ chưa nói đến, huống hồ là"},{"word":"unbudgeted","pos":"adj.","meaning":"ngoài dự toán ngân sách"}]},{"id":"reading-lv6-test-1-q118","questionNumber":118,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 118 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"By the time the external auditors from the regional office arrive next month, the intercompany reconciliation records _______ for every subsidiary.","options":[{"key":"A","text":"(A) will prepare"},{"key":"B","text":"(B) will be preparing"},{"key":"C","text":"(C) will have prepared"},{"key":"D","text":"(D) will have been prepared"}],"correct":"D","translation":"Tính đến khi các kiểm toán viên bên ngoài từ văn phòng khu vực đến vào tháng tới, hồ sơ đối chiếu nội bộ giữa các công ty thành viên sẽ đã được lập xong cho mọi công ty con.","explanation":"Mốc 'By the time + hiện tại đơn (arrive)' đòi hỏi mệnh đề chính chia thì tương lai hoàn thành; chủ ngữ 'records' chịu tác động nên dùng dạng bị động 'will have been prepared'.","vocab":[{"word":"intercompany","pos":"adj.","meaning":"nội bộ giữa các công ty cùng tập đoàn"},{"word":"reconciliation","pos":"n.","meaning":"việc đối chiếu số liệu"},{"word":"external auditor","pos":"n.","meaning":"kiểm toán viên độc lập bên ngoài"}]},{"id":"reading-lv6-test-1-q119","questionNumber":119,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 119 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"The revised procurement framework is intended not only to streamline tender evaluations but also _______ supplier accountability across all operating units.","options":[{"key":"A","text":"(A) strengthening"},{"key":"B","text":"(B) strengthen"},{"key":"C","text":"(C) to strengthen"},{"key":"D","text":"(D) having strengthened"}],"correct":"C","translation":"Khung quy trình thu mua sửa đổi không chỉ nhằm tinh giản khâu đánh giá hồ sơ thầu mà còn tăng cường trách nhiệm giải trình của nhà cung cấp trên mọi đơn vị vận hành.","explanation":"Cấu trúc 'not only ... but also ...' đòi hỏi hai vế song song cùng hình thức ngữ pháp. Vế trước là 'to streamline' (nguyên mẫu có 'to') nên vế sau bắt buộc là 'to strengthen'.","vocab":[{"word":"streamline","pos":"v.","meaning":"tinh giản, hợp lý hóa"},{"word":"tender evaluation","pos":"n.","meaning":"đánh giá hồ sơ dự thầu"},{"word":"accountability","pos":"n.","meaning":"trách nhiệm giải trình"}]},{"id":"reading-lv6-test-1-q120","questionNumber":120,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 120 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"_______ the proposed acquisition failing to obtain antitrust clearance before year-end, either party may invoke the termination clause without penalty.","options":[{"key":"A","text":"(A) In the event of"},{"key":"B","text":"(B) On condition that"},{"key":"C","text":"(C) In the event that"},{"key":"D","text":"(D) Assuming that"}],"correct":"A","translation":"Trong trường hợp thương vụ mua lại dự kiến không giành được chấp thuận chống độc quyền trước cuối năm, một trong hai bên có thể viện dẫn điều khoản chấm dứt mà không bị phạt.","explanation":"Phía sau chỗ trống là cụm danh động từ ('the proposed acquisition failing...'), không có động từ chia thì, nên phải dùng giới từ phức 'In the event of'. Ba lựa chọn chứa 'that' đều là liên từ đòi hỏi mệnh đề hoàn chỉnh.","vocab":[{"word":"antitrust clearance","pos":"n.","meaning":"chấp thuận chống độc quyền"},{"word":"invoke","pos":"v.","meaning":"viện dẫn (điều khoản)"},{"word":"in the event of","pos":"prep.","meaning":"trong trường hợp"}]},{"id":"reading-lv6-test-1-q121","questionNumber":121,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 121 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"Not until the second quarter of the fiscal year _______ any measurable indication of recovery in the domestic retail segment.","options":[{"key":"A","text":"(A) management did observe"},{"key":"B","text":"(B) had management observed"},{"key":"C","text":"(C) did management observe"},{"key":"D","text":"(D) observed management"}],"correct":"C","translation":"Mãi đến quý hai của năm tài chính, ban điều hành mới ghi nhận được dấu hiệu phục hồi rõ rệt nào đó ở phân khúc bán lẻ trong nước.","explanation":"Khi 'Not until + trạng ngữ thời gian' đứng đầu câu, mệnh đề chính bắt buộc đảo ngữ dạng quá khứ đơn: 'did + S + V nguyên mẫu' ('did management observe'). 'observed management' đảo sai động từ chính, 'had management observed' sai phối hợp thì cho sự kiện xảy ra sau mốc 'until'.","vocab":[{"word":"measurable","pos":"adj.","meaning":"có thể đo lường, rõ rệt"},{"word":"indication","pos":"n.","meaning":"dấu hiệu"},{"word":"retail segment","pos":"n.","meaning":"phân khúc bán lẻ"}]},{"id":"reading-lv6-test-1-q122","questionNumber":122,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 122 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"Because the regulator's interim bulletin left several technical definitions ambiguous, industry associations requested formal _______ prior to the compliance deadline.","options":[{"key":"A","text":"(A) ratification"},{"key":"B","text":"(B) litigation"},{"key":"C","text":"(C) clarification"},{"key":"D","text":"(D) proliferation"}],"correct":"C","translation":"Vì bản tin tạm thời của cơ quan quản lý để lại nhiều định nghĩa kỹ thuật còn mơ hồ, các hiệp hội ngành đã yêu cầu được làm rõ chính thức trước hạn chót tuân thủ.","explanation":"Khi định nghĩa bị 'ambiguous' (mơ hồ), hành động hợp lý là yêu cầu 'clarification' (sự làm rõ). 'ratification' (sự phê chuẩn hiệp ước), 'litigation' (kiện tụng) và 'proliferation' (sự gia tăng nhanh) không khớp ngữ cảnh.","vocab":[{"word":"interim","pos":"adj.","meaning":"tạm thời, giữa kỳ"},{"word":"clarification","pos":"n.","meaning":"sự làm rõ, giải thích chính thức"},{"word":"ratification","pos":"n.","meaning":"sự phê chuẩn"}]},{"id":"reading-lv6-test-1-q123","questionNumber":123,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 123 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"European operations surpassed annual operating-margin targets by four percentage points, _______ North American branches lagged behind projections due to freight spikes.","options":[{"key":"A","text":"(A) thereby"},{"key":"B","text":"(B) whereas"},{"key":"C","text":"(C) inasmuch as"},{"key":"D","text":"(D) consequently"}],"correct":"B","translation":"Hoạt động tại châu Âu vượt mục tiêu biên lợi nhuận hằng năm bốn điểm phần trăm, trong khi các chi nhánh Bắc Mỹ tụt lại sau dự báo do chi phí vận tải tăng vọt.","explanation":"'Whereas' nối hai mệnh đề mang ý nghĩa đối lập trực tiếp (vượt mục tiêu >< tụt lại sau dự báo). 'thereby' (nhờ đó), 'inasmuch as' (bởi vì) và 'consequently' (kết quả là) không diễn tả quan hệ tương phản.","vocab":[{"word":"whereas","pos":"conj.","meaning":"trong khi (đối lập)"},{"word":"lag behind","pos":"phr. v.","meaning":"tụt lại phía sau"},{"word":"percentage point","pos":"n.","meaning":"điểm phần trăm"}]},{"id":"reading-lv6-test-1-q124","questionNumber":124,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 124 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"The boutique consultancy _______ the cross-border market-entry blueprint has cautioned that tariff volatility could defer deployment by two quarters.","options":[{"key":"A","text":"(A) drafting"},{"key":"B","text":"(B) to draft"},{"key":"C","text":"(C) having been drafted"},{"key":"D","text":"(D) drafted"}],"correct":"A","translation":"Công ty tư vấn chuyên biệt đang soạn thảo kế hoạch thâm nhập thị trường xuyên biên giới đã cảnh báo rằng biến động thuế quan có thể làm chậm việc triển khai hai quý.","explanation":"Rút gọn mệnh đề quan hệ ở thể chủ động ('which is drafting'): dùng hiện tại phân từ 'drafting' vì chủ thể 'the consultancy' trực tiếp soạn thảo bản kế hoạch. 'drafted' và 'having been drafted' mang nghĩa bị động (sai logic).","vocab":[{"word":"boutique consultancy","pos":"n.","meaning":"công ty tư vấn chuyên sâu"},{"word":"volatility","pos":"n.","meaning":"sự biến động khó lường"},{"word":"defer","pos":"v.","meaning":"hoãn lại, lùi lại"}]},{"id":"reading-lv6-test-1-q125","questionNumber":125,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 125 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"So committed _______ the organization to decarbonizing its freight corridor that it renegotiated every carrier contract within a single fiscal year.","options":[{"key":"A","text":"(A) would"},{"key":"B","text":"(B) has"},{"key":"C","text":"(C) did"},{"key":"D","text":"(D) was"}],"correct":"D","translation":"Tổ chức cam kết mạnh mẽ với việc khử carbon cho hành lang vận tải đến mức đã đàm phán lại toàn bộ hợp đồng với các hãng vận chuyển chỉ trong một năm tài chính.","explanation":"Cấu trúc đảo ngữ nhấn mạnh 'So + tính từ + động từ to be + S + that ...': 'So committed was the organization ...'. 'has' thiếu 'been', 'did' không đi với tính từ 'committed', và 'would' sai ý nghĩa sự kiện đã hoàn tất ('renegotiated').","vocab":[{"word":"decarbonize","pos":"v.","meaning":"giảm/khử phát thải carbon"},{"word":"corridor","pos":"n.","meaning":"hành lang (vận tải)"},{"word":"renegotiate","pos":"v.","meaning":"đàm phán lại"}]},{"id":"reading-lv6-test-1-q126","questionNumber":126,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 126 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"_______ capital expenditure has already exceeded the approved ceiling by eighteen percent, the finance committee is unlikely to sanction supplementary outlays.","options":[{"key":"A","text":"(A) Notwithstanding that"},{"key":"B","text":"(B) Even so"},{"key":"C","text":"(C) For fear that"},{"key":"D","text":"(D) Given that"}],"correct":"D","translation":"Xét thấy chi tiêu vốn đã vượt mức trần được phê duyệt mười tám phần trăm, ủy ban tài chính khó có khả năng chấp thuận thêm các khoản chi bổ sung.","explanation":"'Given that + mệnh đề' mang nghĩa 'xét thấy rằng', nêu cơ sở dẫn đến nhận định ở mệnh đề chính. 'Notwithstanding that' (mặc dù) trái logic, 'For fear that' (vì sợ rằng) sai hướng thời gian, và 'Even so' là trạng từ liên kết chứ không nối hai mệnh đề.","vocab":[{"word":"capital expenditure","pos":"n.","meaning":"chi tiêu vốn đầu tư"},{"word":"sanction","pos":"v.","meaning":"phê chuẩn, chấp thuận"},{"word":"outlay","pos":"n.","meaning":"khoản chi phí bỏ ra"}]},{"id":"reading-lv6-test-1-q127","questionNumber":127,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 127 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"The task force's long-term demand projections were widely dismissed as _______ because they extrapolated from an unrepresentative sample of peak-season orders.","options":[{"key":"A","text":"(A) untenable"},{"key":"B","text":"(B) indispensable"},{"key":"C","text":"(C) immutable"},{"key":"D","text":"(D) inadvertent"}],"correct":"A","translation":"Các dự báo nhu cầu dài hạn của nhóm đặc nhiệm bị bác bỏ rộng rãi là không thể đứng vững vì chúng ngoại suy từ một mẫu đơn hàng mùa cao điểm thiếu tính đại diện.","explanation":"'Untenable' nghĩa là không thể bảo vệ hay đứng vững về mặt lập luận/logic. 'immutable' (bất biến), 'indispensable' (không thể thiếu) và 'inadvertent' (vô ý) không phù hợp để bác bỏ độ tin cậy của một dự báo.","vocab":[{"word":"untenable","pos":"adj.","meaning":"không thể đứng vững, thiếu cơ sở"},{"word":"unrepresentative","pos":"adj.","meaning":"không mang tính đại diện"},{"word":"dismiss","pos":"v.","meaning":"bác bỏ, gạt bỏ"}]},{"id":"reading-lv6-test-1-q128","questionNumber":128,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 128 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"The freight forwarder neither notified the importer of the customs inspection hold, nor _______ it absorb the resulting demurrage charges.","options":[{"key":"A","text":"(A) had"},{"key":"B","text":"(B) was"},{"key":"C","text":"(C) did"},{"key":"D","text":"(D) has"}],"correct":"C","translation":"Đơn vị giao nhận vận tải không thông báo cho nhà nhập khẩu về lệnh giữ hàng kiểm tra hải quan, và cũng không chịu phần phí lưu bãi phát sinh.","explanation":"Mở đầu mệnh đề thứ hai bằng 'nor' bắt buộc đảo trợ động từ lên trước chủ ngữ. Vế trước ở thì quá khứ đơn ('notified') và động từ sau là nguyên mẫu ('absorb') nên trợ động từ phải là 'did'.","vocab":[{"word":"freight forwarder","pos":"n.","meaning":"đơn vị giao nhận vận tải"},{"word":"demurrage","pos":"n.","meaning":"phí lưu bãi, lưu container"},{"word":"absorb","pos":"v.","meaning":"gánh chịu (chi phí)"}]},{"id":"reading-lv6-test-1-q129","questionNumber":129,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 129 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"Several cost-containment measures _______ in the interim sustainability review were deferred until the automated sorting facility became fully operational.","options":[{"key":"A","text":"(A) advocating"},{"key":"B","text":"(B) advocated"},{"key":"C","text":"(C) having advocated"},{"key":"D","text":"(D) to advocate"}],"correct":"B","translation":"Một số biện pháp kiềm chế chi phí được đề xuất trong báo cáo đánh giá bền vững giữa kỳ đã bị hoãn lại cho đến khi cơ sở phân loại tự động đi vào vận hành hoàn chỉnh.","explanation":"Mệnh đề quan hệ bị động rút gọn ('which were advocated in the interim review'): dùng quá khứ phân từ 'advocated' bổ nghĩa cho 'measures'. Ba lựa chọn còn lại đều mang nghĩa chủ động hoặc chỉ mục đích.","vocab":[{"word":"cost-containment","pos":"n.","meaning":"việc kiểm soát, kiềm chế chi phí"},{"word":"advocate","pos":"v.","meaning":"đề xuất, ủng hộ"},{"word":"operational","pos":"adj.","meaning":"đi vào hoạt động"}]},{"id":"reading-lv6-test-1-q130","questionNumber":130,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 5","partNumber":5,"partName":"Part 5: Hoàn thành câu (Incomplete Sentences)","title":"Test 01 (Level 6) • Câu 130 (Part 5: Hoàn thành câu)","passageTitle":"","passageHtml":"","questionText":"Had the audit committee _______ the revised compliance framework before the fiscal year ended, the accounting discrepancies would never have remained undetected.","options":[{"key":"A","text":"(A) had scrutinized"},{"key":"B","text":"(B) scrutinized"},{"key":"C","text":"(C) scrutinizing"},{"key":"D","text":"(D) been scrutinized"}],"correct":"B","translation":"Nếu ủy ban kiểm toán đã rà soát kỹ khung tuân thủ sửa đổi trước khi năm tài chính khép lại thì các sai lệch kế toán đã không bao giờ bị bỏ sót không phát hiện.","explanation":"Đảo ngữ điều kiện loại 3: 'Had + S + V3/ed'. Do 'Had' đã đứng đầu câu làm trợ động từ và chủ ngữ 'the audit committee' thực hiện hành động rà soát, nên cần quá khứ phân từ chủ động 'scrutinized' (không lặp 'had' và không dùng bị động 'been scrutinized').","vocab":[{"word":"scrutinize","pos":"v.","meaning":"rà soát kỹ lưỡng"},{"word":"discrepancy","pos":"n.","meaning":"sự sai lệch"},{"word":"undetected","pos":"adj.","meaning":"không bị phát hiện"}]},{"id":"reading-lv6-test-1-q131","questionNumber":131,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 6","partNumber":6,"partName":"Part 6: Hoàn thành đoạn văn (Text Completion)","title":"Test 01 (Level 6) • Câu 131 (Part 6: Hoàn thành đoạn văn)","passageTitle":"Questions 131-134 refer to the following memorandum:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">MEMORANDUM</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">To: All Regional Operations Managers<br>From: Office of the Chief Operating Officer<br>Re: Revised Supplier Onboarding Protocol</p><p class=\"mt-2\">Beginning 1 March, every regional office will be required to <strong>[131]</strong> the revised supplier onboarding protocol, which stipulates that each new vendor be assessed jointly by the procurement and compliance units before any purchase order is issued. <strong>[132]</strong> The protocol further requires that contracts exceeding $250,000 undergo a second review by the legal department, whereas agreements below that threshold may be approved locally. Managers should anticipate that this additional scrutiny will inevitably <strong>[133]</strong> a more protracted approval cycle for first-time vendors, yet it is expected to mitigate the risk of supplier default. <strong>[134]</strong> these transitional costs, the revised protocol is expected to shorten the average onboarding period once duplicate reviews are eliminated. Failure to observe the stipulated procedures may result in the suspension of purchasing privileges.</p></div>","questionText":"Select the best answer to complete blank [131].","options":[{"key":"A","text":"(A) attest to"},{"key":"B","text":"(B) allude to"},{"key":"C","text":"(C) adhere to"},{"key":"D","text":"(D) aspire to"}],"correct":"C","translation":"Kể từ ngày 1 tháng 3, mọi văn phòng khu vực sẽ phải tuân thủ quy trình tiếp nhận nhà cung cấp đã sửa đổi, trong đó quy định rằng mỗi nhà cung cấp mới phải được đánh giá chung bởi bộ phận thu mua và bộ phận tuân thủ trước khi bất kỳ đơn đặt hàng nào được phát hành.","explanation":"Cụm động từ 'adhere to + quy trình/quy định' mang nghĩa tuân thủ chặt chẽ, khớp với 'stipulates' và câu kết 'Failure to observe the stipulated procedures'. 'attest to' (chứng thực), 'allude to' (ám chỉ) và 'aspire to' (hướng tới, khao khát) đều sai sắc thái nghĩa.","vocab":[{"word":"adhere to","pos":"phr. v.","meaning":"tuân thủ chặt chẽ"},{"word":"stipulate","pos":"v.","meaning":"quy định rõ ràng"},{"word":"procurement","pos":"n.","meaning":"việc thu mua"}]},{"id":"reading-lv6-test-1-q132","questionNumber":132,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 6","partNumber":6,"partName":"Part 6: Hoàn thành đoạn văn (Text Completion)","title":"Test 01 (Level 6) • Câu 132 (Part 6: Hoàn thành đoạn văn)","passageTitle":"Questions 131-134 refer to the following memorandum:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">MEMORANDUM</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">To: All Regional Operations Managers<br>From: Office of the Chief Operating Officer<br>Re: Revised Supplier Onboarding Protocol</p><p class=\"mt-2\">Beginning 1 March, every regional office will be required to <strong>[131]</strong> the revised supplier onboarding protocol, which stipulates that each new vendor be assessed jointly by the procurement and compliance units before any purchase order is issued. <strong>[132]</strong> The protocol further requires that contracts exceeding $250,000 undergo a second review by the legal department, whereas agreements below that threshold may be approved locally. Managers should anticipate that this additional scrutiny will inevitably <strong>[133]</strong> a more protracted approval cycle for first-time vendors, yet it is expected to mitigate the risk of supplier default. <strong>[134]</strong> these transitional costs, the revised protocol is expected to shorten the average onboarding period once duplicate reviews are eliminated. Failure to observe the stipulated procedures may result in the suspension of purchasing privileges.</p></div>","questionText":"Select the sentence that best completes blank [132].","options":[{"key":"A","text":"(A) Once a purchase order has been issued, both units must conduct an annual audit of the vendor's tax filings."},{"key":"B","text":"(B) Regional managers may nevertheless authorize expedited purchases above that figure without consulting compliance staff."},{"key":"C","text":"(C) This joint assessment replaces the separate reviews that the two units previously conducted in isolation."},{"key":"D","text":"(D) Because the legal department previously oversaw every vendor application, its staff will now delegate routine checks to regional buyers."}],"correct":"C","translation":"Việc đánh giá chung này thay thế những cuộc đánh giá riêng rẽ mà hai bộ phận trước đây thực hiện một cách độc lập.","explanation":"Câu trước nêu yêu cầu 'assessed jointly by the procurement and compliance units', còn câu sau mở rộng thêm 'further requires that contracts exceeding $250,000 undergo a second review by the legal department'. Câu C nối trực tiếp cụm 'This joint assessment' với 'assessed jointly' ở câu trước. A sai trình tự (đang nói quy trình trước khi phát hành PO và 'both units' không dẫn được vào 'legal department'); B dùng đại từ 'that figure' khi mốc $250,000 chưa được nhắc tới và mâu thuẫn với câu sau; D mâu thuẫn trực tiếp với việc pháp chế thực hiện vòng rà soát thứ hai.","vocab":[{"word":"joint assessment","pos":"phrase","meaning":"đánh giá chung"},{"word":"in isolation","pos":"phrase","meaning":"một cách riêng lẻ, độc lập"},{"word":"vendor","pos":"n.","meaning":"nhà cung cấp"}]},{"id":"reading-lv6-test-1-q133","questionNumber":133,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 6","partNumber":6,"partName":"Part 6: Hoàn thành đoạn văn (Text Completion)","title":"Test 01 (Level 6) • Câu 133 (Part 6: Hoàn thành đoạn văn)","passageTitle":"Questions 131-134 refer to the following memorandum:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">MEMORANDUM</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">To: All Regional Operations Managers<br>From: Office of the Chief Operating Officer<br>Re: Revised Supplier Onboarding Protocol</p><p class=\"mt-2\">Beginning 1 March, every regional office will be required to <strong>[131]</strong> the revised supplier onboarding protocol, which stipulates that each new vendor be assessed jointly by the procurement and compliance units before any purchase order is issued. <strong>[132]</strong> The protocol further requires that contracts exceeding $250,000 undergo a second review by the legal department, whereas agreements below that threshold may be approved locally. Managers should anticipate that this additional scrutiny will inevitably <strong>[133]</strong> a more protracted approval cycle for first-time vendors, yet it is expected to mitigate the risk of supplier default. <strong>[134]</strong> these transitional costs, the revised protocol is expected to shorten the average onboarding period once duplicate reviews are eliminated. Failure to observe the stipulated procedures may result in the suspension of purchasing privileges.</p></div>","questionText":"Select the best answer to complete blank [133].","options":[{"key":"A","text":"(A) preclude"},{"key":"B","text":"(B) forestall"},{"key":"C","text":"(C) waive"},{"key":"D","text":"(D) entail"}],"correct":"D","translation":"Các quản lý nên lường trước rằng sự giám sát bổ sung này chắc chắn sẽ kéo theo một chu kỳ phê duyệt kéo dài hơn đối với những nhà cung cấp lần đầu, nhưng nó được kỳ vọng sẽ giảm thiểu rủi ro nhà cung cấp vỡ nợ.","explanation":"Động từ 'entail' mang nghĩa tất yếu kéo theo hoặc đòi hỏi một hệ quả đi kèm ('will inevitably entail a more protracted approval cycle'). 'preclude' (ngăn chặn từ trước), 'forestall' (chặn đứng trước) và 'waive' (miễn bỏ) đều trái với nghĩa quy trình bị kéo dài hơn.","vocab":[{"word":"entail","pos":"v.","meaning":"kéo theo, đòi hỏi"},{"word":"protracted","pos":"adj.","meaning":"kéo dài"},{"word":"mitigate","pos":"v.","meaning":"giảm thiểu"}]},{"id":"reading-lv6-test-1-q134","questionNumber":134,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 6","partNumber":6,"partName":"Part 6: Hoàn thành đoạn văn (Text Completion)","title":"Test 01 (Level 6) • Câu 134 (Part 6: Hoàn thành đoạn văn)","passageTitle":"Questions 131-134 refer to the following memorandum:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">MEMORANDUM</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">To: All Regional Operations Managers<br>From: Office of the Chief Operating Officer<br>Re: Revised Supplier Onboarding Protocol</p><p class=\"mt-2\">Beginning 1 March, every regional office will be required to <strong>[131]</strong> the revised supplier onboarding protocol, which stipulates that each new vendor be assessed jointly by the procurement and compliance units before any purchase order is issued. <strong>[132]</strong> The protocol further requires that contracts exceeding $250,000 undergo a second review by the legal department, whereas agreements below that threshold may be approved locally. Managers should anticipate that this additional scrutiny will inevitably <strong>[133]</strong> a more protracted approval cycle for first-time vendors, yet it is expected to mitigate the risk of supplier default. <strong>[134]</strong> these transitional costs, the revised protocol is expected to shorten the average onboarding period once duplicate reviews are eliminated. Failure to observe the stipulated procedures may result in the suspension of purchasing privileges.</p></div>","questionText":"Select the best answer to complete blank [134].","options":[{"key":"A","text":"(A) In lieu of"},{"key":"B","text":"(B) Pursuant to"},{"key":"C","text":"(C) Notwithstanding"},{"key":"D","text":"(D) By virtue of"}],"correct":"C","translation":"Bất chấp những chi phí chuyển tiếp này, quy trình sửa đổi được kỳ vọng sẽ rút ngắn thời gian tiếp nhận trung bình khi các cuộc đánh giá trùng lặp được loại bỏ.","explanation":"'Notwithstanding + cụm danh từ' mang nghĩa 'bất chấp, mặc dù', thể hiện sự tương phản giữa chi phí chuyển đổi ban đầu và lợi ích rút ngắn thời gian về sau. 'Pursuant to' (chiếu theo), 'In lieu of' (thay cho) và 'By virtue of' (nhờ vào) đều không diễn tả quan hệ nhượng bộ.","vocab":[{"word":"notwithstanding","pos":"prep.","meaning":"bất chấp, dù"},{"word":"transitional","pos":"adj.","meaning":"mang tính chuyển tiếp"},{"word":"duplicate","pos":"adj.","meaning":"trùng lặp"}]},{"id":"reading-lv6-test-1-q135","questionNumber":135,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 6","partNumber":6,"partName":"Part 6: Hoàn thành đoạn văn (Text Completion)","title":"Test 01 (Level 6) • Câu 135 (Part 6: Hoàn thành đoạn văn)","passageTitle":"Questions 135-138 refer to the following excerpt from an annual report:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">EXCERPT FROM THE ANNUAL SUSTAINABILITY REPORT</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">In light of the commitments made at last year's shareholder assembly, the company has undertaken a comprehensive review of emissions across its supply chain. The board has stipulated that, by the end of 2027, every tier-one supplier must disclose independently verified emissions data, <strong>[135]</strong> it operates in a jurisdiction with less stringent reporting requirements. Where such data cannot be obtained, the supplier will be required to <strong>[136]</strong> an independent audit at its own expense. <strong>[137]</strong> The review also found that logistics accounted for nearly two-thirds of the group's carbon footprint, a proportion that management considers untenable over the long term. Approval of the retrofit programme remains <strong>[138]</strong> on the outcome of an independent cost-benefit analysis, which the board expects to commission in the second quarter.</p></div>","questionText":"Select the best answer to complete blank [135].","options":[{"key":"A","text":"(A) provided that"},{"key":"B","text":"(B) even though"},{"key":"C","text":"(C) inasmuch as"},{"key":"D","text":"(D) so that"}],"correct":"B","translation":"Hội đồng quản trị đã quy định rằng đến cuối năm 2027, mọi nhà cung cấp cấp một phải công bố dữ liệu phát thải được kiểm chứng độc lập, ngay cả khi họ hoạt động tại một khu vực pháp lý có yêu cầu báo cáo ít nghiêm ngặt hơn.","explanation":"Mệnh đề phụ nêu hoàn cảnh tương phản (luật sở tại ít nghiêm ngặt hơn nhưng nhà cung cấp vẫn phải công bố dữ liệu), nên cần liên từ nhượng bộ 'even though'. 'provided that' (với điều kiện là), 'inasmuch as' (bởi vì) và 'so that' (để mà) đều sai quan hệ logic.","vocab":[{"word":"tier-one supplier","pos":"n.","meaning":"nhà cung cấp cấp một"},{"word":"stringent","pos":"adj.","meaning":"nghiêm ngặt"},{"word":"jurisdiction","pos":"n.","meaning":"khu vực tài phán, phạm vi pháp lý"}]},{"id":"reading-lv6-test-1-q136","questionNumber":136,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 6","partNumber":6,"partName":"Part 6: Hoàn thành đoạn văn (Text Completion)","title":"Test 01 (Level 6) • Câu 136 (Part 6: Hoàn thành đoạn văn)","passageTitle":"Questions 135-138 refer to the following excerpt from an annual report:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">EXCERPT FROM THE ANNUAL SUSTAINABILITY REPORT</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">In light of the commitments made at last year's shareholder assembly, the company has undertaken a comprehensive review of emissions across its supply chain. The board has stipulated that, by the end of 2027, every tier-one supplier must disclose independently verified emissions data, <strong>[135]</strong> it operates in a jurisdiction with less stringent reporting requirements. Where such data cannot be obtained, the supplier will be required to <strong>[136]</strong> an independent audit at its own expense. <strong>[137]</strong> The review also found that logistics accounted for nearly two-thirds of the group's carbon footprint, a proportion that management considers untenable over the long term. Approval of the retrofit programme remains <strong>[138]</strong> on the outcome of an independent cost-benefit analysis, which the board expects to commission in the second quarter.</p></div>","questionText":"Select the best answer to complete blank [136].","options":[{"key":"A","text":"(A) undergo"},{"key":"B","text":"(B) underlie"},{"key":"C","text":"(C) undermine"},{"key":"D","text":"(D) underwrite"}],"correct":"A","translation":"Trường hợp không thể có được dữ liệu đó, nhà cung cấp sẽ phải trải qua một cuộc kiểm toán độc lập với chi phí của chính mình.","explanation":"Cụm cố định 'undergo an audit' nghĩa là trải qua/được kiểm toán. 'undermine' (làm suy yếu), 'underlie' (nằm bên dưới, là cơ sở của) và 'underwrite' (bảo lãnh) đều không kết hợp được với tân ngữ 'an audit'.","vocab":[{"word":"undergo","pos":"v.","meaning":"trải qua"},{"word":"audit","pos":"n.","meaning":"cuộc kiểm toán"},{"word":"at its own expense","pos":"phrase","meaning":"bằng chi phí của chính mình"}]},{"id":"reading-lv6-test-1-q137","questionNumber":137,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 6","partNumber":6,"partName":"Part 6: Hoàn thành đoạn văn (Text Completion)","title":"Test 01 (Level 6) • Câu 137 (Part 6: Hoàn thành đoạn văn)","passageTitle":"Questions 135-138 refer to the following excerpt from an annual report:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">EXCERPT FROM THE ANNUAL SUSTAINABILITY REPORT</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">In light of the commitments made at last year's shareholder assembly, the company has undertaken a comprehensive review of emissions across its supply chain. The board has stipulated that, by the end of 2027, every tier-one supplier must disclose independently verified emissions data, <strong>[135]</strong> it operates in a jurisdiction with less stringent reporting requirements. Where such data cannot be obtained, the supplier will be required to <strong>[136]</strong> an independent audit at its own expense. <strong>[137]</strong> The review also found that logistics accounted for nearly two-thirds of the group's carbon footprint, a proportion that management considers untenable over the long term. Approval of the retrofit programme remains <strong>[138]</strong> on the outcome of an independent cost-benefit analysis, which the board expects to commission in the second quarter.</p></div>","questionText":"Select the sentence that best completes blank [137].","options":[{"key":"A","text":"(A) Because tier-one suppliers have already fulfilled the 2027 mandate, no further supply-chain adjustments are planned."},{"key":"B","text":"(B) Supplier disclosure was not the only shortcoming that the review identified."},{"key":"C","text":"(C) Independent auditors will nevertheless waive verification charges for domestic vendors operating under strict local rules."},{"key":"D","text":"(D) Those emissions disclosures focused solely on manufacturing sites, leaving transport contractors entirely outside the review's scope."}],"correct":"B","translation":"Việc công bố thông tin của nhà cung cấp không phải là khiếm khuyết duy nhất mà cuộc rà soát đã phát hiện.","explanation":"Câu sau mở đầu bằng 'The review also found that logistics accounted for nearly two-thirds...' — từ 'also' đòi hỏi câu đứng trước phải khẳng định vấn đề công bố thông tin của nhà cung cấp chưa phải phát hiện duy nhất. A mâu thuẫn với mốc 2027 và vấn đề mới nêu ở câu sau; C mâu thuẫn trực tiếp với 'at its own expense'; D mâu thuẫn với việc câu sau công bố phát hiện về logistics.","vocab":[{"word":"shortcoming","pos":"n.","meaning":"khiếm khuyết, thiếu sót"},{"word":"disclosure","pos":"n.","meaning":"sự công bố thông tin"},{"word":"mandate","pos":"n.","meaning":"quy định bắt buộc"}]},{"id":"reading-lv6-test-1-q138","questionNumber":138,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 6","partNumber":6,"partName":"Part 6: Hoàn thành đoạn văn (Text Completion)","title":"Test 01 (Level 6) • Câu 138 (Part 6: Hoàn thành đoạn văn)","passageTitle":"Questions 135-138 refer to the following excerpt from an annual report:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">EXCERPT FROM THE ANNUAL SUSTAINABILITY REPORT</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">In light of the commitments made at last year's shareholder assembly, the company has undertaken a comprehensive review of emissions across its supply chain. The board has stipulated that, by the end of 2027, every tier-one supplier must disclose independently verified emissions data, <strong>[135]</strong> it operates in a jurisdiction with less stringent reporting requirements. Where such data cannot be obtained, the supplier will be required to <strong>[136]</strong> an independent audit at its own expense. <strong>[137]</strong> The review also found that logistics accounted for nearly two-thirds of the group's carbon footprint, a proportion that management considers untenable over the long term. Approval of the retrofit programme remains <strong>[138]</strong> on the outcome of an independent cost-benefit analysis, which the board expects to commission in the second quarter.</p></div>","questionText":"Select the best answer to complete blank [138].","options":[{"key":"A","text":"(A) conducive"},{"key":"B","text":"(B) commensurate"},{"key":"C","text":"(C) congruent"},{"key":"D","text":"(D) contingent"}],"correct":"D","translation":"Việc phê duyệt chương trình cải tạo vẫn phụ thuộc vào kết quả của một phân tích chi phí – lợi ích độc lập, mà hội đồng dự kiến sẽ đặt hàng thực hiện trong quý hai.","explanation":"Chỉ có tính từ 'contingent' kết hợp với giới từ 'on' ('be contingent on' = phụ thuộc vào điều kiện gì). 'conducive' đi với giới từ 'to', còn 'congruent' và 'commensurate' đi với giới từ 'with'.","vocab":[{"word":"contingent on","pos":"adj.","meaning":"phụ thuộc vào"},{"word":"retrofit","pos":"n.","meaning":"việc cải tạo, nâng cấp hệ thống"},{"word":"commission","pos":"v.","meaning":"đặt hàng, ủy thác thực hiện"}]},{"id":"reading-lv6-test-1-q139","questionNumber":139,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 6","partNumber":6,"partName":"Part 6: Hoàn thành đoạn văn (Text Completion)","title":"Test 01 (Level 6) • Câu 139 (Part 6: Hoàn thành đoạn văn)","passageTitle":"Questions 139-142 refer to the following letter to customers:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">NOTICE TO PREMIUM ACCOUNT HOLDERS</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Dear Valued Client,</p><p class=\"mt-2\">We are writing to inform you that, effective 15 April, all orders currently submitted through our legacy portal must be placed via the Meridian ordering platform. The migration is designed to <strong>[139]</strong> the delays that many of you have experienced during peak periods, and it will also provide real-time visibility of stock levels. <strong>[140]</strong> Accounts that have not been activated by the migration date will remain accessible in read-only mode until a new password has been issued. <strong>[141]</strong> your account is managed by a designated purchasing agent, no action is required on your part. Should you encounter any difficulty during the transition, our account team will be available to assist you, and we would ask that you <strong>[142]</strong> any outstanding invoices before the legacy portal is retired.</p><p class=\"mt-2\">Yours sincerely,<br>Client Services Directorate</p></div>","questionText":"Select the best answer to complete blank [139].","options":[{"key":"A","text":"(A) exacerbate"},{"key":"B","text":"(B) perpetuate"},{"key":"C","text":"(C) precipitate"},{"key":"D","text":"(D) mitigate"}],"correct":"D","translation":"Việc chuyển đổi được thiết kế để giảm thiểu những chậm trễ mà nhiều quý khách đã gặp phải trong các giai đoạn cao điểm, đồng thời cung cấp khả năng hiển thị tồn kho theo thời gian thực.","explanation":"'Mitigate' nghĩa là làm dịu bớt, giảm thiểu tác động tiêu cực ('mitigate the delays'). 'exacerbate' (làm trầm trọng thêm), 'perpetuate' (duy trì kéo dài mãi) và 'precipitate' (làm bùng phát/đẩy nhanh sự cố) đều trái với lợi ích của nền tảng mới.","vocab":[{"word":"migration","pos":"n.","meaning":"sự chuyển đổi (hệ thống)"},{"word":"mitigate","pos":"v.","meaning":"giảm thiểu"},{"word":"real-time visibility","pos":"phrase","meaning":"khả năng hiển thị tức thời"}]},{"id":"reading-lv6-test-1-q140","questionNumber":140,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 6","partNumber":6,"partName":"Part 6: Hoàn thành đoạn văn (Text Completion)","title":"Test 01 (Level 6) • Câu 140 (Part 6: Hoàn thành đoạn văn)","passageTitle":"Questions 139-142 refer to the following letter to customers:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">NOTICE TO PREMIUM ACCOUNT HOLDERS</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Dear Valued Client,</p><p class=\"mt-2\">We are writing to inform you that, effective 15 April, all orders currently submitted through our legacy portal must be placed via the Meridian ordering platform. The migration is designed to <strong>[139]</strong> the delays that many of you have experienced during peak periods, and it will also provide real-time visibility of stock levels. <strong>[140]</strong> Accounts that have not been activated by the migration date will remain accessible in read-only mode until a new password has been issued. <strong>[141]</strong> your account is managed by a designated purchasing agent, no action is required on your part. Should you encounter any difficulty during the transition, our account team will be available to assist you, and we would ask that you <strong>[142]</strong> any outstanding invoices before the legacy portal is retired.</p><p class=\"mt-2\">Yours sincerely,<br>Client Services Directorate</p></div>","questionText":"Select the sentence that best completes blank [140].","options":[{"key":"A","text":"(A) Once an account is placed in read-only mode, its entire historical order archive is permanently purged."},{"key":"B","text":"(B) Legacy credentials will automatically grant full ordering privileges on the new platform without any user setup."},{"key":"C","text":"(C) A step-by-step activation guide will accompany the invitation that each account holder receives next week."},{"key":"D","text":"(D) Because the old portal has already been decommissioned, urgent orders must now be telephoned to regional depots."}],"correct":"C","translation":"Một hướng dẫn kích hoạt từng bước sẽ được gửi kèm lời mời mà mỗi chủ tài khoản nhận được vào tuần tới.","explanation":"Câu sau đề cập hậu quả đối với các tài khoản chưa được kích hoạt trước ngày chuyển đổi ('Accounts that have not been activated by the migration date...'), nên câu điền vào phải giới thiệu quy trình kích hoạt tài khoản mới (Câu C). B mâu thuẫn với việc phải kích hoạt và cấp mật khẩu mới; A nêu tình huống xóa dữ liệu vô căn cứ và đứt mạch với việc mở đầu khái niệm 'activated'; D mâu thuẫn với mốc hiệu lực '15 April' ở câu đầu.","vocab":[{"word":"activation","pos":"n.","meaning":"sự kích hoạt"},{"word":"accompany","pos":"v.","meaning":"đi kèm, gửi kèm"},{"word":"account holder","pos":"n.","meaning":"chủ tài khoản"}]},{"id":"reading-lv6-test-1-q141","questionNumber":141,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 6","partNumber":6,"partName":"Part 6: Hoàn thành đoạn văn (Text Completion)","title":"Test 01 (Level 6) • Câu 141 (Part 6: Hoàn thành đoạn văn)","passageTitle":"Questions 139-142 refer to the following letter to customers:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">NOTICE TO PREMIUM ACCOUNT HOLDERS</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Dear Valued Client,</p><p class=\"mt-2\">We are writing to inform you that, effective 15 April, all orders currently submitted through our legacy portal must be placed via the Meridian ordering platform. The migration is designed to <strong>[139]</strong> the delays that many of you have experienced during peak periods, and it will also provide real-time visibility of stock levels. <strong>[140]</strong> Accounts that have not been activated by the migration date will remain accessible in read-only mode until a new password has been issued. <strong>[141]</strong> your account is managed by a designated purchasing agent, no action is required on your part. Should you encounter any difficulty during the transition, our account team will be available to assist you, and we would ask that you <strong>[142]</strong> any outstanding invoices before the legacy portal is retired.</p><p class=\"mt-2\">Yours sincerely,<br>Client Services Directorate</p></div>","questionText":"Select the best answer to complete blank [141].","options":[{"key":"A","text":"(A) In the event that"},{"key":"B","text":"(B) Inasmuch as"},{"key":"C","text":"(C) For fear that"},{"key":"D","text":"(D) Notwithstanding that"}],"correct":"A","translation":"Trong trường hợp tài khoản của quý khách được quản lý bởi một đại lý thu mua được chỉ định, quý khách không cần thực hiện thao tác nào.","explanation":"Chỉ có liên từ điều kiện 'In the event that' (trong trường hợp mà) diễn tả đúng tình huống giả định không chắc xảy ra với mọi khách hàng. 'Notwithstanding that' (mặc dù), 'Inasmuch as' (bởi vì, xét thấy thực tế là) và 'For fear that' (vì sợ rằng) không phù hợp quan hệ điều kiện.","vocab":[{"word":"in the event that","pos":"conj.","meaning":"trong trường hợp"},{"word":"designated","pos":"adj.","meaning":"được chỉ định"},{"word":"purchasing agent","pos":"n.","meaning":"đại lý thu mua"}]},{"id":"reading-lv6-test-1-q142","questionNumber":142,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 6","partNumber":6,"partName":"Part 6: Hoàn thành đoạn văn (Text Completion)","title":"Test 01 (Level 6) • Câu 142 (Part 6: Hoàn thành đoạn văn)","passageTitle":"Questions 139-142 refer to the following letter to customers:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">NOTICE TO PREMIUM ACCOUNT HOLDERS</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Dear Valued Client,</p><p class=\"mt-2\">We are writing to inform you that, effective 15 April, all orders currently submitted through our legacy portal must be placed via the Meridian ordering platform. The migration is designed to <strong>[139]</strong> the delays that many of you have experienced during peak periods, and it will also provide real-time visibility of stock levels. <strong>[140]</strong> Accounts that have not been activated by the migration date will remain accessible in read-only mode until a new password has been issued. <strong>[141]</strong> your account is managed by a designated purchasing agent, no action is required on your part. Should you encounter any difficulty during the transition, our account team will be available to assist you, and we would ask that you <strong>[142]</strong> any outstanding invoices before the legacy portal is retired.</p><p class=\"mt-2\">Yours sincerely,<br>Client Services Directorate</p></div>","questionText":"Select the best answer to complete blank [142].","options":[{"key":"A","text":"(A) settled"},{"key":"B","text":"(B) settle"},{"key":"C","text":"(C) would settle"},{"key":"D","text":"(D) are settling"}],"correct":"B","translation":"Nếu quý khách gặp bất kỳ khó khăn nào trong quá trình chuyển đổi, đội ngũ phụ trách tài khoản của chúng tôi sẽ sẵn sàng hỗ trợ, và chúng tôi đề nghị quý khách thanh toán các hoá đơn còn tồn đọng trước khi cổng thông tin cũ ngừng hoạt động.","explanation":"Sau động từ mang tính đề nghị 'ask that' phải dùng giả định cách (mandative subjunctive): động từ nguyên mẫu không 'to' cho mọi chủ ngữ, nên chọn 'settle'. Ba lựa chọn còn lại chia thì chỉ định hoặc điều kiện sai cấu trúc giả định.","vocab":[{"word":"outstanding invoice","pos":"n.","meaning":"hoá đơn chưa thanh toán"},{"word":"settle","pos":"v.","meaning":"thanh toán"},{"word":"retire","pos":"v.","meaning":"cho ngừng sử dụng"}]},{"id":"reading-lv6-test-1-q143","questionNumber":143,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 6","partNumber":6,"partName":"Part 6: Hoàn thành đoạn văn (Text Completion)","title":"Test 01 (Level 6) • Câu 143 (Part 6: Hoàn thành đoạn văn)","passageTitle":"Questions 143-146 refer to the following memorandum:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">PROJECT STATUS UPDATE</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">To: Executive Steering Committee<br>From: Programme Director, Atlas Modernisation<br>Re: Status of Phase Two</p><p class=\"mt-2\">Phase Two of the Atlas modernisation programme is now roughly eighty per cent complete, and the remaining deliverables are expected to be handed over within the revised budget. The data migration, originally scheduled for February, has been postponed until April so that legacy records can be cleansed of duplicate entries. Not until those cleansed records have been independently validated <strong>[143]</strong> to the production environment. <strong>[144]</strong> Nonetheless, the steering committee should be aware that a four-week slip in this workstream would have a <strong>[145]</strong> effect on the go-live date, which is currently fixed for 30 June. <strong>[146]</strong> the vendor makes additional testing resources available, the programme board will release the contingency reserve in June.</p></div>","questionText":"Select the best answer to complete blank [143].","options":[{"key":"A","text":"(A) the migration will proceed"},{"key":"B","text":"(B) will the migration proceed"},{"key":"C","text":"(C) the migration proceeds"},{"key":"D","text":"(D) has the migration proceeded"}],"correct":"B","translation":"Chỉ khi những bản ghi đã được làm sạch đó được kiểm chứng độc lập thì việc di chuyển dữ liệu mới được tiến hành sang môi trường vận hành.","explanation":"Khi 'Not until + mệnh đề trạng ngữ' đặt ở đầu câu, mệnh đề chính bắt buộc phải đảo ngữ ('will the migration proceed'). 'the migration will proceed' và 'the migration proceeds' không đảo ngữ, còn 'has the migration proceeded' sai thì tương lai dự kiến trong tháng Tư.","vocab":[{"word":"validate","pos":"v.","meaning":"kiểm chứng, xác nhận"},{"word":"proceed","pos":"v.","meaning":"tiến hành, đi tiếp"},{"word":"legacy records","pos":"n.","meaning":"dữ liệu cũ"}]},{"id":"reading-lv6-test-1-q144","questionNumber":144,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 6","partNumber":6,"partName":"Part 6: Hoàn thành đoạn văn (Text Completion)","title":"Test 01 (Level 6) • Câu 144 (Part 6: Hoàn thành đoạn văn)","passageTitle":"Questions 143-146 refer to the following memorandum:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">PROJECT STATUS UPDATE</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">To: Executive Steering Committee<br>From: Programme Director, Atlas Modernisation<br>Re: Status of Phase Two</p><p class=\"mt-2\">Phase Two of the Atlas modernisation programme is now roughly eighty per cent complete, and the remaining deliverables are expected to be handed over within the revised budget. The data migration, originally scheduled for February, has been postponed until April so that legacy records can be cleansed of duplicate entries. Not until those cleansed records have been independently validated <strong>[143]</strong> to the production environment. <strong>[144]</strong> Nonetheless, the steering committee should be aware that a four-week slip in this workstream would have a <strong>[145]</strong> effect on the go-live date, which is currently fixed for 30 June. <strong>[146]</strong> the vendor makes additional testing resources available, the programme board will release the contingency reserve in June.</p></div>","questionText":"Select the sentence that best completes blank [144].","options":[{"key":"A","text":"(A) Consequently, the steering committee has formally voted to postpone the 30 June launch until the fourth quarter."},{"key":"B","text":"(B) Phase Two has already exceeded its revised budget, prompting auditors to freeze all remaining deliverables."},{"key":"C","text":"(C) Because duplicate entries cannot be removed before May, production testing has been suspended indefinitely."},{"key":"D","text":"(D) The deferral is not expected to affect the overall timeline, since the cleansing was already under way."}],"correct":"D","translation":"Việc lùi thời hạn này được cho là sẽ không ảnh hưởng đến tiến độ tổng thể, vì công việc làm sạch dữ liệu vốn đã được triển khai từ trước.","explanation":"Câu trước báo hoãn migration từ tháng Hai sang tháng Tư; câu sau mở đầu bằng trạng từ nhượng bộ 'Nonetheless' cảnh báo nguy cơ nếu trễ thêm bốn tuần đối với mốc 30/6. Do đó, câu ở giữa phải đưa ra nhận định trấn an ban đầu ('not expected to affect the overall timeline') để 'Nonetheless' phản biện lại. A và C mâu thuẫn với việc migration dự kiến sang tháng Tư và ngày go-live vẫn là 30/6; B mâu thuẫn trực tiếp câu đầu ('within the revised budget').","vocab":[{"word":"deferral","pos":"n.","meaning":"sự hoãn, sự lùi thời hạn"},{"word":"overall timeline","pos":"phrase","meaning":"tiến độ tổng thể"},{"word":"under way","pos":"phrase","meaning":"đang được triển khai"}]},{"id":"reading-lv6-test-1-q145","questionNumber":145,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 6","partNumber":6,"partName":"Part 6: Hoàn thành đoạn văn (Text Completion)","title":"Test 01 (Level 6) • Câu 145 (Part 6: Hoàn thành đoạn văn)","passageTitle":"Questions 143-146 refer to the following memorandum:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">PROJECT STATUS UPDATE</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">To: Executive Steering Committee<br>From: Programme Director, Atlas Modernisation<br>Re: Status of Phase Two</p><p class=\"mt-2\">Phase Two of the Atlas modernisation programme is now roughly eighty per cent complete, and the remaining deliverables are expected to be handed over within the revised budget. The data migration, originally scheduled for February, has been postponed until April so that legacy records can be cleansed of duplicate entries. Not until those cleansed records have been independently validated <strong>[143]</strong> to the production environment. <strong>[144]</strong> Nonetheless, the steering committee should be aware that a four-week slip in this workstream would have a <strong>[145]</strong> effect on the go-live date, which is currently fixed for 30 June. <strong>[146]</strong> the vendor makes additional testing resources available, the programme board will release the contingency reserve in June.</p></div>","questionText":"Select the best answer to complete blank [145].","options":[{"key":"A","text":"(A) detrimental"},{"key":"B","text":"(B) negligible"},{"key":"C","text":"(C) salutary"},{"key":"D","text":"(D) perfunctory"}],"correct":"A","translation":"Tuy vậy, uỷ ban chỉ đạo cần lưu ý rằng một sự chậm trễ bốn tuần trong nhánh công việc này sẽ có tác động bất lợi đến ngày vận hành chính thức, hiện đang được ấn định vào ngày 30 tháng 6.","explanation":"'Detrimental' mang nghĩa có hại, bất lợi — khớp với cảnh báo thận trọng mở đầu bằng 'Nonetheless' về nguy cơ trượt mốc 30/6. 'negligible' (không đáng kể) làm vô nghĩa lời cảnh báo; 'salutary' (bổ ích, có lợi) ngược nghĩa; 'perfunctory' (qua loa) không đi với kết quả chậm tiến độ.","vocab":[{"word":"slip","pos":"n.","meaning":"sự chậm trễ, sự trượt tiến độ"},{"word":"detrimental","pos":"adj.","meaning":"bất lợi, có hại"},{"word":"go-live date","pos":"n.","meaning":"ngày vận hành chính thức"}]},{"id":"reading-lv6-test-1-q146","questionNumber":146,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 6","partNumber":6,"partName":"Part 6: Hoàn thành đoạn văn (Text Completion)","title":"Test 01 (Level 6) • Câu 146 (Part 6: Hoàn thành đoạn văn)","passageTitle":"Questions 143-146 refer to the following memorandum:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">PROJECT STATUS UPDATE</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">To: Executive Steering Committee<br>From: Programme Director, Atlas Modernisation<br>Re: Status of Phase Two</p><p class=\"mt-2\">Phase Two of the Atlas modernisation programme is now roughly eighty per cent complete, and the remaining deliverables are expected to be handed over within the revised budget. The data migration, originally scheduled for February, has been postponed until April so that legacy records can be cleansed of duplicate entries. Not until those cleansed records have been independently validated <strong>[143]</strong> to the production environment. <strong>[144]</strong> Nonetheless, the steering committee should be aware that a four-week slip in this workstream would have a <strong>[145]</strong> effect on the go-live date, which is currently fixed for 30 June. <strong>[146]</strong> the vendor makes additional testing resources available, the programme board will release the contingency reserve in June.</p></div>","questionText":"Select the best answer to complete blank [146].","options":[{"key":"A","text":"(A) Provided that"},{"key":"B","text":"(B) Unless"},{"key":"C","text":"(C) Even though"},{"key":"D","text":"(D) As though"}],"correct":"A","translation":"Với điều kiện nhà cung cấp cung cấp thêm nguồn lực kiểm thử, hội đồng chương trình sẽ giải phóng khoản dự phòng vào tháng Sáu.","explanation":"'Provided that' là liên từ điều kiện nghĩa 'miễn là, với điều kiện là', khớp logic việc chỉ giải ngân quỹ dự phòng khi nhà cung cấp đáp ứng thêm nguồn lực kiểm thử. 'Unless' (trừ khi) đảo ngược điều kiện, 'Even though' (mặc dù) và 'As though' (như thể là) không phù hợp tương lai có điều kiện.","vocab":[{"word":"provided that","pos":"conj.","meaning":"với điều kiện là"},{"word":"contingency reserve","pos":"n.","meaning":"quỹ dự phòng"},{"word":"release","pos":"v.","meaning":"giải phóng, giải ngân"}]},{"id":"reading-lv6-test-1-q147","questionNumber":147,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 147 (Part 7: Đọc hiểu)","passageTitle":"Questions 147-148 refer to the following e-mail:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">INTERNAL E-MAIL</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">To: Regional Category Managers<br>From: Priya Raghunathan, Director of Procurement<br>Re: Consolidation of printing-supplies contracts</p><p class=\"mt-2\">As you are aware, our current arrangements with four separate office-supply vendors expire at the end of next quarter. Preliminary analysis suggests that consolidating these purchases under a single strategic supplier would reduce unit costs by roughly nine percent, though it would also concentrate risk in one counterparty. I am therefore asking each of you to submit a short assessment of the vendors you currently oversee, with particular attention to their delivery record over the past eighteen months and to any penalty clauses that might be triggered by early termination.</p><p class=\"mt-2\">Please keep submissions to two pages; anecdote is no substitute for the data held in the procurement dashboard. A shortlist will be circulated ahead of the October steering committee.</p></div>","questionText":"Why did Ms. Raghunathan send this e-mail to the regional category managers?","options":[{"key":"A","text":"(A) To instruct them to terminate four office-supply contracts before the end of next quarter"},{"key":"B","text":"(B) To solicit concise, evidence-based vendor evaluations prior to a consolidation review"},{"key":"C","text":"(C) To report that preliminary analysis has guaranteed a nine-percent drop in counterparty risk"},{"key":"D","text":"(D) To request historical delivery data from the procurement dashboard ahead of an October audit"}],"correct":"B","translation":"Vì sao bà Raghunathan gửi e-mail này cho các quản lý ngành hàng khu vực? — Để đề nghị các bản đánh giá nhà cung cấp ngắn gọn, dựa trên dữ liệu trước cuộc rà soát hợp nhất hợp đồng.","explanation":"Người viết nêu việc hợp nhất đang ở bước phân tích sơ bộ ('Preliminary analysis suggests') và yêu cầu nộp bản đánh giá tối đa hai trang dựa trên dữ liệu dashboard ('keep submissions to two pages; anecdote is no substitute for the data...'). A sai vì chưa ra lệnh chấm dứt hợp đồng; C bóp méo số 9% (giảm đơn giá, trong khi hợp nhất thực chất làm tăng tập trung rủi ro đối tác); D sai vì dữ liệu đã có sẵn trên dashboard và cuộc họp tháng 10 là của ban chỉ đạo chứ không phải kiểm toán.","vocab":[{"word":"consolidation","pos":"n.","meaning":"sự hợp nhất, gộp lại"},{"word":"counterparty","pos":"n.","meaning":"bên đối tác trong giao dịch"},{"word":"solicit","pos":"v.","meaning":"đề nghị cung cấp, kêu gọi"}]},{"id":"reading-lv6-test-1-q148","questionNumber":148,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 148 (Part 7: Đọc hiểu)","passageTitle":"Questions 147-148 refer to the following e-mail:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">INTERNAL E-MAIL</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">To: Regional Category Managers<br>From: Priya Raghunathan, Director of Procurement<br>Re: Consolidation of printing-supplies contracts</p><p class=\"mt-2\">As you are aware, our current arrangements with four separate office-supply vendors expire at the end of next quarter. Preliminary analysis suggests that consolidating these purchases under a single strategic supplier would reduce unit costs by roughly nine percent, though it would also concentrate risk in one counterparty. I am therefore asking each of you to submit a short assessment of the vendors you currently oversee, with particular attention to their delivery record over the past eighteen months and to any penalty clauses that might be triggered by early termination.</p><p class=\"mt-2\">Please keep submissions to two pages; anecdote is no substitute for the data held in the procurement dashboard. A shortlist will be circulated ahead of the October steering committee.</p></div>","questionText":"What is implied about the written assessments that managers are asked to submit?","options":[{"key":"A","text":"(A) They should exceed two pages only when penalty clauses require legal quotation."},{"key":"B","text":"(B) They are intended to replace the figures recorded in the procurement dashboard."},{"key":"C","text":"(C) They must be anchored in quantitative performance metrics rather than informal impressions."},{"key":"D","text":"(D) They must compare prospective outside vendors against the four incumbent suppliers."}],"correct":"C","translation":"Điều gì được ngụ ý về các bản đánh giá mà các quản lý được yêu cầu nộp? — Chúng phải dựa trên các chỉ số hiệu suất định lượng thay vì cảm nhận cá nhân rời rạc.","explanation":"Câu 'anecdote is no substitute for the data held in the procurement dashboard' ngụ ý báo cáo đánh giá phải dựa trên số liệu khách quan trên dashboard thay vì nhận xét cảm tính. A bịa đặt ngoại lệ cho giới hạn hai trang; B đảo ngược quan hệ (không thay thế dữ liệu dashboard); D sai vì bài chỉ yêu cầu đánh giá bốn nhà cung cấp hiện tại ('vendors you currently oversee').","vocab":[{"word":"substitute","pos":"n.","meaning":"vật thay thế"},{"word":"quantitative","pos":"adj.","meaning":"mang tính định lượng"},{"word":"incumbent","pos":"adj.","meaning":"đương nhiệm, hiện tại"}]},{"id":"reading-lv6-test-1-q149","questionNumber":149,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 149 (Part 7: Đọc hiểu)","passageTitle":"Questions 149-151 refer to the following policy notice:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">POLICY NOTICE: AMENDMENT TO THE SUPPLIER CODE OF CONDUCT</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Effective 1 January, all Tier 1 suppliers will be required to disclose the carbon intensity of inbound freight on a quarterly basis. Suppliers falling short of the reporting threshold will not be suspended outright; instead, they will be placed on a remediation schedule lasting no more than two quarters. Only persistent non-disclosure, defined as three consecutive missed submissions, will trigger a formal review of the commercial relationship.</p><p class=\"mt-2\">The revised code stops short of mandating a specific emissions target, a point on which the sustainability committee was divided. Suppliers should note that the disclosure obligation extends to subcontracted carriers, notwithstanding any confidentiality provisions in existing agreements.</p></div>","questionText":"What is the primary purpose of the notice?","options":[{"key":"A","text":"(A) To notify Tier 1 suppliers that binding emissions targets take effect on 1 January"},{"key":"B","text":"(B) To exempt subcontracted carriers from quarterly reporting where confidentiality clauses apply"},{"key":"C","text":"(C) To detail revised quarterly emissions reporting mandates and tiered enforcement rules"},{"key":"D","text":"(D) To announce that suppliers missing a quarterly threshold face immediate commercial suspension"}],"correct":"C","translation":"Mục đích chính của thông báo là trình bày chi tiết nghĩa vụ báo cáo phát thải hằng quý đã sửa đổi và các mức xử lý theo lộ trình.","explanation":"Văn bản nêu quy định công bố dữ liệu carbon hằng quý từ 1/1 và lộ trình xử lý theo cấp độ (tối đa hai quý khắc phục trước khi rà soát hợp đồng ở lần thứ ba liên tiếp). A sai vì quy định 'stops short of mandating a specific emissions target'; B trái ngược đoạn cuối ('extends to subcontracted carriers, notwithstanding any confidentiality provisions'); D trái với câu 'will not be suspended outright'.","vocab":[{"word":"disclosure","pos":"n.","meaning":"sự công bố, tiết lộ thông tin"},{"word":"remediation","pos":"n.","meaning":"việc khắc phục, sửa chữa"},{"word":"persistent","pos":"adj.","meaning":"kéo dài, dai dẳng"}]},{"id":"reading-lv6-test-1-q150","questionNumber":150,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 150 (Part 7: Đọc hiểu)","passageTitle":"Questions 149-151 refer to the following policy notice:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">POLICY NOTICE: AMENDMENT TO THE SUPPLIER CODE OF CONDUCT</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Effective 1 January, all Tier 1 suppliers will be required to disclose the carbon intensity of inbound freight on a quarterly basis. Suppliers falling short of the reporting threshold will not be suspended outright; instead, they will be placed on a remediation schedule lasting no more than two quarters. Only persistent non-disclosure, defined as three consecutive missed submissions, will trigger a formal review of the commercial relationship.</p><p class=\"mt-2\">The revised code stops short of mandating a specific emissions target, a point on which the sustainability committee was divided. Suppliers should note that the disclosure obligation extends to subcontracted carriers, notwithstanding any confidentiality provisions in existing agreements.</p></div>","questionText":"The phrase \"stops short of\" in paragraph 2 is closest in meaning to","options":[{"key":"A","text":"(A) exceeds the requirements of"},{"key":"B","text":"(B) abandons the idea of"},{"key":"C","text":"(C) postpones indefinitely"},{"key":"D","text":"(D) refrains from going as far as"}],"correct":"D","translation":"Cụm \"stops short of\" gần nghĩa nhất với \"không đi xa tới mức\".","explanation":"\"Stops short of mandating a specific emissions target\" = bộ quy tắc dừng lại trước việc bắt buộc một mục tiêu cụ thể, tức không đi xa đến mức đó. B (từ bỏ) và C (hoãn vô thời hạn) sai vì quy tắc vẫn có nghĩa vụ công bố; A ngược nghĩa.","vocab":[{"word":"mandate","pos":"v.","meaning":"bắt buộc, quy định"},{"word":"threshold","pos":"n.","meaning":"ngưỡng"},{"word":"consecutive","pos":"adj.","meaning":"liên tiếp"}]},{"id":"reading-lv6-test-1-q151","questionNumber":151,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 151 (Part 7: Đọc hiểu)","passageTitle":"Questions 149-151 refer to the following policy notice:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">POLICY NOTICE: AMENDMENT TO THE SUPPLIER CODE OF CONDUCT</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Effective 1 January, all Tier 1 suppliers will be required to disclose the carbon intensity of inbound freight on a quarterly basis. Suppliers falling short of the reporting threshold will not be suspended outright; instead, they will be placed on a remediation schedule lasting no more than two quarters. Only persistent non-disclosure, defined as three consecutive missed submissions, will trigger a formal review of the commercial relationship.</p><p class=\"mt-2\">The revised code stops short of mandating a specific emissions target, a point on which the sustainability committee was divided. Suppliers should note that the disclosure obligation extends to subcontracted carriers, notwithstanding any confidentiality provisions in existing agreements.</p></div>","questionText":"Which of the following is NOT supported by the notice?","options":[{"key":"A","text":"(A) Suppliers must report emissions data for subcontracted carriers."},{"key":"B","text":"(B) A supplier that misses a single submission loses its Tier 1 status at once."},{"key":"C","text":"(C) Repeated failure to report may put the commercial relationship under review."},{"key":"D","text":"(D) The code does not impose a specific emissions target."}],"correct":"B","translation":"Điều nào KHÔNG được thông báo ủng hộ? — Việc một nhà cung cấp bỏ lỡ một lần nộp báo cáo sẽ mất ngay trạng thái Tier 1.","explanation":"Thông báo ghi rõ \"will not be suspended outright\" và chỉ \"three consecutive missed submissions\" mới dẫn tới rà soát chính thức, nên B trái với văn bản. A đúng (\"extends to subcontracted carriers\"), C đúng (\"formal review\"), D đúng (\"stops short of mandating a specific emissions target\").","vocab":[{"word":"outright","pos":"adv.","meaning":"ngay lập tức, hoàn toàn"},{"word":"subcontract","pos":"v.","meaning":"thầu phụ, ký hợp đồng phụ"},{"word":"confidentiality","pos":"n.","meaning":"tính bảo mật"}]},{"id":"reading-lv6-test-1-q152","questionNumber":152,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 152 (Part 7: Đọc hiểu)","passageTitle":"Questions 152-154 refer to the following extract from a contract:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">MASTER SERVICES AGREEMENT: EXTRACT (CLAUSE 9, LIABILITY)</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">9.1 The Supplier shall indemnify the Client against all direct losses arising from any breach of this Agreement, provided that such losses are notified in writing within ninety days of the event giving rise to the claim.</p><p class=\"mt-2\">9.2 The Supplier's aggregate liability under this Agreement shall not exceed the fees paid by the Client in the twelve months immediately preceding the claim, save where the claim arises from wilful misconduct or gross negligence, in which case no such limitation shall apply.</p><p class=\"mt-2\">9.3 Neither party shall be liable for indirect or consequential loss, including loss of profit, however arising.</p><p class=\"mt-2\">9.4 Nothing in this Clause shall be construed as excluding liability for death or personal injury caused by negligence.</p></div>","questionText":"What can be inferred about a client that wishes to recover profits it claims to have lost?","options":[{"key":"A","text":"(A) It is unlikely to succeed, because such a loss falls outside the recoverable category."},{"key":"B","text":"(B) It may do so provided notice is given within ninety days."},{"key":"C","text":"(C) It may recover the full amount from the Supplier's insurers."},{"key":"D","text":"(D) It must first demonstrate wilful misconduct by the Supplier."}],"correct":"A","translation":"Có thể suy ra gì về khách hàng muốn đòi lại phần lợi nhuận bị mất? — Khó thành công, vì loại thiệt hại đó nằm ngoài phạm vi được bồi thường.","explanation":"Khoản 9.3 quy định \"Neither party shall be liable for indirect or consequential loss, including loss of profit\", tức lợi nhuận bị mất bị xếp vào thiệt hại gián tiếp và bị loại trừ. Vì vậy thông báo trong 90 ngày (B) không giải quyết được vấn đề; C và D không có căn cứ trong điều khoản.","vocab":[{"word":"indemnify","pos":"v.","meaning":"bồi thường, đền bù"},{"word":"consequential","pos":"adj.","meaning":"hệ quả, gián tiếp"},{"word":"breach","pos":"n.","meaning":"sự vi phạm"}]},{"id":"reading-lv6-test-1-q153","questionNumber":153,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 153 (Part 7: Đọc hiểu)","passageTitle":"Questions 152-154 refer to the following extract from a contract:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">MASTER SERVICES AGREEMENT: EXTRACT (CLAUSE 9, LIABILITY)</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">9.1 The Supplier shall indemnify the Client against all direct losses arising from any breach of this Agreement, provided that such losses are notified in writing within ninety days of the event giving rise to the claim.</p><p class=\"mt-2\">9.2 The Supplier's aggregate liability under this Agreement shall not exceed the fees paid by the Client in the twelve months immediately preceding the claim, save where the claim arises from wilful misconduct or gross negligence, in which case no such limitation shall apply.</p><p class=\"mt-2\">9.3 Neither party shall be liable for indirect or consequential loss, including loss of profit, however arising.</p><p class=\"mt-2\">9.4 Nothing in this Clause shall be construed as excluding liability for death or personal injury caused by negligence.</p></div>","questionText":"The phrase \"save where\" in clause 9.2 is closest in meaning to","options":[{"key":"A","text":"(A) in the hope that"},{"key":"B","text":"(B) at the same time as"},{"key":"C","text":"(C) except in cases where"},{"key":"D","text":"(D) regardless of whether"}],"correct":"C","translation":"\"Save where\" trong khoản 9.2 gần nghĩa nhất với \"trừ những trường hợp mà\".","explanation":"\"save where the claim arises from wilful misconduct... no such limitation shall apply\" nghĩa là giới hạn trách nhiệm không áp dụng, trừ khi yêu cầu bồi thường phát sinh từ hành vi cố ý. \"Save\" ở đây là giới từ pháp lý mang nghĩa \"except\".","vocab":[{"word":"aggregate","pos":"adj.","meaning":"tổng cộng, gộp lại"},{"word":"wilful misconduct","pos":"n.","meaning":"hành vi sai trái cố ý"},{"word":"gross negligence","pos":"n.","meaning":"sơ suất nghiêm trọng"}]},{"id":"reading-lv6-test-1-q154","questionNumber":154,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 154 (Part 7: Đọc hiểu)","passageTitle":"Questions 152-154 refer to the following extract from a contract:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">MASTER SERVICES AGREEMENT: EXTRACT (CLAUSE 9, LIABILITY)</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">9.1 The Supplier shall indemnify the Client against all direct losses arising from any breach of this Agreement, provided that such losses are notified in writing within ninety days of the event giving rise to the claim.</p><p class=\"mt-2\">9.2 The Supplier's aggregate liability under this Agreement shall not exceed the fees paid by the Client in the twelve months immediately preceding the claim, save where the claim arises from wilful misconduct or gross negligence, in which case no such limitation shall apply.</p><p class=\"mt-2\">9.3 Neither party shall be liable for indirect or consequential loss, including loss of profit, however arising.</p><p class=\"mt-2\">9.4 Nothing in this Clause shall be construed as excluding liability for death or personal injury caused by negligence.</p></div>","questionText":"Which of the following is NOT supported by the extract?","options":[{"key":"A","text":"(A) Liability arising from gross negligence is subject to the same cap as other claims."},{"key":"B","text":"(B) The liability cap is calculated by reference to fees paid over twelve months."},{"key":"C","text":"(C) A claim must be notified in writing within ninety days of the triggering event."},{"key":"D","text":"(D) Loss of profit is treated as a form of consequential loss."}],"correct":"A","translation":"Điều nào KHÔNG được đoạn trích ủng hộ? — Trách nhiệm phát sinh từ sơ suất nghiêm trọng vẫn chịu cùng mức trần như các yêu cầu khác.","explanation":"Khoản 9.2 nêu rõ với \"wilful misconduct or gross negligence\" thì \"no such limitation shall apply\", tức trần trách nhiệm bị loại bỏ, nên A sai. C (9.1), B (\"fees paid... in the twelve months\") và D (9.3 xếp \"loss of profit\" vào consequential loss) đều được ủng hộ.","vocab":[{"word":"liability","pos":"n.","meaning":"trách nhiệm pháp lý"},{"word":"cap","pos":"n.","meaning":"mức trần, giới hạn tối đa"},{"word":"construe","pos":"v.","meaning":"diễn giải, hiểu là"}]},{"id":"reading-lv6-test-1-q155","questionNumber":155,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 155 (Part 7: Đọc hiểu)","passageTitle":"Questions 155-157 refer to the following financial review:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">EXTRACT FROM THE QUARTERLY FINANCIAL REVIEW</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Revenue for the quarter rose 6.2 percent year on year to $48.1 million, although nearly all of the increase is attributable to favourable currency movements; at constant exchange rates, growth was a modest 0.8 percent. Gross margin contracted by 140 basis points, which management ascribes to elevated inbound logistics costs and an unfavourable product mix. Operating expenses were broadly flat, reflecting the hiring freeze imposed in the prior quarter. Free cash flow turned negative, largely because of a one-off settlement with a former distributor.</p><p class=\"mt-2\">The board has declined to reinstate the dividend, noting that leverage remains above the target range. Management reiterated full-year guidance, albeit within a wider range than previously given, citing \"unprecedented volatility in freight markets\".</p></div>","questionText":"What can be inferred about the company's underlying performance?","options":[{"key":"A","text":"(A) Demand for its products grew strongly during the quarter."},{"key":"B","text":"(B) Gross margin improved because of a more favourable product mix."},{"key":"C","text":"(C) The improvement in reported revenue was largely not operational."},{"key":"D","text":"(D) Operating expenses rose sharply despite the hiring freeze."}],"correct":"C","translation":"Có thể suy ra gì về kết quả kinh doanh thực chất? — Mức tăng doanh thu báo cáo phần lớn không đến từ hoạt động kinh doanh.","explanation":"Đoạn văn cho biết \"nearly all of the increase is attributable to favourable currency movements\" và tăng trưởng theo tỷ giá cố định chỉ 0,8%, nên cải thiện chủ yếu do tiền tệ. A trái với con số 0,8%; B sai vì biên gộp \"contracted\" do \"unfavourable product mix\"; D sai vì chi phí \"broadly flat\".","vocab":[{"word":"contract","pos":"v.","meaning":"thu hẹp, giảm sút"},{"word":"basis point","pos":"n.","meaning":"điểm cơ bản (0,01%)"},{"word":"hiring freeze","pos":"n.","meaning":"việc đóng băng tuyển dụng"}]},{"id":"reading-lv6-test-1-q156","questionNumber":156,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 156 (Part 7: Đọc hiểu)","passageTitle":"Questions 155-157 refer to the following financial review:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">EXTRACT FROM THE QUARTERLY FINANCIAL REVIEW</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Revenue for the quarter rose 6.2 percent year on year to $48.1 million, although nearly all of the increase is attributable to favourable currency movements; at constant exchange rates, growth was a modest 0.8 percent. Gross margin contracted by 140 basis points, which management ascribes to elevated inbound logistics costs and an unfavourable product mix. Operating expenses were broadly flat, reflecting the hiring freeze imposed in the prior quarter. Free cash flow turned negative, largely because of a one-off settlement with a former distributor.</p><p class=\"mt-2\">The board has declined to reinstate the dividend, noting that leverage remains above the target range. Management reiterated full-year guidance, albeit within a wider range than previously given, citing \"unprecedented volatility in freight markets\".</p></div>","questionText":"The word \"ascribes\" in paragraph 1 is closest in meaning to","options":[{"key":"A","text":"(A) contrasts"},{"key":"B","text":"(B) subscribes"},{"key":"C","text":"(C) restricts"},{"key":"D","text":"(D) attributes"}],"correct":"D","translation":"\"Ascribes\" trong đoạn 1 gần nghĩa nhất với \"attributes\" (quy cho, cho là do).","explanation":"\"which management ascribes to elevated inbound logistics costs\" = ban điều hành quy nguyên nhân việc thu hẹp biên gộp cho chi phí logistics đầu vào tăng cao. \"Ascribe... to\" đồng nghĩa \"attribute... to\". Các phương án còn lại không tạo được kết cấu nghĩa này.","vocab":[{"word":"elevated","pos":"adj.","meaning":"tăng cao"},{"word":"inbound","pos":"adj.","meaning":"đầu vào, chiều đến"},{"word":"product mix","pos":"n.","meaning":"cơ cấu sản phẩm"}]},{"id":"reading-lv6-test-1-q157","questionNumber":157,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 157 (Part 7: Đọc hiểu)","passageTitle":"Questions 155-157 refer to the following financial review:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">EXTRACT FROM THE QUARTERLY FINANCIAL REVIEW</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Revenue for the quarter rose 6.2 percent year on year to $48.1 million, although nearly all of the increase is attributable to favourable currency movements; at constant exchange rates, growth was a modest 0.8 percent. Gross margin contracted by 140 basis points, which management ascribes to elevated inbound logistics costs and an unfavourable product mix. Operating expenses were broadly flat, reflecting the hiring freeze imposed in the prior quarter. Free cash flow turned negative, largely because of a one-off settlement with a former distributor.</p><p class=\"mt-2\">The board has declined to reinstate the dividend, noting that leverage remains above the target range. Management reiterated full-year guidance, albeit within a wider range than previously given, citing \"unprecedented volatility in freight markets\".</p></div>","questionText":"Which of the following is NOT supported by the review?","options":[{"key":"A","text":"(A) Currency effects accounted for most of the reported revenue growth."},{"key":"B","text":"(B) The company reduced its headcount during the quarter."},{"key":"C","text":"(C) Gross margin fell by 140 basis points."},{"key":"D","text":"(D) The board chose not to restore the dividend."}],"correct":"B","translation":"Điều nào KHÔNG được báo cáo ủng hộ? — Công ty đã cắt giảm nhân sự trong quý.","explanation":"Báo cáo chỉ nêu \"the hiring freeze imposed in the prior quarter\", tức ngừng tuyển mới, không hề nói giảm biên chế. A đúng (\"nearly all of the increase... favourable currency movements\"), C đúng (\"contracted by 140 basis points\"), D đúng (\"declined to reinstate the dividend\").","vocab":[{"word":"reinstate","pos":"v.","meaning":"phục hồi, khôi phục lại"},{"word":"leverage","pos":"n.","meaning":"đòn bẩy tài chính, mức vay nợ"},{"word":"guidance","pos":"n.","meaning":"dự báo định hướng của doanh nghiệp"}]},{"id":"reading-lv6-test-1-q158","questionNumber":158,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 158 (Part 7: Đọc hiểu)","passageTitle":"Questions 158-160 refer to the following commentary:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">COMMENTARY: THE QUIET COST OF NEARSHORING</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">The case for nearshoring is usually made in the language of resilience: shorter lead times, fewer disruptions, lower exposure to distant chokepoints. Rarely does the same analysis account for what is quietly surrendered in the process.</p><p class=\"mt-2\">Suppliers closer to home are, almost by definition, fewer; and a shorter supply chain with fewer participants is not necessarily a more robust one. I have sat through enough board presentations to recognise the pattern: a map with three arrows replacing one, a slide announcing a 40 percent cut in transit time, and no mention of the single plant on which the entire arrangement now depends.</p><p class=\"mt-2\">Resilience, it turns out, is less about distance than about redundancy, and redundancy is precisely what consolidation eliminates.</p></div>","questionText":"What is the author's attitude toward the usual case for nearshoring?","options":[{"key":"A","text":"(A) Strictly neutral, offering no evaluative judgement"},{"key":"B","text":"(B) Enthusiastically supportive of its conclusions"},{"key":"C","text":"(C) Cautiously skeptical of its underlying reasoning"},{"key":"D","text":"(D) Openly contemptuous of the firms that adopt it"}],"correct":"C","translation":"Thái độ của tác giả với lập luận thông thường ủng hộ nearshoring là gì? — Hoài nghi một cách thận trọng đối với cách lập luận đó.","explanation":"Tác giả dùng \"Rarely does the same analysis account for...\", \"not necessarily a more robust one\" và kết luận \"resilience... is less about distance than about redundancy\" — phê phán có cân nhắc, không phủ nhận hoàn toàn. Vì vậy B (ủng hộ nhiệt liệt) và D (khinh miệt) quá mức; A sai vì bài rõ ràng có đánh giá.","vocab":[{"word":"nearshoring","pos":"n.","meaning":"chuyển sản xuất về nước gần"},{"word":"chokepoint","pos":"n.","meaning":"điểm nghẽn, nút thắt"},{"word":"resilience","pos":"n.","meaning":"khả năng chống chịu, phục hồi"}]},{"id":"reading-lv6-test-1-q159","questionNumber":159,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 159 (Part 7: Đọc hiểu)","passageTitle":"Questions 158-160 refer to the following commentary:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">COMMENTARY: THE QUIET COST OF NEARSHORING</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">The case for nearshoring is usually made in the language of resilience: shorter lead times, fewer disruptions, lower exposure to distant chokepoints. Rarely does the same analysis account for what is quietly surrendered in the process.</p><p class=\"mt-2\">Suppliers closer to home are, almost by definition, fewer; and a shorter supply chain with fewer participants is not necessarily a more robust one. I have sat through enough board presentations to recognise the pattern: a map with three arrows replacing one, a slide announcing a 40 percent cut in transit time, and no mention of the single plant on which the entire arrangement now depends.</p><p class=\"mt-2\">Resilience, it turns out, is less about distance than about redundancy, and redundancy is precisely what consolidation eliminates.</p></div>","questionText":"What does the author suggest by mentioning \"a map with three arrows replacing one\"?","options":[{"key":"A","text":"(A) Board presentations are usually factually inaccurate."},{"key":"B","text":"(B) Three suppliers are always preferable to a single supplier."},{"key":"C","text":"(C) The visual suggests more diversification than the arrangement actually provides."},{"key":"D","text":"(D) Transit time is the decisive measure of supply-chain strength."}],"correct":"C","translation":"Tác giả ngụ ý gì khi nhắc tới \"tấm bản đồ có ba mũi tên thay cho một\"? — Hình ảnh đó gợi cảm giác đa dạng hoá nhiều hơn thực tế.","explanation":"Ngay sau hình ảnh này, tác giả nhấn mạnh \"no mention of the single plant on which the entire arrangement now depends\", cho thấy sơ đồ ba mũi tên che giấu sự phụ thuộc vào một cơ sở duy nhất. A và D là những khẳng định tuyệt đối không được bài viết nêu; B trái với hàm ý của tác giả.","vocab":[{"word":"diversification","pos":"n.","meaning":"sự đa dạng hoá"},{"word":"depend on","pos":"v.","meaning":"phụ thuộc vào"},{"word":"decisive","pos":"adj.","meaning":"mang tính quyết định"}]},{"id":"reading-lv6-test-1-q160","questionNumber":160,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 160 (Part 7: Đọc hiểu)","passageTitle":"Questions 158-160 refer to the following commentary:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">COMMENTARY: THE QUIET COST OF NEARSHORING</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">The case for nearshoring is usually made in the language of resilience: shorter lead times, fewer disruptions, lower exposure to distant chokepoints. Rarely does the same analysis account for what is quietly surrendered in the process.</p><p class=\"mt-2\">Suppliers closer to home are, almost by definition, fewer; and a shorter supply chain with fewer participants is not necessarily a more robust one. I have sat through enough board presentations to recognise the pattern: a map with three arrows replacing one, a slide announcing a 40 percent cut in transit time, and no mention of the single plant on which the entire arrangement now depends.</p><p class=\"mt-2\">Resilience, it turns out, is less about distance than about redundancy, and redundancy is precisely what consolidation eliminates.</p></div>","questionText":"The word \"redundancy\" in the final paragraph is closest in meaning to","options":[{"key":"A","text":"(A) dismissal of surplus staff"},{"key":"B","text":"(B) duplication of critical capacity"},{"key":"C","text":"(C) excessive expenditure on logistics"},{"key":"D","text":"(D) repetition of identical information"}],"correct":"B","translation":"\"Redundancy\" ở đoạn cuối gần nghĩa nhất với \"sự dự phòng, nhân bản năng lực thiết yếu\".","explanation":"Trong ngữ cảnh chuỗi cung ứng, \"redundancy\" là năng lực dự phòng (backup) giúp hệ thống chịu được gián đoạn; tác giả đối lập nó với \"consolidation\". A là nghĩa thông dụng khác của từ (sa thải lao động dư thừa) nhưng không hợp ngữ cảnh; C và D không liên quan.","vocab":[{"word":"eliminate","pos":"v.","meaning":"loại bỏ"},{"word":"robust","pos":"adj.","meaning":"vững chắc, chịu được tác động"},{"word":"lead time","pos":"n.","meaning":"thời gian giao hàng, thời gian chờ"}]},{"id":"reading-lv6-test-1-q161","questionNumber":161,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 161 (Part 7: Đọc hiểu)","passageTitle":"Questions 161-163 refer to the following advertisement:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">CARGOLUME: FREIGHT VISIBILITY IS NOT A DASHBOARD PROBLEM</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Freight visibility is not a dashboard problem. It is a decision problem. Cargolume's predictive routing engine analyses 140 data signals, from port congestion to customs dwell time and carrier reliability, and recommends the route that minimises total landed cost rather than merely transit time.</p><p class=\"mt-2\">Most platforms tell you where your shipment is. Ours tells you where it should be going. Implementation takes six weeks, not six months: our team migrates your historical lane data and configures exception rules before a single order is rerouted. Existing customers report an average 11 percent reduction in expedited freight spend within two quarters.</p><p class=\"mt-2\">Cargolume does not operate trucks, ships, or warehouses. We are, and will remain, strictly a software provider.</p></div>","questionText":"What is the primary purpose of the advertisement?","options":[{"key":"A","text":"(A) To advertise an integrated fleet-management service combining software with warehousing"},{"key":"B","text":"(B) To introduce a six-month onboarding programme designed to audit historical lane records"},{"key":"C","text":"(C) To guarantee a flat eleven-percent cut in carrier rates regardless of transit duration"},{"key":"D","text":"(D) To promote predictive routing software that recommends cost-optimal shipment paths"}],"correct":"D","translation":"Mục đích chính của quảng cáo là quảng bá phần mềm định tuyến dự báo giúp đề xuất lộ trình vận chuyển tối ưu chi phí.","explanation":"Quảng cáo nhấn mạnh Cargolume là phần mềm định tuyến dự báo phân tích 140 tín hiệu để tối thiểu hóa tổng chi phí hàng về kho ('total landed cost'), khác với các nền tảng chỉ theo dõi vị trí. A sai vì Cargolume không vận hành xe hay kho bãi ('does not operate trucks, ships, or warehouses'); C bóp méo mức giảm 11% (mức giảm trung bình chi phí gửi nhanh của khách hàng hiện tại trong hai quý, không phải bảo đảm giảm cước cố định); B sai thời gian triển khai ('six weeks, not six months').","vocab":[{"word":"predictive","pos":"adj.","meaning":"mang tính dự báo"},{"word":"dwell time","pos":"n.","meaning":"thời gian lưu bãi"},{"word":"landed cost","pos":"n.","meaning":"chi phí hàng về đến kho"}]},{"id":"reading-lv6-test-1-q162","questionNumber":162,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 162 (Part 7: Đọc hiểu)","passageTitle":"Questions 161-163 refer to the following advertisement:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">CARGOLUME: FREIGHT VISIBILITY IS NOT A DASHBOARD PROBLEM</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Freight visibility is not a dashboard problem. It is a decision problem. Cargolume's predictive routing engine analyses 140 data signals, from port congestion to customs dwell time and carrier reliability, and recommends the route that minimises total landed cost rather than merely transit time.</p><p class=\"mt-2\">Most platforms tell you where your shipment is. Ours tells you where it should be going. Implementation takes six weeks, not six months: our team migrates your historical lane data and configures exception rules before a single order is rerouted. Existing customers report an average 11 percent reduction in expedited freight spend within two quarters.</p><p class=\"mt-2\">Cargolume does not operate trucks, ships, or warehouses. We are, and will remain, strictly a software provider.</p></div>","questionText":"All of the following are claimed about Cargolume EXCEPT that it","options":[{"key":"A","text":"(A) draws on a very large number of data signals"},{"key":"B","text":"(B) can be implemented in a matter of weeks"},{"key":"C","text":"(C) helps clients cut spending on expedited freight"},{"key":"D","text":"(D) operates its own fleet of vehicles and vessels"}],"correct":"D","translation":"Tất cả những điều sau đều được quảng cáo nêu, NGOẠI TRỪ việc công ty tự vận hành đội xe và tàu.","explanation":"Đoạn cuối phủ định rõ: \"Cargolume does not operate trucks, ships, or warehouses\", nên D trái với quảng cáo. A đúng (\"140 data signals\"), B đúng (\"six weeks, not six months\"), C đúng (\"11 percent reduction in expedited freight spend\").","vocab":[{"word":"exception rule","pos":"n.","meaning":"quy tắc xử lý ngoại lệ"},{"word":"expedited","pos":"adj.","meaning":"hàng gửi nhanh, có phụ phí"},{"word":"migrate","pos":"v.","meaning":"chuyển dữ liệu sang hệ thống mới"}]},{"id":"reading-lv6-test-1-q163","questionNumber":163,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 163 (Part 7: Đọc hiểu)","passageTitle":"Questions 161-163 refer to the following advertisement:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">CARGOLUME: FREIGHT VISIBILITY IS NOT A DASHBOARD PROBLEM</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Freight visibility is not a dashboard problem. It is a decision problem. Cargolume's predictive routing engine analyses 140 data signals, from port congestion to customs dwell time and carrier reliability, and recommends the route that minimises total landed cost rather than merely transit time.</p><p class=\"mt-2\">Most platforms tell you where your shipment is. Ours tells you where it should be going. Implementation takes six weeks, not six months: our team migrates your historical lane data and configures exception rules before a single order is rerouted. Existing customers report an average 11 percent reduction in expedited freight spend within two quarters.</p><p class=\"mt-2\">Cargolume does not operate trucks, ships, or warehouses. We are, and will remain, strictly a software provider.</p></div>","questionText":"What can be inferred from the statement that Cargolume is strictly a software provider?","options":[{"key":"A","text":"(A) It intends to acquire a freight forwarder within two quarters."},{"key":"B","text":"(B) It competes with carriers by undercutting their rates."},{"key":"C","text":"(C) Its lack of transport assets is meant to reassure clients of its impartiality."},{"key":"D","text":"(D) It plans to phase out software in favour of managed transport."}],"correct":"C","translation":"Có thể suy ra gì từ việc Cargolume chỉ là nhà cung cấp phần mềm? — Việc không sở hữu tài sản vận tải nhằm trấn an khách hàng về tính khách quan.","explanation":"Việc nhấn mạnh \"does not operate trucks, ships, or warehouses\" và \"will remain, strictly a software provider\" cho thấy công ty muốn khách hàng thấy mình không có lợi ích riêng trong việc chọn tuyến hay hãng vận chuyển nào. A, B, D đều không có căn cứ, thậm chí trái với đoạn cuối.","vocab":[{"word":"impartiality","pos":"n.","meaning":"tính khách quan, không thiên vị"},{"word":"undercut","pos":"v.","meaning":"hạ giá thấp hơn đối thủ"},{"word":"phase out","pos":"v.","meaning":"loại bỏ dần"}]},{"id":"reading-lv6-test-1-q164","questionNumber":164,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 164 (Part 7: Đọc hiểu)","passageTitle":"Questions 164-166 refer to the following minutes:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">MINUTES OF THE PRODUCT STEWARDSHIP COMMITTEE</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">The committee convened on 4 March with seven of its nine members present. The chair opened by noting that the recall of the Model 12 adapter had consumed resources earmarked for the successor programme, and asked whether the launch date should be treated as fixed.</p><p class=\"mt-2\">After some discussion, the committee resolved that the date be retained but that the scope be reduced to two configurations, with the remainder deferred to a point release. The quality director dissented, arguing that compressing validation to eleven weeks would merely postpone, rather than eliminate, the underlying defect risk; her objection was recorded. The finance representative observed that the deferred configurations account for a substantial share of projected margin, a remark that went unaddressed.</p><p class=\"mt-2\">Action: engineering to circulate a revised validation plan by 18 March.</p></div>","questionText":"What is the primary purpose of this document?","options":[{"key":"A","text":"(A) To document a scope-reduction compromise along with formal reservations raised during deliberations"},{"key":"B","text":"(B) To ratify a postponed launch schedule requested jointly by the quality and finance representatives"},{"key":"C","text":"(C) To record unanimous committee approval for compressing product validation to eleven weeks"},{"key":"D","text":"(D) To assign engineering teams to resolve the Model 12 adapter recall by 18 March"}],"correct":"A","translation":"Mục đích chính của văn bản là ghi nhận thỏa hiệp thu hẹp phạm vi ra mắt cùng với những ý kiến bảo lưu chính thức nêu ra trong phiên họp.","explanation":"Biên bản ghi lại quyết định giữ nguyên ngày ra mắt nhưng cắt giảm còn hai cấu hình ('scope be reduced to two configurations'), đồng thời ghi nhận sự phản đối chính thức của giám đốc chất lượng ('her objection was recorded'). B sai vì ngày ra mắt được giữ nguyên không hoãn; C sai vì không đạt đồng thuận tuyệt đối ('dissented'); D sai vì mốc 18/3 là hạn gửi kế hoạch kiểm định mới cho sản phẩm kế nhiệm chứ không phải xử lý đợt thu hồi Model 12.","vocab":[{"word":"convene","pos":"v.","meaning":"triệu tập, họp"},{"word":"reservation","pos":"n.","meaning":"sự bảo lưu ý kiến, dè dặt"},{"word":"defer","pos":"v.","meaning":"hoãn, dời lại"}]},{"id":"reading-lv6-test-1-q165","questionNumber":165,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 165 (Part 7: Đọc hiểu)","passageTitle":"Questions 164-166 refer to the following minutes:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">MINUTES OF THE PRODUCT STEWARDSHIP COMMITTEE</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">The committee convened on 4 March with seven of its nine members present. The chair opened by noting that the recall of the Model 12 adapter had consumed resources earmarked for the successor programme, and asked whether the launch date should be treated as fixed.</p><p class=\"mt-2\">After some discussion, the committee resolved that the date be retained but that the scope be reduced to two configurations, with the remainder deferred to a point release. The quality director dissented, arguing that compressing validation to eleven weeks would merely postpone, rather than eliminate, the underlying defect risk; her objection was recorded. The finance representative observed that the deferred configurations account for a substantial share of projected margin, a remark that went unaddressed.</p><p class=\"mt-2\">Action: engineering to circulate a revised validation plan by 18 March.</p></div>","questionText":"What is the tone of the quality director's contribution?","options":[{"key":"A","text":"(A) Supportive of the compromise reached by the committee"},{"key":"B","text":"(B) Indifferent to the outcome of the discussion"},{"key":"C","text":"(C) Concerned that the compromise defers rather than resolves the risk"},{"key":"D","text":"(D) Confident that eleven weeks is more than sufficient"}],"correct":"C","translation":"Giọng điệu trong ý kiến của giám đốc chất lượng là lo ngại rằng thoả hiệp chỉ trì hoãn chứ không giải quyết rủi ro.","explanation":"Bà \"dissented\" và lập luận \"compressing validation to eleven weeks would merely postpone, rather than eliminate, the underlying defect risk\" — vừa phản đối vừa cảnh báo rủi ro tiềm ẩn. A và D ngược lại; B trái với việc bà đã chính thức phản đối.","vocab":[{"word":"dissent","pos":"v.","meaning":"phản đối, bất đồng ý kiến"},{"word":"validation","pos":"n.","meaning":"việc kiểm định, xác nhận"},{"word":"underlying","pos":"adj.","meaning":"tiềm ẩn, nằm bên dưới"}]},{"id":"reading-lv6-test-1-q166","questionNumber":166,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 166 (Part 7: Đọc hiểu)","passageTitle":"Questions 164-166 refer to the following minutes:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">MINUTES OF THE PRODUCT STEWARDSHIP COMMITTEE</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">The committee convened on 4 March with seven of its nine members present. The chair opened by noting that the recall of the Model 12 adapter had consumed resources earmarked for the successor programme, and asked whether the launch date should be treated as fixed.</p><p class=\"mt-2\">After some discussion, the committee resolved that the date be retained but that the scope be reduced to two configurations, with the remainder deferred to a point release. The quality director dissented, arguing that compressing validation to eleven weeks would merely postpone, rather than eliminate, the underlying defect risk; her objection was recorded. The finance representative observed that the deferred configurations account for a substantial share of projected margin, a remark that went unaddressed.</p><p class=\"mt-2\">Action: engineering to circulate a revised validation plan by 18 March.</p></div>","questionText":"What can be inferred from the remark that \"went unaddressed\"?","options":[{"key":"A","text":"(A) The finance representative was absent when the remark was made."},{"key":"B","text":"(B) The committee had already reviewed detailed margin projections."},{"key":"C","text":"(C) The financial consequence of the decision was left unresolved."},{"key":"D","text":"(D) The remark was struck from the official record."}],"correct":"C","translation":"Có thể suy ra gì từ việc lời nhận xét đó \"không được đề cập tới\"? — Hệ quả tài chính của quyết định vẫn chưa được giải quyết.","explanation":"Nhận xét rằng các cấu hình bị hoãn chiếm \"a substantial share of projected margin\" mà \"went unaddressed\" nghĩa là uỷ ban không bàn tiếp, để ngỏ tác động tài chính. Văn bản ghi \"seven of its nine members present\" và không nói ai vắng, nên A không được chứng minh; D trái với việc biên bản vẫn ghi lại lời nhận xét.","vocab":[{"word":"projected","pos":"adj.","meaning":"dự kiến, dự báo"},{"word":"configuration","pos":"n.","meaning":"cấu hình, phiên bản"},{"word":"circulate","pos":"v.","meaning":"gửi vòng, lưu hành nội bộ"}]},{"id":"reading-lv6-test-1-q167","questionNumber":167,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 167 (Part 7: Đọc hiểu)","passageTitle":"Questions 167-169 refer to the following price schedule:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">ENTERPRISE SUPPORT PRICING: SCHEDULE B</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">The following schedule supersedes Schedule A of the master support agreement dated 14 April and takes effect on renewal. Fees are quoted per site, in United States dollars, and exclude applicable taxes.</p><table class=\"mt-2 w-full border-collapse text-sm\"><tr><th class=\"border border-neutral-400 px-2 py-1 text-left\">Tier</th><th class=\"border border-neutral-400 px-2 py-1 text-left\">Annual fee</th><th class=\"border border-neutral-400 px-2 py-1 text-left\">Response target</th><th class=\"border border-neutral-400 px-2 py-1 text-left\">Incidents included</th><th class=\"border border-neutral-400 px-2 py-1 text-left\">Overage per incident</th></tr><tr><td class=\"border border-neutral-400 px-2 py-1\">Essential</td><td class=\"border border-neutral-400 px-2 py-1\">12,000</td><td class=\"border border-neutral-400 px-2 py-1\">8 business hours</td><td class=\"border border-neutral-400 px-2 py-1\">10</td><td class=\"border border-neutral-400 px-2 py-1\">450</td></tr><tr><td class=\"border border-neutral-400 px-2 py-1\">Professional</td><td class=\"border border-neutral-400 px-2 py-1\">28,000</td><td class=\"border border-neutral-400 px-2 py-1\">4 business hours</td><td class=\"border border-neutral-400 px-2 py-1\">25</td><td class=\"border border-neutral-400 px-2 py-1\">300</td></tr><tr><td class=\"border border-neutral-400 px-2 py-1\">Enterprise</td><td class=\"border border-neutral-400 px-2 py-1\">54,000</td><td class=\"border border-neutral-400 px-2 py-1\">1 hour, 24/7</td><td class=\"border border-neutral-400 px-2 py-1\">60</td><td class=\"border border-neutral-400 px-2 py-1\">180</td></tr></table><p class=\"mt-2\">Multi-year commitments receive a 7 percent reduction on the second and subsequent years. Incident credits are applied only where a response target is missed by more than two hours; scheduled maintenance windows are excluded from all response calculations.</p></div>","questionText":"What applies to a Professional-tier client that logs 30 incidents in a single year?","options":[{"key":"A","text":"(A) The client receives a credit for the excess incidents."},{"key":"B","text":"(B) All thirty incidents are covered by the annual fee."},{"key":"C","text":"(C) The client must upgrade to Enterprise before support continues."},{"key":"D","text":"(D) Five incidents are chargeable at the overage rate."}],"correct":"D","translation":"Điều gì áp dụng cho khách hàng gói Professional ghi nhận 30 sự cố trong một năm? — Năm sự cố vượt định mức sẽ bị tính theo giá overage.","explanation":"Bảng giá nêu Professional gồm \"25\" sự cố, nên 30 − 25 = 5 sự cố vượt mức, mỗi sự cố tính 300 đô-la. B sai vì chỉ 25 sự cố nằm trong phí năm; C và A không xuất hiện trong quy định (credit chỉ áp dụng khi trễ phản hồi quá hai giờ).","vocab":[{"word":"supersede","pos":"v.","meaning":"thay thế, huỷ bỏ cái cũ"},{"word":"overage","pos":"n.","meaning":"phần vượt định mức"},{"word":"exclude","pos":"v.","meaning":"loại trừ, không bao gồm"}]},{"id":"reading-lv6-test-1-q168","questionNumber":168,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 168 (Part 7: Đọc hiểu)","passageTitle":"Questions 167-169 refer to the following price schedule:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">ENTERPRISE SUPPORT PRICING: SCHEDULE B</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">The following schedule supersedes Schedule A of the master support agreement dated 14 April and takes effect on renewal. Fees are quoted per site, in United States dollars, and exclude applicable taxes.</p><table class=\"mt-2 w-full border-collapse text-sm\"><tr><th class=\"border border-neutral-400 px-2 py-1 text-left\">Tier</th><th class=\"border border-neutral-400 px-2 py-1 text-left\">Annual fee</th><th class=\"border border-neutral-400 px-2 py-1 text-left\">Response target</th><th class=\"border border-neutral-400 px-2 py-1 text-left\">Incidents included</th><th class=\"border border-neutral-400 px-2 py-1 text-left\">Overage per incident</th></tr><tr><td class=\"border border-neutral-400 px-2 py-1\">Essential</td><td class=\"border border-neutral-400 px-2 py-1\">12,000</td><td class=\"border border-neutral-400 px-2 py-1\">8 business hours</td><td class=\"border border-neutral-400 px-2 py-1\">10</td><td class=\"border border-neutral-400 px-2 py-1\">450</td></tr><tr><td class=\"border border-neutral-400 px-2 py-1\">Professional</td><td class=\"border border-neutral-400 px-2 py-1\">28,000</td><td class=\"border border-neutral-400 px-2 py-1\">4 business hours</td><td class=\"border border-neutral-400 px-2 py-1\">25</td><td class=\"border border-neutral-400 px-2 py-1\">300</td></tr><tr><td class=\"border border-neutral-400 px-2 py-1\">Enterprise</td><td class=\"border border-neutral-400 px-2 py-1\">54,000</td><td class=\"border border-neutral-400 px-2 py-1\">1 hour, 24/7</td><td class=\"border border-neutral-400 px-2 py-1\">60</td><td class=\"border border-neutral-400 px-2 py-1\">180</td></tr></table><p class=\"mt-2\">Multi-year commitments receive a 7 percent reduction on the second and subsequent years. Incident credits are applied only where a response target is missed by more than two hours; scheduled maintenance windows are excluded from all response calculations.</p></div>","questionText":"Which of the following is NOT supported by the schedule?","options":[{"key":"A","text":"(A) Quoted fees do not include applicable taxes."},{"key":"B","text":"(B) Response targets apply during scheduled maintenance windows."},{"key":"C","text":"(C) A reduction applies from the second year of a multi-year commitment."},{"key":"D","text":"(D) A credit requires a delay of more than two hours."}],"correct":"B","translation":"Điều nào KHÔNG được bảng giá ủng hộ? — Cam kết thời gian phản hồi vẫn áp dụng trong các khung bảo trì định kỳ.","explanation":"Câu cuối ghi \"scheduled maintenance windows are excluded from all response calculations\", tức thời gian bảo trì không tính vào cam kết phản hồi, nên B trái văn bản. A (\"exclude applicable taxes\"), C (\"7 percent reduction on the second and subsequent years\") và D (\"missed by more than two hours\") đều được nêu rõ.","vocab":[{"word":"maintenance window","pos":"n.","meaning":"khung thời gian bảo trì"},{"word":"credit","pos":"n.","meaning":"khoản giảm trừ, bù trừ"},{"word":"applicable","pos":"adj.","meaning":"áp dụng, có hiệu lực"}]},{"id":"reading-lv6-test-1-q169","questionNumber":169,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 169 (Part 7: Đọc hiểu)","passageTitle":"Questions 167-169 refer to the following price schedule:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">ENTERPRISE SUPPORT PRICING: SCHEDULE B</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">The following schedule supersedes Schedule A of the master support agreement dated 14 April and takes effect on renewal. Fees are quoted per site, in United States dollars, and exclude applicable taxes.</p><table class=\"mt-2 w-full border-collapse text-sm\"><tr><th class=\"border border-neutral-400 px-2 py-1 text-left\">Tier</th><th class=\"border border-neutral-400 px-2 py-1 text-left\">Annual fee</th><th class=\"border border-neutral-400 px-2 py-1 text-left\">Response target</th><th class=\"border border-neutral-400 px-2 py-1 text-left\">Incidents included</th><th class=\"border border-neutral-400 px-2 py-1 text-left\">Overage per incident</th></tr><tr><td class=\"border border-neutral-400 px-2 py-1\">Essential</td><td class=\"border border-neutral-400 px-2 py-1\">12,000</td><td class=\"border border-neutral-400 px-2 py-1\">8 business hours</td><td class=\"border border-neutral-400 px-2 py-1\">10</td><td class=\"border border-neutral-400 px-2 py-1\">450</td></tr><tr><td class=\"border border-neutral-400 px-2 py-1\">Professional</td><td class=\"border border-neutral-400 px-2 py-1\">28,000</td><td class=\"border border-neutral-400 px-2 py-1\">4 business hours</td><td class=\"border border-neutral-400 px-2 py-1\">25</td><td class=\"border border-neutral-400 px-2 py-1\">300</td></tr><tr><td class=\"border border-neutral-400 px-2 py-1\">Enterprise</td><td class=\"border border-neutral-400 px-2 py-1\">54,000</td><td class=\"border border-neutral-400 px-2 py-1\">1 hour, 24/7</td><td class=\"border border-neutral-400 px-2 py-1\">60</td><td class=\"border border-neutral-400 px-2 py-1\">180</td></tr></table><p class=\"mt-2\">Multi-year commitments receive a 7 percent reduction on the second and subsequent years. Incident credits are applied only where a response target is missed by more than two hours; scheduled maintenance windows are excluded from all response calculations.</p></div>","questionText":"What can be inferred from the way overage rates change across tiers?","options":[{"key":"A","text":"(A) Enterprise clients are discouraged from reporting incidents."},{"key":"B","text":"(B) Lower tiers are subsidised by clients that never report incidents."},{"key":"C","text":"(C) Support staff assigned to higher tiers are less qualified."},{"key":"D","text":"(D) Higher tiers are priced on the assumption of proportionally heavier usage."}],"correct":"D","translation":"Có thể suy ra gì từ cách giá overage thay đổi giữa các gói? — Các gói cao được định giá dựa trên giả định mức sử dụng lớn hơn.","explanation":"Khi phí năm tăng từ 12.000 lên 54.000, số sự cố bao gồm tăng từ 10 lên 60 và giá mỗi sự cố vượt mức giảm từ 450 xuống 180 — dấu hiệu gói cao giả định khối lượng sử dụng lớn nên đơn giá biên thấp hơn. B, C, A không có căn cứ trong bảng hay ghi chú.","vocab":[{"word":"proportionally","pos":"adv.","meaning":"theo tỷ lệ"},{"word":"subsidise","pos":"v.","meaning":"trợ cấp, bù đắp chi phí"},{"word":"assumption","pos":"n.","meaning":"giả định"}]},{"id":"reading-lv6-test-1-q170","questionNumber":170,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 170 (Part 7: Đọc hiểu)","passageTitle":"Questions 170-172 refer to the following itinerary:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">SITE VISIT ITINERARY: PORT OF ROTTERDAM EXPANSION</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Delegates should note that the 07:40 coach departs from the Amstel annex, not the main terminal, as the latter remains closed for resurfacing. The morning session has been moved forward by 45 minutes to accommodate the harbour master, who must leave by noon; consequently the buffer originally scheduled for document review has been eliminated.</p><p class=\"mt-2\">Access to the northern quay requires photographic identification and, for anyone carrying recording equipment, prior clearance from the terminal operator; requests submitted on the day will not be processed. The closing dinner will proceed as planned, though the venue has been changed to the Boompjes room to accommodate a larger party.</p></div>","questionText":"What is the main purpose of the itinerary?","options":[{"key":"A","text":"(A) To notify delegates that the northern quay inspection has been cancelled due to resurfacing"},{"key":"B","text":"(B) To confirm an extended morning session accommodating additional document-review briefings"},{"key":"C","text":"(C) To inform delegates of logistical, scheduling, and venue modifications for a site visit"},{"key":"D","text":"(D) To outline same-day clearance procedures for delegates carrying photographic recording gear"}],"correct":"C","translation":"Mục đích chính của lịch trình là thông báo cho đại biểu về các điều chỉnh hậu cần, thời gian và địa điểm của chuyến thăm thực địa.","explanation":"Văn bản thông báo hàng loạt thay đổi cho chuyến thăm: đổi điểm đón xe buýt sang khu phụ Amstel, đẩy sớm phiên sáng 45 phút (bỏ thời gian xem tài liệu), và đổi địa điểm tiệc tối sang phòng Boompjes. A bóp méo việc đóng cửa nhà ga chính (cầu cảng phía bắc vẫn đón khách có giấy phép); B sai vì thời gian xem tài liệu đã bị cắt bỏ chứ không mở rộng; D trái với quy định yêu cầu xin phép trong ngày sẽ không được xử lý.","vocab":[{"word":"delegate","pos":"n.","meaning":"đại biểu"},{"word":"resurfacing","pos":"n.","meaning":"việc làm lại mặt đường"},{"word":"accommodate","pos":"v.","meaning":"đáp ứng, tạo điều kiện cho"}]},{"id":"reading-lv6-test-1-q171","questionNumber":171,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 171 (Part 7: Đọc hiểu)","passageTitle":"Questions 170-172 refer to the following itinerary:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">SITE VISIT ITINERARY: PORT OF ROTTERDAM EXPANSION</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Delegates should note that the 07:40 coach departs from the Amstel annex, not the main terminal, as the latter remains closed for resurfacing. The morning session has been moved forward by 45 minutes to accommodate the harbour master, who must leave by noon; consequently the buffer originally scheduled for document review has been eliminated.</p><p class=\"mt-2\">Access to the northern quay requires photographic identification and, for anyone carrying recording equipment, prior clearance from the terminal operator; requests submitted on the day will not be processed. The closing dinner will proceed as planned, though the venue has been changed to the Boompjes room to accommodate a larger party.</p></div>","questionText":"The word \"buffer\" in paragraph 1 is closest in meaning to","options":[{"key":"A","text":"(A) a physical barrier at the quay"},{"key":"B","text":"(B) a margin of time held in reserve"},{"key":"C","text":"(C) a discount on the coach fare"},{"key":"D","text":"(D) a summary of the day's documents"}],"correct":"B","translation":"\"Buffer\" trong đoạn 1 gần nghĩa nhất với \"khoảng thời gian dự trữ\".","explanation":"\"the buffer originally scheduled for document review has been eliminated\" chỉ khoảng thời gian đệm vốn dành để xem tài liệu, nay bị cắt vì lịch dồn sớm. A là nghĩa vật lý của \"buffer\" nhưng không hợp ngữ cảnh; C và D không liên quan.","vocab":[{"word":"eliminate","pos":"v.","meaning":"loại bỏ, cắt bỏ"},{"word":"quay","pos":"n.","meaning":"cầu cảng"},{"word":"clearance","pos":"n.","meaning":"sự cho phép, giấy thông hành"}]},{"id":"reading-lv6-test-1-q172","questionNumber":172,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 172 (Part 7: Đọc hiểu)","passageTitle":"Questions 170-172 refer to the following itinerary:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">SITE VISIT ITINERARY: PORT OF ROTTERDAM EXPANSION</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Delegates should note that the 07:40 coach departs from the Amstel annex, not the main terminal, as the latter remains closed for resurfacing. The morning session has been moved forward by 45 minutes to accommodate the harbour master, who must leave by noon; consequently the buffer originally scheduled for document review has been eliminated.</p><p class=\"mt-2\">Access to the northern quay requires photographic identification and, for anyone carrying recording equipment, prior clearance from the terminal operator; requests submitted on the day will not be processed. The closing dinner will proceed as planned, though the venue has been changed to the Boompjes room to accommodate a larger party.</p></div>","questionText":"Which of the following is NOT supported by the itinerary?","options":[{"key":"A","text":"(A) The coach leaves from a different location than originally intended."},{"key":"B","text":"(B) Same-day clearance requests are accepted if identification is presented."},{"key":"C","text":"(C) Visitors carrying recording equipment must obtain clearance in advance."},{"key":"D","text":"(D) The time previously reserved for reviewing documents has been removed."}],"correct":"B","translation":"Điều nào KHÔNG được lịch trình ủng hộ? — Yêu cầu cấp phép trong ngày vẫn được chấp nhận nếu xuất trình giấy tờ tuỳ thân.","explanation":"Văn bản ghi rõ \"requests submitted on the day will not be processed\", nên B trái nội dung. A đúng (\"not the main terminal\"), D đúng (\"buffer... has been eliminated\"), C đúng (\"prior clearance from the terminal operator\").","vocab":[{"word":"identification","pos":"n.","meaning":"giấy tờ tuỳ thân"},{"word":"venue","pos":"n.","meaning":"địa điểm tổ chức"},{"word":"proceed","pos":"v.","meaning":"tiến hành, diễn ra"}]},{"id":"reading-lv6-test-1-q173","questionNumber":173,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 173 (Part 7: Đọc hiểu)","passageTitle":"Questions 173-175 refer to the following survey summary:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">CUSTOMER SATISFACTION SURVEY: MANAGEMENT SUMMARY</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Of the 1,840 clients invited, 612 responded, a rate of 33 percent that is broadly consistent with last year's exercise. Headline satisfaction held at 4.1 out of 5.</p><p class=\"mt-2\">That stability, however, conceals considerable movement beneath the surface: scores for account management improved markedly, while scores for onboarding fell by half a point, the steepest decline recorded in five years. Respondents who had contacted support in the preceding quarter were nearly twice as likely to report dissatisfaction, a pattern that merits more attention than the aggregate figure alone would suggest.</p><p class=\"mt-2\">Written comments were dominated by two themes, clarity of invoicing and the pace of technical onboarding, neither of which can be addressed by the customer-facing teams alone.</p></div>","questionText":"What is the author's attitude toward the headline satisfaction score?","options":[{"key":"A","text":"(A) It should be withdrawn from the report entirely."},{"key":"B","text":"(B) It is wholly unreliable because the response rate was too low."},{"key":"C","text":"(C) It proves that service quality has improved across every area."},{"key":"D","text":"(D) It is reassuring on its own but potentially misleading as a summary."}],"correct":"D","translation":"Thái độ của tác giả với điểm hài lòng tổng thể: đáng yên tâm nhưng có thể gây hiểu lầm nếu dùng làm tóm tắt.","explanation":"Tác giả nêu điểm 4,1 giữ nguyên nhưng ngay sau đó dùng \"however\" và \"conceals considerable movement beneath the surface\", cho thấy con số tổng hợp che khuất biến động thực tế. Không có chỗ nào nói tỷ lệ phản hồi quá thấp (B) — ngược lại là \"broadly consistent\"; C mâu thuẫn với việc điểm onboarding giảm; A quá cực đoan.","vocab":[{"word":"aggregate","pos":"adj.","meaning":"tổng hợp"},{"word":"markedly","pos":"adv.","meaning":"rõ rệt"},{"word":"onboarding","pos":"n.","meaning":"quá trình tiếp nhận, khởi tạo khách hàng"}]},{"id":"reading-lv6-test-1-q174","questionNumber":174,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 174 (Part 7: Đọc hiểu)","passageTitle":"Questions 173-175 refer to the following survey summary:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">CUSTOMER SATISFACTION SURVEY: MANAGEMENT SUMMARY</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Of the 1,840 clients invited, 612 responded, a rate of 33 percent that is broadly consistent with last year's exercise. Headline satisfaction held at 4.1 out of 5.</p><p class=\"mt-2\">That stability, however, conceals considerable movement beneath the surface: scores for account management improved markedly, while scores for onboarding fell by half a point, the steepest decline recorded in five years. Respondents who had contacted support in the preceding quarter were nearly twice as likely to report dissatisfaction, a pattern that merits more attention than the aggregate figure alone would suggest.</p><p class=\"mt-2\">Written comments were dominated by two themes, clarity of invoicing and the pace of technical onboarding, neither of which can be addressed by the customer-facing teams alone.</p></div>","questionText":"What does the author imply about the two recurring themes in the comments?","options":[{"key":"A","text":"(A) They can be resolved by retraining the customer-facing teams."},{"key":"B","text":"(B) They reflect the views of a small and unrepresentative minority."},{"key":"C","text":"(C) They are less important than the headline satisfaction score."},{"key":"D","text":"(D) They require action from parts of the business outside customer service."}],"correct":"D","translation":"Tác giả ngụ ý hai chủ đề lặp lại cần sự vào cuộc của các bộ phận ngoài nhóm tiếp xúc khách hàng.","explanation":"Câu cuối khẳng định hai chủ đề \"neither of which can be addressed by the customer-facing teams alone\", tức cần phối hợp liên bộ phận. A trái trực tiếp; C trái với việc tác giả coi trọng các tín hiệu này; B không được dữ liệu khảo sát hỗ trợ.","vocab":[{"word":"recurring","pos":"adj.","meaning":"lặp đi lặp lại"},{"word":"invoicing","pos":"n.","meaning":"việc lập và gửi hoá đơn"},{"word":"address","pos":"v.","meaning":"xử lý, giải quyết"}]},{"id":"reading-lv6-test-1-q175","questionNumber":175,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 175 (Part 7: Đọc hiểu)","passageTitle":"Questions 173-175 refer to the following survey summary:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">CUSTOMER SATISFACTION SURVEY: MANAGEMENT SUMMARY</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Of the 1,840 clients invited, 612 responded, a rate of 33 percent that is broadly consistent with last year's exercise. Headline satisfaction held at 4.1 out of 5.</p><p class=\"mt-2\">That stability, however, conceals considerable movement beneath the surface: scores for account management improved markedly, while scores for onboarding fell by half a point, the steepest decline recorded in five years. Respondents who had contacted support in the preceding quarter were nearly twice as likely to report dissatisfaction, a pattern that merits more attention than the aggregate figure alone would suggest.</p><p class=\"mt-2\">Written comments were dominated by two themes, clarity of invoicing and the pace of technical onboarding, neither of which can be addressed by the customer-facing teams alone.</p></div>","questionText":"The phrase \"merits more attention\" in paragraph 2 is closest in meaning to","options":[{"key":"A","text":"(A) defies statistical measurement"},{"key":"B","text":"(B) attracts undue criticism"},{"key":"C","text":"(C) warrants closer scrutiny"},{"key":"D","text":"(D) precedes formal escalation"}],"correct":"C","translation":"Cụm 'merits more attention' trong đoạn 2 gần nghĩa nhất với 'xứng đáng được xem xét kỹ lưỡng hơn'.","explanation":"Trong ngữ cảnh tỷ lệ không hài lòng ở nhóm từng liên hệ bộ phận hỗ trợ tăng gần gấp đôi, cụm 'a pattern that merits more attention than the aggregate figure alone would suggest' nghĩa là xu hướng này đòi hỏi phải được rà soát sâu sát hơn ('warrants closer scrutiny'). B (thu hút chỉ trích quá mức), A (không thể đo lường) và D (diễn ra trước khi leo thang chính thức) đều sai sắc thái nghĩa.","vocab":[{"word":"warrant","pos":"v.","meaning":"xứng đáng, đòi hỏi phải có"},{"word":"scrutiny","pos":"n.","meaning":"sự xem xét kỹ lưỡng"},{"word":"merit","pos":"v.","meaning":"đáng được, xứng đáng nhận"}]},{"id":"reading-lv6-test-1-q176","questionNumber":176,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 176 (Part 7: Đọc hiểu)","passageTitle":"Questions 176-180 refer to the following e-mail and invoice:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Priya Raghunathan, Procurement Manager, Halcyon Ridge Furniture<br>To: Accounts Receivable, Meridian Components<br>Subject: Invoice MC-4471 — quantity and freight discrepancy</p><p class=\"mt-2\">Dear Ms. Okafor,</p><p class=\"mt-2\">Thank you for dispatching the oak veneer panels ahead of schedule. Before we release payment on invoice MC-4471, however, our warehouse team has flagged two items that require your confirmation.</p><p class=\"mt-2\">Your invoice lists 240 panels, whereas the delivery note accompanying the shipment records 225. Our receiving clerk counted the pallets twice and photographed each one; the figure of 225 appears to be accurate. In addition, the invoice applies a fuel surcharge of 4.5 percent, although clause 7 of our master supply agreement caps all freight-related surcharges at 3 percent for the duration of the contract.</p><p class=\"mt-2\">We remain keen to keep the revised delivery dates for the Riverside project on track, so I would ask that you issue a corrected invoice by Friday rather than delay settlement. Once the amended document arrives, our finance department can process the transfer within two business days.</p><p class=\"mt-2\">Kind regards,<br>Priya Raghunathan</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Invoice</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">MERIDIAN COMPONENTS — COMMERCIAL INVOICE<br>Invoice no. MC-4471 | Date: 12 March | Terms: net 30<br>Bill to: Halcyon Ridge Furniture, 88 Foundry Lane<br>Purchase order: HRF-2291</p><table class=\"mt-2 w-full text-left\"><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr><tr><td>Oak veneer panels, 3 mm</td><td>240</td><td>$38.50</td><td>$9,240.00</td></tr><tr><td>Edge banding, 50 m rolls</td><td>12</td><td>$22.00</td><td>$264.00</td></tr><tr><td>Subtotal</td><td></td><td></td><td>$9,504.00</td></tr><tr><td>Freight (fuel surcharge 4.5%)</td><td></td><td></td><td>$427.68</td></tr><tr><td>Total due</td><td></td><td></td><td>$9,931.68</td></tr></table><p class=\"mt-2\">Goods shipped 9 March via Northgate Freight, consignment NF-77120. Claims for shortages must be submitted in writing within ten days of receipt. Please quote the invoice number with every remittance and remit by bank transfer to Meridian Components, account 4471-8820, quoting the purchase order.</p></div>","questionText":"What is the primary purpose of the e-mail?","options":[{"key":"A","text":"(A) To request prompt billing corrections so settlement can proceed without jeopardising a schedule"},{"key":"B","text":"(B) To dispute the unit price billed for oak veneer panels ahead of the net-30 deadline"},{"key":"C","text":"(C) To report that damaged veneer panels were rejected by the warehouse receiving clerk"},{"key":"D","text":"(D) To propose revising clause 7 of the master supply agreement before Friday's transfer"}],"correct":"A","translation":"Mục đích chính của e-mail là yêu cầu chỉnh sửa hoá đơn kịp thời để việc thanh toán được tiến hành mà không làm ảnh hưởng đến tiến độ dự án.","explanation":"Người gửi nêu hai sai sót cần xác nhận trên hoá đơn (số lượng 240 vs 225 và phụ phí nhiên liệu 4,5% vs trần 3%) và đề nghị xuất lại hoá đơn trước thứ Sáu để không làm trễ việc thanh toán và giữ tiến độ dự án Riverside. B sai vì đơn giá $38.50 không bị tranh chấp; C sai vì hàng bị thiếu số lượng chứ không nêu bị hư hỏng; D sai vì người viết đang viện dẫn giới hạn sẵn có của điều khoản 7 chứ không đề nghị sửa hợp đồng.","vocab":[{"word":"release payment","pos":"v. phr.","meaning":"giải ngân, thực hiện thanh toán"},{"word":"dispatch","pos":"v.","meaning":"gửi hàng, xuất hàng"},{"word":"jeopardise","pos":"v.","meaning":"gây nguy hiểm, làm ảnh hưởng xấu"}]},{"id":"reading-lv6-test-1-q177","questionNumber":177,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 177 (Part 7: Đọc hiểu)","passageTitle":"Questions 176-180 refer to the following e-mail and invoice:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Priya Raghunathan, Procurement Manager, Halcyon Ridge Furniture<br>To: Accounts Receivable, Meridian Components<br>Subject: Invoice MC-4471 — quantity and freight discrepancy</p><p class=\"mt-2\">Dear Ms. Okafor,</p><p class=\"mt-2\">Thank you for dispatching the oak veneer panels ahead of schedule. Before we release payment on invoice MC-4471, however, our warehouse team has flagged two items that require your confirmation.</p><p class=\"mt-2\">Your invoice lists 240 panels, whereas the delivery note accompanying the shipment records 225. Our receiving clerk counted the pallets twice and photographed each one; the figure of 225 appears to be accurate. In addition, the invoice applies a fuel surcharge of 4.5 percent, although clause 7 of our master supply agreement caps all freight-related surcharges at 3 percent for the duration of the contract.</p><p class=\"mt-2\">We remain keen to keep the revised delivery dates for the Riverside project on track, so I would ask that you issue a corrected invoice by Friday rather than delay settlement. Once the amended document arrives, our finance department can process the transfer within two business days.</p><p class=\"mt-2\">Kind regards,<br>Priya Raghunathan</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Invoice</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">MERIDIAN COMPONENTS — COMMERCIAL INVOICE<br>Invoice no. MC-4471 | Date: 12 March | Terms: net 30<br>Bill to: Halcyon Ridge Furniture, 88 Foundry Lane<br>Purchase order: HRF-2291</p><table class=\"mt-2 w-full text-left\"><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr><tr><td>Oak veneer panels, 3 mm</td><td>240</td><td>$38.50</td><td>$9,240.00</td></tr><tr><td>Edge banding, 50 m rolls</td><td>12</td><td>$22.00</td><td>$264.00</td></tr><tr><td>Subtotal</td><td></td><td></td><td>$9,504.00</td></tr><tr><td>Freight (fuel surcharge 4.5%)</td><td></td><td></td><td>$427.68</td></tr><tr><td>Total due</td><td></td><td></td><td>$9,931.68</td></tr></table><p class=\"mt-2\">Goods shipped 9 March via Northgate Freight, consignment NF-77120. Claims for shortages must be submitted in writing within ten days of receipt. Please quote the invoice number with every remittance and remit by bank transfer to Meridian Components, account 4471-8820, quoting the purchase order.</p></div>","questionText":"What does the reference to the Riverside project suggest about Halcyon Ridge's priorities?","options":[{"key":"A","text":"(A) It will accept the overcharge in order to settle the account immediately."},{"key":"B","text":"(B) It expects Meridian to absorb the entire freight surcharge."},{"key":"C","text":"(C) It intends to terminate the supply agreement once the contract expires."},{"key":"D","text":"(D) Meeting the construction timetable outweighs settling the account at once."}],"correct":"D","translation":"Việc nhắc tới dự án Riverside cho thấy ưu tiên của Halcyon Ridge là gì? — Giữ đúng tiến độ dự án quan trọng hơn việc thanh toán ngay.","explanation":"Cụm 'We remain keen to keep the revised delivery dates for the Riverside project on track, so I would ask that you issue a corrected invoice ... rather than delay settlement' cho thấy công ty ưu tiên tiến độ giao hàng cho dự án hơn là thanh toán tức thời. Việc yêu cầu hoá đơn điều chỉnh chứng tỏ họ không chấp nhận khoản thu vượt (loại A).","vocab":[{"word":"on track","pos":"adj. phr.","meaning":"đúng tiến độ"},{"word":"settlement","pos":"n.","meaning":"sự thanh toán, tất toán"},{"word":"overcharge","pos":"n.","meaning":"khoản thu vượt giá"}]},{"id":"reading-lv6-test-1-q178","questionNumber":178,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 178 (Part 7: Đọc hiểu)","passageTitle":"Questions 176-180 refer to the following e-mail and invoice:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Priya Raghunathan, Procurement Manager, Halcyon Ridge Furniture<br>To: Accounts Receivable, Meridian Components<br>Subject: Invoice MC-4471 — quantity and freight discrepancy</p><p class=\"mt-2\">Dear Ms. Okafor,</p><p class=\"mt-2\">Thank you for dispatching the oak veneer panels ahead of schedule. Before we release payment on invoice MC-4471, however, our warehouse team has flagged two items that require your confirmation.</p><p class=\"mt-2\">Your invoice lists 240 panels, whereas the delivery note accompanying the shipment records 225. Our receiving clerk counted the pallets twice and photographed each one; the figure of 225 appears to be accurate. In addition, the invoice applies a fuel surcharge of 4.5 percent, although clause 7 of our master supply agreement caps all freight-related surcharges at 3 percent for the duration of the contract.</p><p class=\"mt-2\">We remain keen to keep the revised delivery dates for the Riverside project on track, so I would ask that you issue a corrected invoice by Friday rather than delay settlement. Once the amended document arrives, our finance department can process the transfer within two business days.</p><p class=\"mt-2\">Kind regards,<br>Priya Raghunathan</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Invoice</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">MERIDIAN COMPONENTS — COMMERCIAL INVOICE<br>Invoice no. MC-4471 | Date: 12 March | Terms: net 30<br>Bill to: Halcyon Ridge Furniture, 88 Foundry Lane<br>Purchase order: HRF-2291</p><table class=\"mt-2 w-full text-left\"><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr><tr><td>Oak veneer panels, 3 mm</td><td>240</td><td>$38.50</td><td>$9,240.00</td></tr><tr><td>Edge banding, 50 m rolls</td><td>12</td><td>$22.00</td><td>$264.00</td></tr><tr><td>Subtotal</td><td></td><td></td><td>$9,504.00</td></tr><tr><td>Freight (fuel surcharge 4.5%)</td><td></td><td></td><td>$427.68</td></tr><tr><td>Total due</td><td></td><td></td><td>$9,931.68</td></tr></table><p class=\"mt-2\">Goods shipped 9 March via Northgate Freight, consignment NF-77120. Claims for shortages must be submitted in writing within ten days of receipt. Please quote the invoice number with every remittance and remit by bank transfer to Meridian Components, account 4471-8820, quoting the purchase order.</p></div>","questionText":"The e-mail states that 225 panels were actually received. At the unit price shown on the invoice, what is the value of the shortfall?","options":[{"key":"A","text":"(A) $577.50"},{"key":"B","text":"(B) $462.00"},{"key":"C","text":"(C) $225.00"},{"key":"D","text":"(D) $9,240.00"}],"correct":"A","translation":"E-mail nói thực nhận 225 tấm. Với đơn giá trên hoá đơn, giá trị phần thiếu là bao nhiêu? — 577,50 đô la.","explanation":"Hoá đơn ghi 240 tấm với đơn giá $38.50/tấm, còn e-mail xác nhận chỉ nhận 225 tấm. Chênh lệch 240 − 225 = 15 tấm; 15 × $38.50 = $577.50. Phải đối chiếu số lượng ở Tài liệu 1 với dòng 'Oak veneer panels, 3 mm ... $38.50' ở Tài liệu 2.","vocab":[{"word":"unit price","pos":"n. phr.","meaning":"đơn giá"},{"word":"shortfall","pos":"n.","meaning":"phần thiếu hụt"},{"word":"figure","pos":"n.","meaning":"con số"}]},{"id":"reading-lv6-test-1-q179","questionNumber":179,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 179 (Part 7: Đọc hiểu)","passageTitle":"Questions 176-180 refer to the following e-mail and invoice:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Priya Raghunathan, Procurement Manager, Halcyon Ridge Furniture<br>To: Accounts Receivable, Meridian Components<br>Subject: Invoice MC-4471 — quantity and freight discrepancy</p><p class=\"mt-2\">Dear Ms. Okafor,</p><p class=\"mt-2\">Thank you for dispatching the oak veneer panels ahead of schedule. Before we release payment on invoice MC-4471, however, our warehouse team has flagged two items that require your confirmation.</p><p class=\"mt-2\">Your invoice lists 240 panels, whereas the delivery note accompanying the shipment records 225. Our receiving clerk counted the pallets twice and photographed each one; the figure of 225 appears to be accurate. In addition, the invoice applies a fuel surcharge of 4.5 percent, although clause 7 of our master supply agreement caps all freight-related surcharges at 3 percent for the duration of the contract.</p><p class=\"mt-2\">We remain keen to keep the revised delivery dates for the Riverside project on track, so I would ask that you issue a corrected invoice by Friday rather than delay settlement. Once the amended document arrives, our finance department can process the transfer within two business days.</p><p class=\"mt-2\">Kind regards,<br>Priya Raghunathan</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Invoice</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">MERIDIAN COMPONENTS — COMMERCIAL INVOICE<br>Invoice no. MC-4471 | Date: 12 March | Terms: net 30<br>Bill to: Halcyon Ridge Furniture, 88 Foundry Lane<br>Purchase order: HRF-2291</p><table class=\"mt-2 w-full text-left\"><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr><tr><td>Oak veneer panels, 3 mm</td><td>240</td><td>$38.50</td><td>$9,240.00</td></tr><tr><td>Edge banding, 50 m rolls</td><td>12</td><td>$22.00</td><td>$264.00</td></tr><tr><td>Subtotal</td><td></td><td></td><td>$9,504.00</td></tr><tr><td>Freight (fuel surcharge 4.5%)</td><td></td><td></td><td>$427.68</td></tr><tr><td>Total due</td><td></td><td></td><td>$9,931.68</td></tr></table><p class=\"mt-2\">Goods shipped 9 March via Northgate Freight, consignment NF-77120. Claims for shortages must be submitted in writing within ten days of receipt. Please quote the invoice number with every remittance and remit by bank transfer to Meridian Components, account 4471-8820, quoting the purchase order.</p></div>","questionText":"In the e-mail, the word \"flagged\" is closest in meaning to","options":[{"key":"A","text":"(A) marked with a coloured label"},{"key":"B","text":"(B) drawn to someone's attention"},{"key":"C","text":"(C) formally approved by a manager"},{"key":"D","text":"(D) postponed for later consideration"}],"correct":"B","translation":"Từ 'flagged' trong e-mail gần nghĩa nhất với 'được nêu ra để chú ý'.","explanation":"'our warehouse team has flagged two items that require your confirmation' — 'flag' ở đây nghĩa là nêu ra, làm cho được chú ý tới (drawn to someone's attention), không phải dán nhãn thật (A) hay hoãn lại (D).","vocab":[{"word":"flag","pos":"v.","meaning":"nêu ra, đánh dấu để chú ý"},{"word":"confirmation","pos":"n.","meaning":"sự xác nhận"},{"word":"pallet","pos":"n.","meaning":"pallet, bệ hàng"}]},{"id":"reading-lv6-test-1-q180","questionNumber":180,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 180 (Part 7: Đọc hiểu)","passageTitle":"Questions 176-180 refer to the following e-mail and invoice:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Priya Raghunathan, Procurement Manager, Halcyon Ridge Furniture<br>To: Accounts Receivable, Meridian Components<br>Subject: Invoice MC-4471 — quantity and freight discrepancy</p><p class=\"mt-2\">Dear Ms. Okafor,</p><p class=\"mt-2\">Thank you for dispatching the oak veneer panels ahead of schedule. Before we release payment on invoice MC-4471, however, our warehouse team has flagged two items that require your confirmation.</p><p class=\"mt-2\">Your invoice lists 240 panels, whereas the delivery note accompanying the shipment records 225. Our receiving clerk counted the pallets twice and photographed each one; the figure of 225 appears to be accurate. In addition, the invoice applies a fuel surcharge of 4.5 percent, although clause 7 of our master supply agreement caps all freight-related surcharges at 3 percent for the duration of the contract.</p><p class=\"mt-2\">We remain keen to keep the revised delivery dates for the Riverside project on track, so I would ask that you issue a corrected invoice by Friday rather than delay settlement. Once the amended document arrives, our finance department can process the transfer within two business days.</p><p class=\"mt-2\">Kind regards,<br>Priya Raghunathan</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Invoice</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">MERIDIAN COMPONENTS — COMMERCIAL INVOICE<br>Invoice no. MC-4471 | Date: 12 March | Terms: net 30<br>Bill to: Halcyon Ridge Furniture, 88 Foundry Lane<br>Purchase order: HRF-2291</p><table class=\"mt-2 w-full text-left\"><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr><tr><td>Oak veneer panels, 3 mm</td><td>240</td><td>$38.50</td><td>$9,240.00</td></tr><tr><td>Edge banding, 50 m rolls</td><td>12</td><td>$22.00</td><td>$264.00</td></tr><tr><td>Subtotal</td><td></td><td></td><td>$9,504.00</td></tr><tr><td>Freight (fuel surcharge 4.5%)</td><td></td><td></td><td>$427.68</td></tr><tr><td>Total due</td><td></td><td></td><td>$9,931.68</td></tr></table><p class=\"mt-2\">Goods shipped 9 March via Northgate Freight, consignment NF-77120. Claims for shortages must be submitted in writing within ten days of receipt. Please quote the invoice number with every remittance and remit by bank transfer to Meridian Components, account 4471-8820, quoting the purchase order.</p></div>","questionText":"According to the invoice, all of the following are true EXCEPT:","options":[{"key":"A","text":"(A) Payment falls due within two business days."},{"key":"B","text":"(B) The consignment was carried by Northgate Freight."},{"key":"C","text":"(C) It was issued on 12 March."},{"key":"D","text":"(D) Shortage claims must be lodged within ten days of receipt."}],"correct":"A","translation":"Theo hoá đơn, tất cả các ý sau đều đúng NGOẠI TRỪ: Thanh toán đến hạn trong vòng hai ngày làm việc.","explanation":"Hoá đơn ghi 'Terms: net 30', tức thanh toán trong 30 ngày, nên A sai. Hai ngày làm việc là thời gian bộ phận tài chính của Halcyon xử lý chuyển khoản, nêu ở Tài liệu 1, không phải điều khoản của hoá đơn. Các ý C, B, D đều xuất hiện trên hoá đơn.","vocab":[{"word":"remittance","pos":"n.","meaning":"khoản chuyển tiền thanh toán"},{"word":"lodge a claim","pos":"v. phr.","meaning":"nộp khiếu nại"},{"word":"consignment","pos":"n.","meaning":"lô hàng"}]},{"id":"reading-lv6-test-1-q181","questionNumber":181,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 181 (Part 7: Đọc hiểu)","passageTitle":"Questions 181-185 refer to the following advertisement and text message exchange:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Advertisement</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">KESTREL ANALYTICS INSTITUTE<br>Executive Data Storytelling — two-day intensive</p><p class=\"mt-2\">Numbers persuade only when they are narrated. This programme is designed for senior managers who must present analytical findings to boards and investors. Participants work in cohorts of no more than fourteen, revising their own quarterly materials under faculty drawn from the investor-relations teams of listed companies.</p><p class=\"mt-2\">Dates: 4-5 June (London); 17-18 September (Singapore).<br>Fee: £1,850 per participant, inclusive of the pre-course assessment, all catering and a post-course coaching call.</p><p class=\"mt-2\">Groups of four or more booking together receive a 15 percent reduction. Registration completed before 1 May carries a further 10 percent reduction, applicable to the standard fee only. Completion earns twelve CPD hours.</p><p class=\"mt-2\">Places are allocated on receipt of payment; provisional holds are not offered. Enquiries: registrar@kestrel-institute.example</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Text message exchange</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">[10:42] Daniel: Did you see the Kestrel brochure I forwarded? Our learning budget for the third quarter covers the September cohort but nothing earlier.</p><p class=\"mt-2\">[10:47] Mei-Lin: I saw it. Four of us in strategy are interested. But the fee they quote on the website seems to exclude the assessment, which would change the arithmetic.</p><p class=\"mt-2\">[10:51] Daniel: Look again — the assessment is included. What is restricted is the early rate, which applies to the standard fee only, so it may not survive the group reduction.</p><p class=\"mt-2\">[10:55] Mei-Lin: Then the four of us would miss the early window unless payment clears by Thursday. Shall I ask the registrar whether the two reductions can be combined?</p><p class=\"mt-2\">[10:57] Daniel: Yes, and put the four names forward at the same time — places go on payment, not on a waiting list.</p></div>","questionText":"What is the main purpose of the advertisement?","options":[{"key":"A","text":"(A) To notify applicants that the June London cohort is full and direct them to Singapore"},{"key":"B","text":"(B) To market an online investor-relations assessment required for CPD accreditation"},{"key":"C","text":"(C) To explain why provisional holds have replaced advance payment for group bookings"},{"key":"D","text":"(D) To promote a specialized leadership seminar along with its fee and discount terms"}],"correct":"D","translation":"Mục đích chính của quảng cáo là quảng bá một hội thảo đào tạo chuyên sâu cho lãnh đạo cùng mức phí và các điều kiện ưu đãi.","explanation":"Tài liệu 1 giới thiệu khoá chuyên sâu hai ngày 'Executive Data Storytelling', đối tượng quản lý cấp cao, lịch tổ chức tại London/Singapore, học phí £1,850 và các quy định giảm giá nhóm/đăng ký sớm. A sai vì cả hai đợt tháng 6 và tháng 9 đều đang mở đăng ký; C trái ngược quy định 'provisional holds are not offered'; B sai vì bài đánh giá chỉ là phần đi kèm trước khoá học trực tiếp, không phải sản phẩm rao bán riêng.","vocab":[{"word":"cohort","pos":"n.","meaning":"nhóm học viên cùng khoá"},{"word":"intensive","pos":"adj.","meaning":"cường độ cao, tập trung"},{"word":"provisional hold","pos":"n. phr.","meaning":"giữ chỗ tạm thời"}]},{"id":"reading-lv6-test-1-q182","questionNumber":182,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 182 (Part 7: Đọc hiểu)","passageTitle":"Questions 181-185 refer to the following advertisement and text message exchange:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Advertisement</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">KESTREL ANALYTICS INSTITUTE<br>Executive Data Storytelling — two-day intensive</p><p class=\"mt-2\">Numbers persuade only when they are narrated. This programme is designed for senior managers who must present analytical findings to boards and investors. Participants work in cohorts of no more than fourteen, revising their own quarterly materials under faculty drawn from the investor-relations teams of listed companies.</p><p class=\"mt-2\">Dates: 4-5 June (London); 17-18 September (Singapore).<br>Fee: £1,850 per participant, inclusive of the pre-course assessment, all catering and a post-course coaching call.</p><p class=\"mt-2\">Groups of four or more booking together receive a 15 percent reduction. Registration completed before 1 May carries a further 10 percent reduction, applicable to the standard fee only. Completion earns twelve CPD hours.</p><p class=\"mt-2\">Places are allocated on receipt of payment; provisional holds are not offered. Enquiries: registrar@kestrel-institute.example</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Text message exchange</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">[10:42] Daniel: Did you see the Kestrel brochure I forwarded? Our learning budget for the third quarter covers the September cohort but nothing earlier.</p><p class=\"mt-2\">[10:47] Mei-Lin: I saw it. Four of us in strategy are interested. But the fee they quote on the website seems to exclude the assessment, which would change the arithmetic.</p><p class=\"mt-2\">[10:51] Daniel: Look again — the assessment is included. What is restricted is the early rate, which applies to the standard fee only, so it may not survive the group reduction.</p><p class=\"mt-2\">[10:55] Mei-Lin: Then the four of us would miss the early window unless payment clears by Thursday. Shall I ask the registrar whether the two reductions can be combined?</p><p class=\"mt-2\">[10:57] Daniel: Yes, and put the four names forward at the same time — places go on payment, not on a waiting list.</p></div>","questionText":"Which claim made in the text exchange is contradicted by the advertisement?","options":[{"key":"A","text":"(A) The quoted fee excludes the assessment."},{"key":"B","text":"(B) The third-quarter budget covers the September cohort."},{"key":"C","text":"(C) Four strategy staff are interested in attending."},{"key":"D","text":"(D) The early-registration window closes on Thursday."}],"correct":"A","translation":"Khẳng định nào trong đoạn tin nhắn bị quảng cáo phủ định? — Học phí được niêm yết không bao gồm bài đánh giá.","explanation":"Mei-Lin viết 'the fee they quote on the website seems to exclude the assessment', nhưng quảng cáo ghi rõ 'Fee: £1,850 ... inclusive of the pre-course assessment, all catering and a post-course coaching call'. Vì vậy A bị phủ định; các ý còn lại không mâu thuẫn với tài liệu nào.","vocab":[{"word":"quote","pos":"v.","meaning":"niêm yết, báo giá"},{"word":"inclusive of","pos":"adj. phr.","meaning":"bao gồm"},{"word":"arithmetic","pos":"n.","meaning":"phép tính, bài toán chi phí"}]},{"id":"reading-lv6-test-1-q183","questionNumber":183,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 183 (Part 7: Đọc hiểu)","passageTitle":"Questions 181-185 refer to the following advertisement and text message exchange:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Advertisement</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">KESTREL ANALYTICS INSTITUTE<br>Executive Data Storytelling — two-day intensive</p><p class=\"mt-2\">Numbers persuade only when they are narrated. This programme is designed for senior managers who must present analytical findings to boards and investors. Participants work in cohorts of no more than fourteen, revising their own quarterly materials under faculty drawn from the investor-relations teams of listed companies.</p><p class=\"mt-2\">Dates: 4-5 June (London); 17-18 September (Singapore).<br>Fee: £1,850 per participant, inclusive of the pre-course assessment, all catering and a post-course coaching call.</p><p class=\"mt-2\">Groups of four or more booking together receive a 15 percent reduction. Registration completed before 1 May carries a further 10 percent reduction, applicable to the standard fee only. Completion earns twelve CPD hours.</p><p class=\"mt-2\">Places are allocated on receipt of payment; provisional holds are not offered. Enquiries: registrar@kestrel-institute.example</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Text message exchange</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">[10:42] Daniel: Did you see the Kestrel brochure I forwarded? Our learning budget for the third quarter covers the September cohort but nothing earlier.</p><p class=\"mt-2\">[10:47] Mei-Lin: I saw it. Four of us in strategy are interested. But the fee they quote on the website seems to exclude the assessment, which would change the arithmetic.</p><p class=\"mt-2\">[10:51] Daniel: Look again — the assessment is included. What is restricted is the early rate, which applies to the standard fee only, so it may not survive the group reduction.</p><p class=\"mt-2\">[10:55] Mei-Lin: Then the four of us would miss the early window unless payment clears by Thursday. Shall I ask the registrar whether the two reductions can be combined?</p><p class=\"mt-2\">[10:57] Daniel: Yes, and put the four names forward at the same time — places go on payment, not on a waiting list.</p></div>","questionText":"What will Daniel and Mei-Lin most likely do next?","options":[{"key":"A","text":"(A) Register for the June cohort instead of the September one."},{"key":"B","text":"(B) Ask the registrar whether the two reductions may be combined."},{"key":"C","text":"(C) Postpone the decision until the next budget cycle."},{"key":"D","text":"(D) Ask the institute to waive the fee for the coaching call."}],"correct":"B","translation":"Daniel và Mei-Lin nhiều khả năng sẽ làm gì tiếp theo? — Hỏi bộ phận đăng ký xem hai ưu đãi có được cộng gộp hay không.","explanation":"Mei-Lin đề nghị 'Shall I ask the registrar whether the two reductions can be combined?' và Daniel đồng ý, đồng thời giục 'put the four names forward'. Quảng cáo chỉ nói ưu đãi sớm 'applicable to the standard fee only', không nói rõ có cộng với ưu đãi nhóm hay không — nên cần hỏi. Ngân sách quý ba chỉ đủ cho đợt tháng 9 nên A sai.","vocab":[{"word":"combine","pos":"v.","meaning":"cộng gộp, kết hợp"},{"word":"reduction","pos":"n.","meaning":"mức giảm giá"},{"word":"waive","pos":"v.","meaning":"miễn, bỏ khoản phí"}]},{"id":"reading-lv6-test-1-q184","questionNumber":184,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 184 (Part 7: Đọc hiểu)","passageTitle":"Questions 181-185 refer to the following advertisement and text message exchange:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Advertisement</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">KESTREL ANALYTICS INSTITUTE<br>Executive Data Storytelling — two-day intensive</p><p class=\"mt-2\">Numbers persuade only when they are narrated. This programme is designed for senior managers who must present analytical findings to boards and investors. Participants work in cohorts of no more than fourteen, revising their own quarterly materials under faculty drawn from the investor-relations teams of listed companies.</p><p class=\"mt-2\">Dates: 4-5 June (London); 17-18 September (Singapore).<br>Fee: £1,850 per participant, inclusive of the pre-course assessment, all catering and a post-course coaching call.</p><p class=\"mt-2\">Groups of four or more booking together receive a 15 percent reduction. Registration completed before 1 May carries a further 10 percent reduction, applicable to the standard fee only. Completion earns twelve CPD hours.</p><p class=\"mt-2\">Places are allocated on receipt of payment; provisional holds are not offered. Enquiries: registrar@kestrel-institute.example</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Text message exchange</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">[10:42] Daniel: Did you see the Kestrel brochure I forwarded? Our learning budget for the third quarter covers the September cohort but nothing earlier.</p><p class=\"mt-2\">[10:47] Mei-Lin: I saw it. Four of us in strategy are interested. But the fee they quote on the website seems to exclude the assessment, which would change the arithmetic.</p><p class=\"mt-2\">[10:51] Daniel: Look again — the assessment is included. What is restricted is the early rate, which applies to the standard fee only, so it may not survive the group reduction.</p><p class=\"mt-2\">[10:55] Mei-Lin: Then the four of us would miss the early window unless payment clears by Thursday. Shall I ask the registrar whether the two reductions can be combined?</p><p class=\"mt-2\">[10:57] Daniel: Yes, and put the four names forward at the same time — places go on payment, not on a waiting list.</p></div>","questionText":"In the text exchange, the phrase \"put the four names forward\" is closest in meaning to","options":[{"key":"A","text":"(A) nominate the four candidates"},{"key":"B","text":"(B) dismiss the four candidates"},{"key":"C","text":"(C) defer the four applications"},{"key":"D","text":"(D) rank the four applicants"}],"correct":"A","translation":"Cụm 'put the four names forward' gần nghĩa nhất với 'đề cử bốn ứng viên'.","explanation":"'Put somebody's name forward' = đề cử, giới thiệu ai đó vào một vị trí/danh sách. Trong ngữ cảnh này là gửi tên bốn người để đăng ký, nên 'nominate' là tương đương; không phải loại bỏ (B), trì hoãn (C) hay xếp hạng (D).","vocab":[{"word":"put forward","pos":"phr. v.","meaning":"đề cử, giới thiệu"},{"word":"nominate","pos":"v.","meaning":"đề cử"},{"word":"clear","pos":"v.","meaning":"được thanh toán, chuyển tiền thành công"}]},{"id":"reading-lv6-test-1-q185","questionNumber":185,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 185 (Part 7: Đọc hiểu)","passageTitle":"Questions 181-185 refer to the following advertisement and text message exchange:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Advertisement</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">KESTREL ANALYTICS INSTITUTE<br>Executive Data Storytelling — two-day intensive</p><p class=\"mt-2\">Numbers persuade only when they are narrated. This programme is designed for senior managers who must present analytical findings to boards and investors. Participants work in cohorts of no more than fourteen, revising their own quarterly materials under faculty drawn from the investor-relations teams of listed companies.</p><p class=\"mt-2\">Dates: 4-5 June (London); 17-18 September (Singapore).<br>Fee: £1,850 per participant, inclusive of the pre-course assessment, all catering and a post-course coaching call.</p><p class=\"mt-2\">Groups of four or more booking together receive a 15 percent reduction. Registration completed before 1 May carries a further 10 percent reduction, applicable to the standard fee only. Completion earns twelve CPD hours.</p><p class=\"mt-2\">Places are allocated on receipt of payment; provisional holds are not offered. Enquiries: registrar@kestrel-institute.example</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Text message exchange</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">[10:42] Daniel: Did you see the Kestrel brochure I forwarded? Our learning budget for the third quarter covers the September cohort but nothing earlier.</p><p class=\"mt-2\">[10:47] Mei-Lin: I saw it. Four of us in strategy are interested. But the fee they quote on the website seems to exclude the assessment, which would change the arithmetic.</p><p class=\"mt-2\">[10:51] Daniel: Look again — the assessment is included. What is restricted is the early rate, which applies to the standard fee only, so it may not survive the group reduction.</p><p class=\"mt-2\">[10:55] Mei-Lin: Then the four of us would miss the early window unless payment clears by Thursday. Shall I ask the registrar whether the two reductions can be combined?</p><p class=\"mt-2\">[10:57] Daniel: Yes, and put the four names forward at the same time — places go on payment, not on a waiting list.</p></div>","questionText":"The advertisement indicates that the fee covers all of the following EXCEPT","options":[{"key":"A","text":"(A) the pre-course assessment"},{"key":"B","text":"(B) overnight accommodation"},{"key":"C","text":"(C) a post-course coaching call"},{"key":"D","text":"(D) catering during the two days"}],"correct":"B","translation":"Quảng cáo cho biết học phí bao gồm tất cả các mục sau NGOẠI TRỪ: chỗ ở qua đêm.","explanation":"Quảng cáo ghi 'inclusive of the pre-course assessment, all catering and a post-course coaching call', hoàn toàn không nhắc tới chỗ ở. Vì vậy B là mục không được bao gồm.","vocab":[{"word":"catering","pos":"n.","meaning":"dịch vụ ăn uống"},{"word":"inclusive","pos":"adj.","meaning":"bao gồm tất cả"},{"word":"accommodation","pos":"n.","meaning":"chỗ ở"}]},{"id":"reading-lv6-test-1-q186","questionNumber":186,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 186 (Part 7: Đọc hiểu)","passageTitle":"Questions 186-190 refer to the following programme, e-mail and reply:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Programme</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">NORTHFIELD SUPPLY CHAIN FORUM — PROGRAMME, 14 NOVEMBER</p><table class=\"mt-2 w-full text-left\"><tr><th>Time</th><th>Session</th><th>Venue</th></tr><tr><td>08:30</td><td>Registration</td><td>Atrium</td></tr><tr><td>09:15</td><td>Keynote: resilience after the Red Sea disruptions</td><td>Plenary Hall</td></tr><tr><td>10:30</td><td>Track A — scoring supplier risk in volatile markets</td><td>Room 2A</td></tr><tr><td>10:30</td><td>Track B — calculating the return on warehouse automation</td><td>Room 2B</td></tr><tr><td>12:00</td><td>Buffet lunch</td><td>Terrace</td></tr><tr><td>13:15</td><td>Panel: customs compliance in a fragmented trading environment</td><td>Plenary Hall</td></tr><tr><td>14:30</td><td>Workshop: drafting force majeure clauses (ninety minutes, pre-registration required, thirty places)</td><td>Room 3C</td></tr><tr><td>16:00</td><td>Closing remarks</td><td>Plenary Hall</td></tr></table><p class=\"mt-2\">Delegates may attend one parallel session only. Registration for the forum closes on 7 November.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Tobias Lindqvist<br>To: programmes@northfieldforum.example<br>Subject: Workshop allocation</p><p class=\"mt-2\">Dear Organising Team,</p><p class=\"mt-2\">I have registered for the full forum on 14 November and would like to attend the force majeure workshop at 14:30. When I completed the booking form, the workshop did not appear among the selectable options, so I assume the list had not yet been finalised.</p><p class=\"mt-2\">I should mention that my flight back to Stockholm departs at 17:05, which means I will have to leave the venue by 15:40. If the workshop runs its full length, I would depart before the end; please tell me whether that would invalidate the attendance certificate, since my professional body requires evidence of complete sessions.</p><p class=\"mt-2\">A colleague, Helena Marsh, hopes to join the same workshop. She is registering tomorrow.</p><p class=\"mt-2\">Best regards,<br>Tobias Lindqvist</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 3: Reply</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Registration Office<br>To: Tobias Lindqvist<br>Subject: RE: Workshop allocation</p><p class=\"mt-2\">Dear Mr. Lindqvist,</p><p class=\"mt-2\">Thank you for writing. The workshop has now been added to the booking system and is capped at thirty participants; as of this morning twenty-two places remain, so your colleague should have no difficulty securing one provided she registers before 7 November, when the programme closes.</p><p class=\"mt-2\">On the certificate: attendance is recorded in part-sessions, but only delegates present for the entire workshop receive the certificate endorsed by the Chartered Institute of Logistics. We are, however, filming every session and will release the footage to registered delegates for thirty days afterwards; several attendees have used it to satisfy continuing-education requirements. The closing remarks are optional this year, so leaving at 15:40 will not affect your record for the remainder of the day.</p><p class=\"mt-2\">Kind regards,<br>Registration Office</p></div>","questionText":"What is the purpose of Mr. Lindqvist's e-mail?","options":[{"key":"A","text":"(A) To reserve a workshop seat for Helena Marsh before the 7 November registration cutoff"},{"key":"B","text":"(B) To request that the afternoon workshop be moved earlier to accommodate his 17:05 flight"},{"key":"C","text":"(C) To verify the certification consequences of leaving a workshop before its scheduled conclusion"},{"key":"D","text":"(D) To switch his booking from the morning parallel tracks to the afternoon panel"}],"correct":"C","translation":"Mục đích e-mail của ông Lindqvist là xác minh hệ quả đối với chứng chỉ nếu ông rời buổi workshop trước giờ kết thúc dự kiến.","explanation":"Ông cho biết phải rời địa điểm lúc 15:40 để kịp chuyến bay và hỏi 'please tell me whether that would invalidate the attendance certificate'. A sai vì Helena Marsh sẽ tự đăng ký ngày mai ('She is registering tomorrow'); B sai vì ông không xin dời giờ workshop; D không hề được nhắc tới trong e-mail.","vocab":[{"word":"invalidate","pos":"v.","meaning":"làm mất hiệu lực"},{"word":"attendance certificate","pos":"n. phr.","meaning":"chứng nhận tham dự"},{"word":"finalise","pos":"v.","meaning":"hoàn tất, chốt danh sách"}]},{"id":"reading-lv6-test-1-q187","questionNumber":187,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 187 (Part 7: Đọc hiểu)","passageTitle":"Questions 186-190 refer to the following programme, e-mail and reply:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Programme</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">NORTHFIELD SUPPLY CHAIN FORUM — PROGRAMME, 14 NOVEMBER</p><table class=\"mt-2 w-full text-left\"><tr><th>Time</th><th>Session</th><th>Venue</th></tr><tr><td>08:30</td><td>Registration</td><td>Atrium</td></tr><tr><td>09:15</td><td>Keynote: resilience after the Red Sea disruptions</td><td>Plenary Hall</td></tr><tr><td>10:30</td><td>Track A — scoring supplier risk in volatile markets</td><td>Room 2A</td></tr><tr><td>10:30</td><td>Track B — calculating the return on warehouse automation</td><td>Room 2B</td></tr><tr><td>12:00</td><td>Buffet lunch</td><td>Terrace</td></tr><tr><td>13:15</td><td>Panel: customs compliance in a fragmented trading environment</td><td>Plenary Hall</td></tr><tr><td>14:30</td><td>Workshop: drafting force majeure clauses (ninety minutes, pre-registration required, thirty places)</td><td>Room 3C</td></tr><tr><td>16:00</td><td>Closing remarks</td><td>Plenary Hall</td></tr></table><p class=\"mt-2\">Delegates may attend one parallel session only. Registration for the forum closes on 7 November.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Tobias Lindqvist<br>To: programmes@northfieldforum.example<br>Subject: Workshop allocation</p><p class=\"mt-2\">Dear Organising Team,</p><p class=\"mt-2\">I have registered for the full forum on 14 November and would like to attend the force majeure workshop at 14:30. When I completed the booking form, the workshop did not appear among the selectable options, so I assume the list had not yet been finalised.</p><p class=\"mt-2\">I should mention that my flight back to Stockholm departs at 17:05, which means I will have to leave the venue by 15:40. If the workshop runs its full length, I would depart before the end; please tell me whether that would invalidate the attendance certificate, since my professional body requires evidence of complete sessions.</p><p class=\"mt-2\">A colleague, Helena Marsh, hopes to join the same workshop. She is registering tomorrow.</p><p class=\"mt-2\">Best regards,<br>Tobias Lindqvist</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 3: Reply</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Registration Office<br>To: Tobias Lindqvist<br>Subject: RE: Workshop allocation</p><p class=\"mt-2\">Dear Mr. Lindqvist,</p><p class=\"mt-2\">Thank you for writing. The workshop has now been added to the booking system and is capped at thirty participants; as of this morning twenty-two places remain, so your colleague should have no difficulty securing one provided she registers before 7 November, when the programme closes.</p><p class=\"mt-2\">On the certificate: attendance is recorded in part-sessions, but only delegates present for the entire workshop receive the certificate endorsed by the Chartered Institute of Logistics. We are, however, filming every session and will release the footage to registered delegates for thirty days afterwards; several attendees have used it to satisfy continuing-education requirements. The closing remarks are optional this year, so leaving at 15:40 will not affect your record for the remainder of the day.</p><p class=\"mt-2\">Kind regards,<br>Registration Office</p></div>","questionText":"If Mr. Lindqvist leaves at 15:40 as planned, how much of the workshop will he be unable to attend?","options":[{"key":"A","text":"(A) Ten minutes"},{"key":"B","text":"(B) Fifteen minutes"},{"key":"C","text":"(C) Twenty minutes"},{"key":"D","text":"(D) Thirty minutes"}],"correct":"C","translation":"Nếu ông Lindqvist rời đi lúc 15:40 như dự kiến, ông sẽ không dự được bao nhiêu thời gian của buổi workshop? — Hai mươi phút.","explanation":"Tài liệu 1 ghi workshop bắt đầu 14:30 và kéo dài 'ninety minutes', tức kết thúc 16:00. Tài liệu 2 cho biết ông phải rời đi lúc 15:40. Vậy ông thiếu 16:00 − 15:40 = 20 phút. Phải đối chiếu cả hai tài liệu mới tính được.","vocab":[{"word":"run its full length","pos":"v. phr.","meaning":"kéo dài đủ thời lượng"},{"word":"depart","pos":"v.","meaning":"khởi hành, rời đi"},{"word":"session","pos":"n.","meaning":"phiên họp, buổi"}]},{"id":"reading-lv6-test-1-q188","questionNumber":188,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 188 (Part 7: Đọc hiểu)","passageTitle":"Questions 186-190 refer to the following programme, e-mail and reply:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Programme</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">NORTHFIELD SUPPLY CHAIN FORUM — PROGRAMME, 14 NOVEMBER</p><table class=\"mt-2 w-full text-left\"><tr><th>Time</th><th>Session</th><th>Venue</th></tr><tr><td>08:30</td><td>Registration</td><td>Atrium</td></tr><tr><td>09:15</td><td>Keynote: resilience after the Red Sea disruptions</td><td>Plenary Hall</td></tr><tr><td>10:30</td><td>Track A — scoring supplier risk in volatile markets</td><td>Room 2A</td></tr><tr><td>10:30</td><td>Track B — calculating the return on warehouse automation</td><td>Room 2B</td></tr><tr><td>12:00</td><td>Buffet lunch</td><td>Terrace</td></tr><tr><td>13:15</td><td>Panel: customs compliance in a fragmented trading environment</td><td>Plenary Hall</td></tr><tr><td>14:30</td><td>Workshop: drafting force majeure clauses (ninety minutes, pre-registration required, thirty places)</td><td>Room 3C</td></tr><tr><td>16:00</td><td>Closing remarks</td><td>Plenary Hall</td></tr></table><p class=\"mt-2\">Delegates may attend one parallel session only. Registration for the forum closes on 7 November.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Tobias Lindqvist<br>To: programmes@northfieldforum.example<br>Subject: Workshop allocation</p><p class=\"mt-2\">Dear Organising Team,</p><p class=\"mt-2\">I have registered for the full forum on 14 November and would like to attend the force majeure workshop at 14:30. When I completed the booking form, the workshop did not appear among the selectable options, so I assume the list had not yet been finalised.</p><p class=\"mt-2\">I should mention that my flight back to Stockholm departs at 17:05, which means I will have to leave the venue by 15:40. If the workshop runs its full length, I would depart before the end; please tell me whether that would invalidate the attendance certificate, since my professional body requires evidence of complete sessions.</p><p class=\"mt-2\">A colleague, Helena Marsh, hopes to join the same workshop. She is registering tomorrow.</p><p class=\"mt-2\">Best regards,<br>Tobias Lindqvist</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 3: Reply</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Registration Office<br>To: Tobias Lindqvist<br>Subject: RE: Workshop allocation</p><p class=\"mt-2\">Dear Mr. Lindqvist,</p><p class=\"mt-2\">Thank you for writing. The workshop has now been added to the booking system and is capped at thirty participants; as of this morning twenty-two places remain, so your colleague should have no difficulty securing one provided she registers before 7 November, when the programme closes.</p><p class=\"mt-2\">On the certificate: attendance is recorded in part-sessions, but only delegates present for the entire workshop receive the certificate endorsed by the Chartered Institute of Logistics. We are, however, filming every session and will release the footage to registered delegates for thirty days afterwards; several attendees have used it to satisfy continuing-education requirements. The closing remarks are optional this year, so leaving at 15:40 will not affect your record for the remainder of the day.</p><p class=\"mt-2\">Kind regards,<br>Registration Office</p></div>","questionText":"What does the reply indicate about Helena Marsh?","options":[{"key":"A","text":"(A) She has already been allocated one of the thirty places."},{"key":"B","text":"(B) She will probably obtain a place if she registers before 7 November."},{"key":"C","text":"(C) She is ineligible because the workshop is closed to new registrations."},{"key":"D","text":"(D) She must attend the closing remarks to qualify for a certificate."}],"correct":"B","translation":"Thư phản hồi cho biết gì về Helena Marsh? — Bà ấy nhiều khả năng sẽ có chỗ nếu đăng ký trước ngày 7 tháng 11.","explanation":"Thư trả lời nói 'twenty-two places remain, so your colleague should have no difficulty securing one provided she registers before 7 November'. Như vậy bà ấy chưa có chỗ (loại A) và vẫn còn chỗ (loại C).","vocab":[{"word":"cap","pos":"v.","meaning":"giới hạn số lượng"},{"word":"secure a place","pos":"v. phr.","meaning":"giành được một chỗ"},{"word":"provided","pos":"conj.","meaning":"với điều kiện là"}]},{"id":"reading-lv6-test-1-q189","questionNumber":189,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 189 (Part 7: Đọc hiểu)","passageTitle":"Questions 186-190 refer to the following programme, e-mail and reply:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Programme</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">NORTHFIELD SUPPLY CHAIN FORUM — PROGRAMME, 14 NOVEMBER</p><table class=\"mt-2 w-full text-left\"><tr><th>Time</th><th>Session</th><th>Venue</th></tr><tr><td>08:30</td><td>Registration</td><td>Atrium</td></tr><tr><td>09:15</td><td>Keynote: resilience after the Red Sea disruptions</td><td>Plenary Hall</td></tr><tr><td>10:30</td><td>Track A — scoring supplier risk in volatile markets</td><td>Room 2A</td></tr><tr><td>10:30</td><td>Track B — calculating the return on warehouse automation</td><td>Room 2B</td></tr><tr><td>12:00</td><td>Buffet lunch</td><td>Terrace</td></tr><tr><td>13:15</td><td>Panel: customs compliance in a fragmented trading environment</td><td>Plenary Hall</td></tr><tr><td>14:30</td><td>Workshop: drafting force majeure clauses (ninety minutes, pre-registration required, thirty places)</td><td>Room 3C</td></tr><tr><td>16:00</td><td>Closing remarks</td><td>Plenary Hall</td></tr></table><p class=\"mt-2\">Delegates may attend one parallel session only. Registration for the forum closes on 7 November.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Tobias Lindqvist<br>To: programmes@northfieldforum.example<br>Subject: Workshop allocation</p><p class=\"mt-2\">Dear Organising Team,</p><p class=\"mt-2\">I have registered for the full forum on 14 November and would like to attend the force majeure workshop at 14:30. When I completed the booking form, the workshop did not appear among the selectable options, so I assume the list had not yet been finalised.</p><p class=\"mt-2\">I should mention that my flight back to Stockholm departs at 17:05, which means I will have to leave the venue by 15:40. If the workshop runs its full length, I would depart before the end; please tell me whether that would invalidate the attendance certificate, since my professional body requires evidence of complete sessions.</p><p class=\"mt-2\">A colleague, Helena Marsh, hopes to join the same workshop. She is registering tomorrow.</p><p class=\"mt-2\">Best regards,<br>Tobias Lindqvist</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 3: Reply</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Registration Office<br>To: Tobias Lindqvist<br>Subject: RE: Workshop allocation</p><p class=\"mt-2\">Dear Mr. Lindqvist,</p><p class=\"mt-2\">Thank you for writing. The workshop has now been added to the booking system and is capped at thirty participants; as of this morning twenty-two places remain, so your colleague should have no difficulty securing one provided she registers before 7 November, when the programme closes.</p><p class=\"mt-2\">On the certificate: attendance is recorded in part-sessions, but only delegates present for the entire workshop receive the certificate endorsed by the Chartered Institute of Logistics. We are, however, filming every session and will release the footage to registered delegates for thirty days afterwards; several attendees have used it to satisfy continuing-education requirements. The closing remarks are optional this year, so leaving at 15:40 will not affect your record for the remainder of the day.</p><p class=\"mt-2\">Kind regards,<br>Registration Office</p></div>","questionText":"What can be inferred about the organisers' attitude towards continuing-education requirements?","options":[{"key":"A","text":"(A) They charge delegates separately for documentation of attendance."},{"key":"B","text":"(B) They refuse to recognise certificates issued by other professional bodies."},{"key":"C","text":"(C) They intend to shorten future workshops to under ninety minutes."},{"key":"D","text":"(D) They treat recorded footage as an acceptable substitute for full attendance."}],"correct":"D","translation":"Có thể suy ra gì về thái độ của ban tổ chức với yêu cầu đào tạo thường xuyên? — Họ coi bản ghi hình là giải pháp thay thế chấp nhận được cho việc dự đủ buổi.","explanation":"Sau khi nói chứng chỉ chỉ cấp cho người dự trọn buổi, thư trả lời bổ sung 'We are ... filming every session and will release the footage ... several attendees have used it to satisfy continuing-education requirements' — hàm ý linh hoạt, chấp nhận bản ghi làm bằng chứng thay thế. Không có căn cứ cho B, C hay A.","vocab":[{"word":"endorse","pos":"v.","meaning":"chứng thực, công nhận"},{"word":"footage","pos":"n.","meaning":"bản ghi hình"},{"word":"continuing education","pos":"n. phr.","meaning":"đào tạo thường xuyên, bồi dưỡng"}]},{"id":"reading-lv6-test-1-q190","questionNumber":190,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 190 (Part 7: Đọc hiểu)","passageTitle":"Questions 186-190 refer to the following programme, e-mail and reply:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Programme</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">NORTHFIELD SUPPLY CHAIN FORUM — PROGRAMME, 14 NOVEMBER</p><table class=\"mt-2 w-full text-left\"><tr><th>Time</th><th>Session</th><th>Venue</th></tr><tr><td>08:30</td><td>Registration</td><td>Atrium</td></tr><tr><td>09:15</td><td>Keynote: resilience after the Red Sea disruptions</td><td>Plenary Hall</td></tr><tr><td>10:30</td><td>Track A — scoring supplier risk in volatile markets</td><td>Room 2A</td></tr><tr><td>10:30</td><td>Track B — calculating the return on warehouse automation</td><td>Room 2B</td></tr><tr><td>12:00</td><td>Buffet lunch</td><td>Terrace</td></tr><tr><td>13:15</td><td>Panel: customs compliance in a fragmented trading environment</td><td>Plenary Hall</td></tr><tr><td>14:30</td><td>Workshop: drafting force majeure clauses (ninety minutes, pre-registration required, thirty places)</td><td>Room 3C</td></tr><tr><td>16:00</td><td>Closing remarks</td><td>Plenary Hall</td></tr></table><p class=\"mt-2\">Delegates may attend one parallel session only. Registration for the forum closes on 7 November.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Tobias Lindqvist<br>To: programmes@northfieldforum.example<br>Subject: Workshop allocation</p><p class=\"mt-2\">Dear Organising Team,</p><p class=\"mt-2\">I have registered for the full forum on 14 November and would like to attend the force majeure workshop at 14:30. When I completed the booking form, the workshop did not appear among the selectable options, so I assume the list had not yet been finalised.</p><p class=\"mt-2\">I should mention that my flight back to Stockholm departs at 17:05, which means I will have to leave the venue by 15:40. If the workshop runs its full length, I would depart before the end; please tell me whether that would invalidate the attendance certificate, since my professional body requires evidence of complete sessions.</p><p class=\"mt-2\">A colleague, Helena Marsh, hopes to join the same workshop. She is registering tomorrow.</p><p class=\"mt-2\">Best regards,<br>Tobias Lindqvist</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 3: Reply</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Registration Office<br>To: Tobias Lindqvist<br>Subject: RE: Workshop allocation</p><p class=\"mt-2\">Dear Mr. Lindqvist,</p><p class=\"mt-2\">Thank you for writing. The workshop has now been added to the booking system and is capped at thirty participants; as of this morning twenty-two places remain, so your colleague should have no difficulty securing one provided she registers before 7 November, when the programme closes.</p><p class=\"mt-2\">On the certificate: attendance is recorded in part-sessions, but only delegates present for the entire workshop receive the certificate endorsed by the Chartered Institute of Logistics. We are, however, filming every session and will release the footage to registered delegates for thirty days afterwards; several attendees have used it to satisfy continuing-education requirements. The closing remarks are optional this year, so leaving at 15:40 will not affect your record for the remainder of the day.</p><p class=\"mt-2\">Kind regards,<br>Registration Office</p></div>","questionText":"According to the reply, the organisers will do all of the following EXCEPT","options":[{"key":"A","text":"(A) accept registrations until 7 November"},{"key":"B","text":"(B) make session recordings available for thirty days"},{"key":"C","text":"(C) extend the workshop beyond its scheduled finishing time"},{"key":"D","text":"(D) endorse certificates for delegates who attend the whole workshop"}],"correct":"C","translation":"Theo thư trả lời, ban tổ chức sẽ làm tất cả các việc sau NGOẠI TRỪ: kéo dài workshop quá giờ kết thúc dự kiến.","explanation":"Thư không hề nói sẽ kéo dài workshop; ngược lại còn gợi ý ông rời lúc 15:40 vì 'closing remarks are optional'. Các ý A (mốc 7 November), B (ghi hình 30 ngày) và D (chứng chỉ cho người dự trọn buổi) đều có trong thư.","vocab":[{"word":"optional","pos":"adj.","meaning":"không bắt buộc"},{"word":"record","pos":"n.","meaning":"hồ sơ, biên bản ghi nhận"},{"word":"remainder","pos":"n.","meaning":"phần còn lại"}]},{"id":"reading-lv6-test-1-q191","questionNumber":191,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 191 (Part 7: Đọc hiểu)","passageTitle":"Questions 191-195 refer to the following fee schedule, request form and e-mail:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Schedule of fees</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">BRIGHTWELL TESTING SERVICES — SCHEDULE OF FEES (EXTRACT)</p><table class=\"mt-2 w-full text-left\"><tr><th>Test</th><th>Standard turnaround</th><th>Fee per sample</th></tr><tr><td>Tensile strength (ISO 6892)</td><td>5 working days</td><td>$210</td></tr><tr><td>Tensile strength, expedited</td><td>2 working days</td><td>$315</td></tr><tr><td>Hardness survey (ASTM E18)</td><td>3 working days</td><td>$145</td></tr><tr><td>Salt-spray corrosion (ISO 9227)</td><td>10 working days</td><td>$480</td></tr><tr><td>Metallographic examination</td><td>7 working days</td><td>$360</td></tr></table><p class=\"mt-2\">A supplement of 12 percent is applied to any specimen requiring sectioning before testing. Academic and public research institutions receive an 8 percent reduction, which applies to standard-turnaround tests only and may not be combined with expedited service. Fees exclude courier charges and the translation of reports. Quotations are valid for thirty days from the date of issue.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Test request form</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Client: Ardenne Polytechnic, Department of Mechanical Engineering<br>Contact: Dr. Sofia Renard | Purchase order: AP-2026-118<br>Samples submitted: 18 | Date received: 3 April</p><p class=\"mt-2\">Tests requested: tensile strength (ISO 6892) — 12 samples, expedited turnaround; hardness survey (ASTM E18) — 6 samples, standard turnaround.</p><p class=\"mt-2\">Sectioning required: yes, for nine of the tensile specimens.</p><p class=\"mt-2\">Special instructions: the report is to be issued in French and English, and every certificate must cite the purchase order number.</p><p class=\"mt-2\">Billing address: 14 Rue des Ateliers, Namur. Reports are to be delivered electronically in PDF format only; printed copies are not required. The department's laboratory coordinator, M. Verhoeven, will act as technical contact for any query arising during testing.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 3: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: accounts@brightwell-testing.example<br>To: S. Renard<br>Subject: Quotation AP-2026-118 — clarification needed</p><p class=\"mt-2\">Dear Dr. Renard,</p><p class=\"mt-2\">Thank you for the eighteen samples, which arrived safely on 3 April. Before we issue the formal quotation, two points require your confirmation.</p><p class=\"mt-2\">First, your form requests expedited turnaround for the tensile tests only; the hardness survey will follow the standard three-day schedule. Second, we note that sectioning is required for nine of the tensile specimens, which attracts the supplement published in our schedule. Please confirm that this is acceptable.</p><p class=\"mt-2\">I should also point out that the academic reduction cannot be combined with expedited service, so the twelve tensile tests will be charged at the full published rate. If, however, you were willing to accept the standard five-day turnaround, the reduction would apply and the saving would be considerable.</p><p class=\"mt-2\">Our quotation will follow within one working day of your reply. Please note that we invoice in US dollars and that courier costs are additional.</p><p class=\"mt-2\">Regards,<br>Marcus Ihejirika, Accounts</p></div>","questionText":"What is the main purpose of the e-mail?","options":[{"key":"A","text":"(A) To inform Dr. Renard that the academic discount has been applied to all eighteen samples"},{"key":"B","text":"(B) To verify turnaround and surcharge details prior to issuing a formal price quotation"},{"key":"C","text":"(C) To request permission to invoice in euros and waive PDF report translation charges"},{"key":"D","text":"(D) To advise Dr. Renard that M. Verhoeven must approve the sectioning fees before testing"}],"correct":"B","translation":"Mục đích chính của e-mail là xác minh các chi tiết về thời gian trả kết quả và phụ phí trước khi phát hành báo giá chính thức.","explanation":"Người gửi mở đầu bằng 'Before we issue the formal quotation, two points require your confirmation', làm rõ lịch xử lý nhanh/tiêu chuẩn của hai loại thử nghiệm và xác nhận phụ phí cắt mẫu 9 mẫu thử kéo. A sai vì 12 mẫu thử kéo dùng gói expedited nên không được giảm giá học thuật; C trái ngược nội dung tính tiền bằng đô-la Mỹ; D sai vì M. Verhoeven là đầu mối kỹ thuật, còn chính Dr. Renard được yêu cầu xác nhận chi phí.","vocab":[{"word":"quotation","pos":"n.","meaning":"báo giá"},{"word":"clarification","pos":"n.","meaning":"sự làm rõ"},{"word":"turnaround","pos":"n.","meaning":"thời gian hoàn thành dịch vụ"}]},{"id":"reading-lv6-test-1-q192","questionNumber":192,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 192 (Part 7: Đọc hiểu)","passageTitle":"Questions 191-195 refer to the following fee schedule, request form and e-mail:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Schedule of fees</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">BRIGHTWELL TESTING SERVICES — SCHEDULE OF FEES (EXTRACT)</p><table class=\"mt-2 w-full text-left\"><tr><th>Test</th><th>Standard turnaround</th><th>Fee per sample</th></tr><tr><td>Tensile strength (ISO 6892)</td><td>5 working days</td><td>$210</td></tr><tr><td>Tensile strength, expedited</td><td>2 working days</td><td>$315</td></tr><tr><td>Hardness survey (ASTM E18)</td><td>3 working days</td><td>$145</td></tr><tr><td>Salt-spray corrosion (ISO 9227)</td><td>10 working days</td><td>$480</td></tr><tr><td>Metallographic examination</td><td>7 working days</td><td>$360</td></tr></table><p class=\"mt-2\">A supplement of 12 percent is applied to any specimen requiring sectioning before testing. Academic and public research institutions receive an 8 percent reduction, which applies to standard-turnaround tests only and may not be combined with expedited service. Fees exclude courier charges and the translation of reports. Quotations are valid for thirty days from the date of issue.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Test request form</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Client: Ardenne Polytechnic, Department of Mechanical Engineering<br>Contact: Dr. Sofia Renard | Purchase order: AP-2026-118<br>Samples submitted: 18 | Date received: 3 April</p><p class=\"mt-2\">Tests requested: tensile strength (ISO 6892) — 12 samples, expedited turnaround; hardness survey (ASTM E18) — 6 samples, standard turnaround.</p><p class=\"mt-2\">Sectioning required: yes, for nine of the tensile specimens.</p><p class=\"mt-2\">Special instructions: the report is to be issued in French and English, and every certificate must cite the purchase order number.</p><p class=\"mt-2\">Billing address: 14 Rue des Ateliers, Namur. Reports are to be delivered electronically in PDF format only; printed copies are not required. The department's laboratory coordinator, M. Verhoeven, will act as technical contact for any query arising during testing.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 3: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: accounts@brightwell-testing.example<br>To: S. Renard<br>Subject: Quotation AP-2026-118 — clarification needed</p><p class=\"mt-2\">Dear Dr. Renard,</p><p class=\"mt-2\">Thank you for the eighteen samples, which arrived safely on 3 April. Before we issue the formal quotation, two points require your confirmation.</p><p class=\"mt-2\">First, your form requests expedited turnaround for the tensile tests only; the hardness survey will follow the standard three-day schedule. Second, we note that sectioning is required for nine of the tensile specimens, which attracts the supplement published in our schedule. Please confirm that this is acceptable.</p><p class=\"mt-2\">I should also point out that the academic reduction cannot be combined with expedited service, so the twelve tensile tests will be charged at the full published rate. If, however, you were willing to accept the standard five-day turnaround, the reduction would apply and the saving would be considerable.</p><p class=\"mt-2\">Our quotation will follow within one working day of your reply. Please note that we invoice in US dollars and that courier costs are additional.</p><p class=\"mt-2\">Regards,<br>Marcus Ihejirika, Accounts</p></div>","questionText":"Why will the academic reduction not apply to the tensile tests?","options":[{"key":"A","text":"(A) Those specimens must be sectioned before testing."},{"key":"B","text":"(B) The client requested expedited turnaround for them."},{"key":"C","text":"(C) The purchase order was submitted after the deadline."},{"key":"D","text":"(D) The report is to be produced in two languages."}],"correct":"B","translation":"Vì sao mức giảm dành cho học viện không áp dụng cho các mẫu thử kéo? — Vì khách hàng yêu cầu thời gian trả kết quả nhanh cho các mẫu đó.","explanation":"Tài liệu 2 ghi 12 mẫu thử kéo dùng 'expedited turnaround', còn Tài liệu 3 khẳng định 'the academic reduction cannot be combined with expedited service'. Tài liệu 1 cũng quy định mức giảm chỉ áp dụng cho 'standard-turnaround tests'. Phụ phí cắt mẫu (A) là khoản riêng, không phải lý do mất ưu đãi.","vocab":[{"word":"expedited","pos":"adj.","meaning":"nhanh, thúc đẩy tiến độ"},{"word":"supplement","pos":"n.","meaning":"phụ phí"},{"word":"specimen","pos":"n.","meaning":"mẫu thử"}]},{"id":"reading-lv6-test-1-q193","questionNumber":193,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 193 (Part 7: Đọc hiểu)","passageTitle":"Questions 191-195 refer to the following fee schedule, request form and e-mail:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Schedule of fees</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">BRIGHTWELL TESTING SERVICES — SCHEDULE OF FEES (EXTRACT)</p><table class=\"mt-2 w-full text-left\"><tr><th>Test</th><th>Standard turnaround</th><th>Fee per sample</th></tr><tr><td>Tensile strength (ISO 6892)</td><td>5 working days</td><td>$210</td></tr><tr><td>Tensile strength, expedited</td><td>2 working days</td><td>$315</td></tr><tr><td>Hardness survey (ASTM E18)</td><td>3 working days</td><td>$145</td></tr><tr><td>Salt-spray corrosion (ISO 9227)</td><td>10 working days</td><td>$480</td></tr><tr><td>Metallographic examination</td><td>7 working days</td><td>$360</td></tr></table><p class=\"mt-2\">A supplement of 12 percent is applied to any specimen requiring sectioning before testing. Academic and public research institutions receive an 8 percent reduction, which applies to standard-turnaround tests only and may not be combined with expedited service. Fees exclude courier charges and the translation of reports. Quotations are valid for thirty days from the date of issue.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Test request form</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Client: Ardenne Polytechnic, Department of Mechanical Engineering<br>Contact: Dr. Sofia Renard | Purchase order: AP-2026-118<br>Samples submitted: 18 | Date received: 3 April</p><p class=\"mt-2\">Tests requested: tensile strength (ISO 6892) — 12 samples, expedited turnaround; hardness survey (ASTM E18) — 6 samples, standard turnaround.</p><p class=\"mt-2\">Sectioning required: yes, for nine of the tensile specimens.</p><p class=\"mt-2\">Special instructions: the report is to be issued in French and English, and every certificate must cite the purchase order number.</p><p class=\"mt-2\">Billing address: 14 Rue des Ateliers, Namur. Reports are to be delivered electronically in PDF format only; printed copies are not required. The department's laboratory coordinator, M. Verhoeven, will act as technical contact for any query arising during testing.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 3: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: accounts@brightwell-testing.example<br>To: S. Renard<br>Subject: Quotation AP-2026-118 — clarification needed</p><p class=\"mt-2\">Dear Dr. Renard,</p><p class=\"mt-2\">Thank you for the eighteen samples, which arrived safely on 3 April. Before we issue the formal quotation, two points require your confirmation.</p><p class=\"mt-2\">First, your form requests expedited turnaround for the tensile tests only; the hardness survey will follow the standard three-day schedule. Second, we note that sectioning is required for nine of the tensile specimens, which attracts the supplement published in our schedule. Please confirm that this is acceptable.</p><p class=\"mt-2\">I should also point out that the academic reduction cannot be combined with expedited service, so the twelve tensile tests will be charged at the full published rate. If, however, you were willing to accept the standard five-day turnaround, the reduction would apply and the saving would be considerable.</p><p class=\"mt-2\">Our quotation will follow within one working day of your reply. Please note that we invoice in US dollars and that courier costs are additional.</p><p class=\"mt-2\">Regards,<br>Marcus Ihejirika, Accounts</p></div>","questionText":"Based on the schedule of fees, what will the hardness survey cost, before any supplement or reduction?","options":[{"key":"A","text":"(A) $870"},{"key":"B","text":"(B) $780"},{"key":"C","text":"(C) $580"},{"key":"D","text":"(D) $1,260"}],"correct":"A","translation":"Theo bảng giá, phí khảo sát độ cứng là bao nhiêu trước mọi phụ phí hay giảm giá? — 870 đô la.","explanation":"Tài liệu 2 cho biết có 6 mẫu khảo sát độ cứng; Tài liệu 1 niêm yết 'Hardness survey (ASTM E18) ... $145' mỗi mẫu. Vậy 6 × $145 = $870. Cần ghép số mẫu ở phiếu đăng ký với đơn giá ở bảng giá.","vocab":[{"word":"per sample","pos":"prep. phr.","meaning":"mỗi mẫu"},{"word":"survey","pos":"n.","meaning":"khảo sát, đo đạc"},{"word":"fee schedule","pos":"n. phr.","meaning":"bảng phí"}]},{"id":"reading-lv6-test-1-q194","questionNumber":194,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 194 (Part 7: Đọc hiểu)","passageTitle":"Questions 191-195 refer to the following fee schedule, request form and e-mail:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Schedule of fees</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">BRIGHTWELL TESTING SERVICES — SCHEDULE OF FEES (EXTRACT)</p><table class=\"mt-2 w-full text-left\"><tr><th>Test</th><th>Standard turnaround</th><th>Fee per sample</th></tr><tr><td>Tensile strength (ISO 6892)</td><td>5 working days</td><td>$210</td></tr><tr><td>Tensile strength, expedited</td><td>2 working days</td><td>$315</td></tr><tr><td>Hardness survey (ASTM E18)</td><td>3 working days</td><td>$145</td></tr><tr><td>Salt-spray corrosion (ISO 9227)</td><td>10 working days</td><td>$480</td></tr><tr><td>Metallographic examination</td><td>7 working days</td><td>$360</td></tr></table><p class=\"mt-2\">A supplement of 12 percent is applied to any specimen requiring sectioning before testing. Academic and public research institutions receive an 8 percent reduction, which applies to standard-turnaround tests only and may not be combined with expedited service. Fees exclude courier charges and the translation of reports. Quotations are valid for thirty days from the date of issue.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Test request form</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Client: Ardenne Polytechnic, Department of Mechanical Engineering<br>Contact: Dr. Sofia Renard | Purchase order: AP-2026-118<br>Samples submitted: 18 | Date received: 3 April</p><p class=\"mt-2\">Tests requested: tensile strength (ISO 6892) — 12 samples, expedited turnaround; hardness survey (ASTM E18) — 6 samples, standard turnaround.</p><p class=\"mt-2\">Sectioning required: yes, for nine of the tensile specimens.</p><p class=\"mt-2\">Special instructions: the report is to be issued in French and English, and every certificate must cite the purchase order number.</p><p class=\"mt-2\">Billing address: 14 Rue des Ateliers, Namur. Reports are to be delivered electronically in PDF format only; printed copies are not required. The department's laboratory coordinator, M. Verhoeven, will act as technical contact for any query arising during testing.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 3: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: accounts@brightwell-testing.example<br>To: S. Renard<br>Subject: Quotation AP-2026-118 — clarification needed</p><p class=\"mt-2\">Dear Dr. Renard,</p><p class=\"mt-2\">Thank you for the eighteen samples, which arrived safely on 3 April. Before we issue the formal quotation, two points require your confirmation.</p><p class=\"mt-2\">First, your form requests expedited turnaround for the tensile tests only; the hardness survey will follow the standard three-day schedule. Second, we note that sectioning is required for nine of the tensile specimens, which attracts the supplement published in our schedule. Please confirm that this is acceptable.</p><p class=\"mt-2\">I should also point out that the academic reduction cannot be combined with expedited service, so the twelve tensile tests will be charged at the full published rate. If, however, you were willing to accept the standard five-day turnaround, the reduction would apply and the saving would be considerable.</p><p class=\"mt-2\">Our quotation will follow within one working day of your reply. Please note that we invoice in US dollars and that courier costs are additional.</p><p class=\"mt-2\">Regards,<br>Marcus Ihejirika, Accounts</p></div>","questionText":"What does Mr. Ihejirika imply about the standard five-day turnaround?","options":[{"key":"A","text":"(A) It would lower the charge appreciably but postpone the results."},{"key":"B","text":"(B) It is unavailable for specimens that require sectioning."},{"key":"C","text":"(C) It is reserved exclusively for academic clients."},{"key":"D","text":"(D) It would oblige the client to collect the samples in person."}],"correct":"A","translation":"Ông Ihejirika hàm ý gì về thời gian trả kết quả tiêu chuẩn năm ngày? — Nó sẽ giảm chi phí đáng kể nhưng làm kết quả ra muộn hơn.","explanation":"Câu 'If ... you were willing to accept the standard five-day turnaround, the reduction would apply and the saving would be considerable' cho thấy đánh đổi: tiết kiệm chi phí nhưng chậm hơn (5 ngày so với 2 ngày ghi ở Tài liệu 1). Không có thông tin nào nói mẫu cắt không dùng được gói tiêu chuẩn (B).","vocab":[{"word":"considerable","pos":"adj.","meaning":"đáng kể"},{"word":"saving","pos":"n.","meaning":"khoản tiết kiệm"},{"word":"be willing to","pos":"adj. phr.","meaning":"sẵn lòng"}]},{"id":"reading-lv6-test-1-q195","questionNumber":195,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 195 (Part 7: Đọc hiểu)","passageTitle":"Questions 191-195 refer to the following fee schedule, request form and e-mail:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Schedule of fees</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">BRIGHTWELL TESTING SERVICES — SCHEDULE OF FEES (EXTRACT)</p><table class=\"mt-2 w-full text-left\"><tr><th>Test</th><th>Standard turnaround</th><th>Fee per sample</th></tr><tr><td>Tensile strength (ISO 6892)</td><td>5 working days</td><td>$210</td></tr><tr><td>Tensile strength, expedited</td><td>2 working days</td><td>$315</td></tr><tr><td>Hardness survey (ASTM E18)</td><td>3 working days</td><td>$145</td></tr><tr><td>Salt-spray corrosion (ISO 9227)</td><td>10 working days</td><td>$480</td></tr><tr><td>Metallographic examination</td><td>7 working days</td><td>$360</td></tr></table><p class=\"mt-2\">A supplement of 12 percent is applied to any specimen requiring sectioning before testing. Academic and public research institutions receive an 8 percent reduction, which applies to standard-turnaround tests only and may not be combined with expedited service. Fees exclude courier charges and the translation of reports. Quotations are valid for thirty days from the date of issue.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Test request form</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">Client: Ardenne Polytechnic, Department of Mechanical Engineering<br>Contact: Dr. Sofia Renard | Purchase order: AP-2026-118<br>Samples submitted: 18 | Date received: 3 April</p><p class=\"mt-2\">Tests requested: tensile strength (ISO 6892) — 12 samples, expedited turnaround; hardness survey (ASTM E18) — 6 samples, standard turnaround.</p><p class=\"mt-2\">Sectioning required: yes, for nine of the tensile specimens.</p><p class=\"mt-2\">Special instructions: the report is to be issued in French and English, and every certificate must cite the purchase order number.</p><p class=\"mt-2\">Billing address: 14 Rue des Ateliers, Namur. Reports are to be delivered electronically in PDF format only; printed copies are not required. The department's laboratory coordinator, M. Verhoeven, will act as technical contact for any query arising during testing.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 3: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: accounts@brightwell-testing.example<br>To: S. Renard<br>Subject: Quotation AP-2026-118 — clarification needed</p><p class=\"mt-2\">Dear Dr. Renard,</p><p class=\"mt-2\">Thank you for the eighteen samples, which arrived safely on 3 April. Before we issue the formal quotation, two points require your confirmation.</p><p class=\"mt-2\">First, your form requests expedited turnaround for the tensile tests only; the hardness survey will follow the standard three-day schedule. Second, we note that sectioning is required for nine of the tensile specimens, which attracts the supplement published in our schedule. Please confirm that this is acceptable.</p><p class=\"mt-2\">I should also point out that the academic reduction cannot be combined with expedited service, so the twelve tensile tests will be charged at the full published rate. If, however, you were willing to accept the standard five-day turnaround, the reduction would apply and the saving would be considerable.</p><p class=\"mt-2\">Our quotation will follow within one working day of your reply. Please note that we invoice in US dollars and that courier costs are additional.</p><p class=\"mt-2\">Regards,<br>Marcus Ihejirika, Accounts</p></div>","questionText":"In the e-mail, the verb \"attracts\" in \"attracts the supplement\" is closest in meaning to","options":[{"key":"A","text":"(A) reduces"},{"key":"B","text":"(B) avoids"},{"key":"C","text":"(C) advertises"},{"key":"D","text":"(D) incurs"}],"correct":"D","translation":"Động từ 'attracts' trong 'attracts the supplement' gần nghĩa nhất với 'phát sinh'.","explanation":"Trong văn bản thương mại, 'attract a charge/supplement' nghĩa là làm phát sinh khoản phí đó (incur). Câu này nói việc cắt mẫu sẽ phát sinh phụ phí 12% đã công bố ở Tài liệu 1.","vocab":[{"word":"attract a charge","pos":"v. phr.","meaning":"phát sinh một khoản phí"},{"word":"incur","pos":"v.","meaning":"gánh chịu, phát sinh"},{"word":"sectioning","pos":"n.","meaning":"việc cắt mẫu"}]},{"id":"reading-lv6-test-1-q196","questionNumber":196,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 196 (Part 7: Đọc hiểu)","passageTitle":"Questions 196-200 refer to the following notice, allocation table and e-mail:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Notice</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">MERIDIAN HOUSE — PHASE 2 REFURBISHMENT<br>Notice to occupants of floors three to five</p><p class=\"mt-2\">Work on the second phase of the refurbishment will begin on 2 June. Contractors will complete the building floor by floor, starting at the top and working downwards, and each floor is expected to be out of use for approximately three weeks.</p><p class=\"mt-2\">Occupants of the three affected floors must vacate their accommodation by 30 May. Temporary allocations are published in the table below.</p><p class=\"mt-2\">The goods lift will be reserved for the contractors between 07:00 and 16:00 each weekday; staff moving crates should therefore schedule their use of the lift outside those hours.</p><p class=\"mt-2\">Every crate must carry a label showing the department code and the destination floor. Personal belongings should be cleared from desks, but IT equipment — monitors, docking stations and handsets — must not be disconnected or packed by staff. The approved vendor will dismantle, label and transport all such items.</p><p class=\"mt-2\">Queries: facilities@meridianhouse.example</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Allocation table</p><hr class=\"my-2 border-neutral-300\"><table class=\"mt-2 w-full text-left\"><tr><th>Department</th><th>Current floor</th><th>Temporary location</th><th>Expected return</th></tr><tr><td>Finance</td><td>5</td><td>Building B, 2nd floor</td><td>4 August</td></tr><tr><td>Legal</td><td>4</td><td>Building B, 3rd floor</td><td>25 August</td></tr><tr><td>Product Design</td><td>3</td><td>Remote working, with co-working allowance</td><td>22 September</td></tr></table><p class=\"mt-2\">Notes: the third-floor suite in Building B is shared with the Finance overflow at peak periods. Storage of archived files at the temporary site is limited to twenty crates per department; anything beyond that limit must remain in the off-site records facility. Departments will be notified of any change to these allocations at least ten working days in advance, and the department code shown in the intranet directory is to be used on all labels.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 3: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Rowena Adeyemi, Head of Legal<br>To: Facilities Helpdesk<br>Subject: Relocation — archive access and permits</p><p class=\"mt-2\">Dear Facilities,</p><p class=\"mt-2\">Two concerns about our move on 30 May.</p><p class=\"mt-2\">Our case files fill roughly forty crates. The notice states that IT equipment must be handled by the vendor; does the same restriction apply to document archives, or may my team pack them ourselves? We cannot risk files arriving out of sequence in Building B, since three matters are listed for hearing in early June.</p><p class=\"mt-2\">Second, seven members of my team hold parking permits for Meridian House. The notice says nothing about whether these will be honoured at the temporary site; if they are not, we shall have to arrange alternative transport for colleagues who commute from outside the city.</p><p class=\"mt-2\">Finally, the floor plan circulated last week shows Legal on the third floor of Building B, which I understand is also earmarked for Finance's overflow. Could you confirm the allocation before we label the crates, as the department code must appear on every label?</p><p class=\"mt-2\">Kind regards,<br>Rowena Adeyemi</p></div>","questionText":"Based on the notice and the allocation table, which statement accurately describes the sequence of the Phase 2 refurbishment?","options":[{"key":"A","text":"(A) All three affected departments will vacate simultaneously on 2 June as contractors begin on every floor."},{"key":"B","text":"(B) Product Design staff will relocate to Building B once Finance completes its nine-week refurbishment period."},{"key":"C","text":"(C) Work on Legal's current floor is scheduled to conclude immediately before Finance returns on 4 August."},{"key":"D","text":"(D) Refurbishment will progress sequentially from the Finance floor down to the Product Design floor."}],"correct":"D","translation":"Dựa trên thông báo và bảng phân bổ, phát biểu nào mô tả đúng trình tự cải tạo Giai đoạn 2? — Việc cải tạo sẽ tiến hành tuần tự từ tầng của Finance xuống tới tầng của Product Design.","explanation":"Tài liệu 1 nêu nhà thầu thi công từng tầng một, bắt đầu từ tầng cao nhất đi xuống ('starting at the top and working downwards'). Kết hợp Tài liệu 2: Finance ở tầng 5, Legal ở tầng 4 và Product Design ở tầng 3 — tức thứ tự là Finance → Legal → Product Design. A sai vì phải rời đi trước 30/5 và thi công từng tầng; C sai vì mỗi tầng mất khoảng 3 tuần nên tầng 4 (Legal) hoàn tất khoảng giữa tháng 7 chứ không phải đầu tháng 8; B sai vì Product Design làm việc từ xa và 9 tuần là tổng thời gian của cả 3 tầng.","vocab":[{"word":"refurbishment","pos":"n.","meaning":"việc cải tạo, nâng cấp"},{"word":"sequentially","pos":"adv.","meaning":"một cách tuần tự, lần lượt"},{"word":"vacate","pos":"v.","meaning":"rời đi, trả lại chỗ"}]},{"id":"reading-lv6-test-1-q197","questionNumber":197,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 197 (Part 7: Đọc hiểu)","passageTitle":"Questions 196-200 refer to the following notice, allocation table and e-mail:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Notice</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">MERIDIAN HOUSE — PHASE 2 REFURBISHMENT<br>Notice to occupants of floors three to five</p><p class=\"mt-2\">Work on the second phase of the refurbishment will begin on 2 June. Contractors will complete the building floor by floor, starting at the top and working downwards, and each floor is expected to be out of use for approximately three weeks.</p><p class=\"mt-2\">Occupants of the three affected floors must vacate their accommodation by 30 May. Temporary allocations are published in the table below.</p><p class=\"mt-2\">The goods lift will be reserved for the contractors between 07:00 and 16:00 each weekday; staff moving crates should therefore schedule their use of the lift outside those hours.</p><p class=\"mt-2\">Every crate must carry a label showing the department code and the destination floor. Personal belongings should be cleared from desks, but IT equipment — monitors, docking stations and handsets — must not be disconnected or packed by staff. The approved vendor will dismantle, label and transport all such items.</p><p class=\"mt-2\">Queries: facilities@meridianhouse.example</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Allocation table</p><hr class=\"my-2 border-neutral-300\"><table class=\"mt-2 w-full text-left\"><tr><th>Department</th><th>Current floor</th><th>Temporary location</th><th>Expected return</th></tr><tr><td>Finance</td><td>5</td><td>Building B, 2nd floor</td><td>4 August</td></tr><tr><td>Legal</td><td>4</td><td>Building B, 3rd floor</td><td>25 August</td></tr><tr><td>Product Design</td><td>3</td><td>Remote working, with co-working allowance</td><td>22 September</td></tr></table><p class=\"mt-2\">Notes: the third-floor suite in Building B is shared with the Finance overflow at peak periods. Storage of archived files at the temporary site is limited to twenty crates per department; anything beyond that limit must remain in the off-site records facility. Departments will be notified of any change to these allocations at least ten working days in advance, and the department code shown in the intranet directory is to be used on all labels.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 3: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Rowena Adeyemi, Head of Legal<br>To: Facilities Helpdesk<br>Subject: Relocation — archive access and permits</p><p class=\"mt-2\">Dear Facilities,</p><p class=\"mt-2\">Two concerns about our move on 30 May.</p><p class=\"mt-2\">Our case files fill roughly forty crates. The notice states that IT equipment must be handled by the vendor; does the same restriction apply to document archives, or may my team pack them ourselves? We cannot risk files arriving out of sequence in Building B, since three matters are listed for hearing in early June.</p><p class=\"mt-2\">Second, seven members of my team hold parking permits for Meridian House. The notice says nothing about whether these will be honoured at the temporary site; if they are not, we shall have to arrange alternative transport for colleagues who commute from outside the city.</p><p class=\"mt-2\">Finally, the floor plan circulated last week shows Legal on the third floor of Building B, which I understand is also earmarked for Finance's overflow. Could you confirm the allocation before we label the crates, as the department code must appear on every label?</p><p class=\"mt-2\">Kind regards,<br>Rowena Adeyemi</p></div>","questionText":"Based on the notice and the table, when is work on the floor occupied by Product Design expected to begin?","options":[{"key":"A","text":"(A) In mid-July"},{"key":"B","text":"(B) In late June"},{"key":"C","text":"(C) In early June"},{"key":"D","text":"(D) In late August"}],"correct":"A","translation":"Dựa trên thông báo và bảng phân bổ, công việc ở tầng của bộ phận Product Design dự kiến bắt đầu khi nào? — Giữa tháng Bảy.","explanation":"Product Design ở tầng 3. Theo thông báo, thi công từ 2/6 theo thứ tự giảm dần, mỗi tầng khoảng ba tuần: tầng 5 (Finance) khoảng 2-23/6, tầng 4 (Legal) khoảng 23/6-14/7, tầng 3 bắt đầu khoảng giữa tháng 7. Ngày 22/9 ở bảng là ngày dự kiến trở về, không phải ngày khởi công.","vocab":[{"word":"approximately","pos":"adv.","meaning":"xấp xỉ"},{"word":"allocation","pos":"n.","meaning":"sự phân bổ"},{"word":"expected return","pos":"n. phr.","meaning":"ngày dự kiến quay về"}]},{"id":"reading-lv6-test-1-q198","questionNumber":198,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 198 (Part 7: Đọc hiểu)","passageTitle":"Questions 196-200 refer to the following notice, allocation table and e-mail:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Notice</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">MERIDIAN HOUSE — PHASE 2 REFURBISHMENT<br>Notice to occupants of floors three to five</p><p class=\"mt-2\">Work on the second phase of the refurbishment will begin on 2 June. Contractors will complete the building floor by floor, starting at the top and working downwards, and each floor is expected to be out of use for approximately three weeks.</p><p class=\"mt-2\">Occupants of the three affected floors must vacate their accommodation by 30 May. Temporary allocations are published in the table below.</p><p class=\"mt-2\">The goods lift will be reserved for the contractors between 07:00 and 16:00 each weekday; staff moving crates should therefore schedule their use of the lift outside those hours.</p><p class=\"mt-2\">Every crate must carry a label showing the department code and the destination floor. Personal belongings should be cleared from desks, but IT equipment — monitors, docking stations and handsets — must not be disconnected or packed by staff. The approved vendor will dismantle, label and transport all such items.</p><p class=\"mt-2\">Queries: facilities@meridianhouse.example</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Allocation table</p><hr class=\"my-2 border-neutral-300\"><table class=\"mt-2 w-full text-left\"><tr><th>Department</th><th>Current floor</th><th>Temporary location</th><th>Expected return</th></tr><tr><td>Finance</td><td>5</td><td>Building B, 2nd floor</td><td>4 August</td></tr><tr><td>Legal</td><td>4</td><td>Building B, 3rd floor</td><td>25 August</td></tr><tr><td>Product Design</td><td>3</td><td>Remote working, with co-working allowance</td><td>22 September</td></tr></table><p class=\"mt-2\">Notes: the third-floor suite in Building B is shared with the Finance overflow at peak periods. Storage of archived files at the temporary site is limited to twenty crates per department; anything beyond that limit must remain in the off-site records facility. Departments will be notified of any change to these allocations at least ten working days in advance, and the department code shown in the intranet directory is to be used on all labels.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 3: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Rowena Adeyemi, Head of Legal<br>To: Facilities Helpdesk<br>Subject: Relocation — archive access and permits</p><p class=\"mt-2\">Dear Facilities,</p><p class=\"mt-2\">Two concerns about our move on 30 May.</p><p class=\"mt-2\">Our case files fill roughly forty crates. The notice states that IT equipment must be handled by the vendor; does the same restriction apply to document archives, or may my team pack them ourselves? We cannot risk files arriving out of sequence in Building B, since three matters are listed for hearing in early June.</p><p class=\"mt-2\">Second, seven members of my team hold parking permits for Meridian House. The notice says nothing about whether these will be honoured at the temporary site; if they are not, we shall have to arrange alternative transport for colleagues who commute from outside the city.</p><p class=\"mt-2\">Finally, the floor plan circulated last week shows Legal on the third floor of Building B, which I understand is also earmarked for Finance's overflow. Could you confirm the allocation before we label the crates, as the department code must appear on every label?</p><p class=\"mt-2\">Kind regards,<br>Rowena Adeyemi</p></div>","questionText":"What does Ms. Adeyemi imply about the parking permits?","options":[{"key":"A","text":"(A) They will automatically transfer to the temporary site."},{"key":"B","text":"(B) They are issued by the landlord of Building B."},{"key":"C","text":"(C) They have already been withdrawn by the Facilities team."},{"key":"D","text":"(D) It is unclear whether they will remain valid at the temporary site."}],"correct":"D","translation":"Bà Adeyemi hàm ý gì về giấy phép đỗ xe? — Chưa rõ chúng có còn hiệu lực ở địa điểm tạm hay không.","explanation":"Bà viết 'The notice says nothing about whether these will be honoured at the temporary site' — tức thông báo im lặng về vấn đề này, chứ không nói sẽ tự động chuyển (A) hay đã bị thu hồi (C).","vocab":[{"word":"honour","pos":"v.","meaning":"tôn trọng, công nhận hiệu lực"},{"word":"permit","pos":"n.","meaning":"giấy phép"},{"word":"commute","pos":"v.","meaning":"đi lại làm việc"}]},{"id":"reading-lv6-test-1-q199","questionNumber":199,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 199 (Part 7: Đọc hiểu)","passageTitle":"Questions 196-200 refer to the following notice, allocation table and e-mail:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Notice</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">MERIDIAN HOUSE — PHASE 2 REFURBISHMENT<br>Notice to occupants of floors three to five</p><p class=\"mt-2\">Work on the second phase of the refurbishment will begin on 2 June. Contractors will complete the building floor by floor, starting at the top and working downwards, and each floor is expected to be out of use for approximately three weeks.</p><p class=\"mt-2\">Occupants of the three affected floors must vacate their accommodation by 30 May. Temporary allocations are published in the table below.</p><p class=\"mt-2\">The goods lift will be reserved for the contractors between 07:00 and 16:00 each weekday; staff moving crates should therefore schedule their use of the lift outside those hours.</p><p class=\"mt-2\">Every crate must carry a label showing the department code and the destination floor. Personal belongings should be cleared from desks, but IT equipment — monitors, docking stations and handsets — must not be disconnected or packed by staff. The approved vendor will dismantle, label and transport all such items.</p><p class=\"mt-2\">Queries: facilities@meridianhouse.example</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Allocation table</p><hr class=\"my-2 border-neutral-300\"><table class=\"mt-2 w-full text-left\"><tr><th>Department</th><th>Current floor</th><th>Temporary location</th><th>Expected return</th></tr><tr><td>Finance</td><td>5</td><td>Building B, 2nd floor</td><td>4 August</td></tr><tr><td>Legal</td><td>4</td><td>Building B, 3rd floor</td><td>25 August</td></tr><tr><td>Product Design</td><td>3</td><td>Remote working, with co-working allowance</td><td>22 September</td></tr></table><p class=\"mt-2\">Notes: the third-floor suite in Building B is shared with the Finance overflow at peak periods. Storage of archived files at the temporary site is limited to twenty crates per department; anything beyond that limit must remain in the off-site records facility. Departments will be notified of any change to these allocations at least ten working days in advance, and the department code shown in the intranet directory is to be used on all labels.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 3: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Rowena Adeyemi, Head of Legal<br>To: Facilities Helpdesk<br>Subject: Relocation — archive access and permits</p><p class=\"mt-2\">Dear Facilities,</p><p class=\"mt-2\">Two concerns about our move on 30 May.</p><p class=\"mt-2\">Our case files fill roughly forty crates. The notice states that IT equipment must be handled by the vendor; does the same restriction apply to document archives, or may my team pack them ourselves? We cannot risk files arriving out of sequence in Building B, since three matters are listed for hearing in early June.</p><p class=\"mt-2\">Second, seven members of my team hold parking permits for Meridian House. The notice says nothing about whether these will be honoured at the temporary site; if they are not, we shall have to arrange alternative transport for colleagues who commute from outside the city.</p><p class=\"mt-2\">Finally, the floor plan circulated last week shows Legal on the third floor of Building B, which I understand is also earmarked for Finance's overflow. Could you confirm the allocation before we label the crates, as the department code must appear on every label?</p><p class=\"mt-2\">Kind regards,<br>Rowena Adeyemi</p></div>","questionText":"Why does Ms. Adeyemi want the floor allocation confirmed before the crates are labelled?","options":[{"key":"A","text":"(A) The department code and destination must match, or the files could be misdirected."},{"key":"B","text":"(B) The contractors refuse to move any crate that lacks a label."},{"key":"C","text":"(C) The labels have to be printed in two languages."},{"key":"D","text":"(D) The IT vendor needs the codes in order to disconnect the equipment."}],"correct":"A","translation":"Vì sao bà Adeyemi muốn xác nhận phân bổ tầng trước khi dán nhãn thùng? — Mã bộ phận và điểm đến phải khớp nhau, nếu không hồ sơ có thể bị chuyển nhầm.","explanation":"Bà nêu nghi vấn Legal ở tầng 3 toà B có thể trùng với chỗ để đồ của Finance, rồi nói 'Could you confirm the allocation before we label the crates, as the department code must appear on every label' — nhãn phải ghi đúng đích đến, nên phân bổ sai sẽ khiến hồ sơ đi nhầm. Điều này kết hợp quy định dán nhãn ở Tài liệu 1 với băn khoăn ở Tài liệu 3.","vocab":[{"word":"misdirect","pos":"v.","meaning":"chuyển nhầm hướng"},{"word":"earmark","pos":"v.","meaning":"dành riêng cho mục đích nào đó"},{"word":"out of sequence","pos":"adj. phr.","meaning":"sai thứ tự"}]},{"id":"reading-lv6-test-1-q200","questionNumber":200,"etsYear":"2026","etsTestId":"reading-lv6-test-1","part":"Part 7","partNumber":7,"partName":"Part 7: Đọc hiểu (Reading Comprehension)","title":"Test 01 (Level 6) • Câu 200 (Part 7: Đọc hiểu)","passageTitle":"Questions 196-200 refer to the following notice, allocation table and e-mail:","passageHtml":"<div class=\"border-2 border-neutral-800 bg-white p-4 sm:p-5 text-sm leading-relaxed text-neutral-900 shadow-sm mb-3\"><p class=\"font-bold text-center text-base\">Document 1: Notice</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">MERIDIAN HOUSE — PHASE 2 REFURBISHMENT<br>Notice to occupants of floors three to five</p><p class=\"mt-2\">Work on the second phase of the refurbishment will begin on 2 June. Contractors will complete the building floor by floor, starting at the top and working downwards, and each floor is expected to be out of use for approximately three weeks.</p><p class=\"mt-2\">Occupants of the three affected floors must vacate their accommodation by 30 May. Temporary allocations are published in the table below.</p><p class=\"mt-2\">The goods lift will be reserved for the contractors between 07:00 and 16:00 each weekday; staff moving crates should therefore schedule their use of the lift outside those hours.</p><p class=\"mt-2\">Every crate must carry a label showing the department code and the destination floor. Personal belongings should be cleared from desks, but IT equipment — monitors, docking stations and handsets — must not be disconnected or packed by staff. The approved vendor will dismantle, label and transport all such items.</p><p class=\"mt-2\">Queries: facilities@meridianhouse.example</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 2: Allocation table</p><hr class=\"my-2 border-neutral-300\"><table class=\"mt-2 w-full text-left\"><tr><th>Department</th><th>Current floor</th><th>Temporary location</th><th>Expected return</th></tr><tr><td>Finance</td><td>5</td><td>Building B, 2nd floor</td><td>4 August</td></tr><tr><td>Legal</td><td>4</td><td>Building B, 3rd floor</td><td>25 August</td></tr><tr><td>Product Design</td><td>3</td><td>Remote working, with co-working allowance</td><td>22 September</td></tr></table><p class=\"mt-2\">Notes: the third-floor suite in Building B is shared with the Finance overflow at peak periods. Storage of archived files at the temporary site is limited to twenty crates per department; anything beyond that limit must remain in the off-site records facility. Departments will be notified of any change to these allocations at least ten working days in advance, and the department code shown in the intranet directory is to be used on all labels.</p><hr class=\"my-2 border-neutral-300\"><p class=\"font-bold text-center text-base\">Document 3: E-mail</p><hr class=\"my-2 border-neutral-300\"><p class=\"mt-2\">From: Rowena Adeyemi, Head of Legal<br>To: Facilities Helpdesk<br>Subject: Relocation — archive access and permits</p><p class=\"mt-2\">Dear Facilities,</p><p class=\"mt-2\">Two concerns about our move on 30 May.</p><p class=\"mt-2\">Our case files fill roughly forty crates. The notice states that IT equipment must be handled by the vendor; does the same restriction apply to document archives, or may my team pack them ourselves? We cannot risk files arriving out of sequence in Building B, since three matters are listed for hearing in early June.</p><p class=\"mt-2\">Second, seven members of my team hold parking permits for Meridian House. The notice says nothing about whether these will be honoured at the temporary site; if they are not, we shall have to arrange alternative transport for colleagues who commute from outside the city.</p><p class=\"mt-2\">Finally, the floor plan circulated last week shows Legal on the third floor of Building B, which I understand is also earmarked for Finance's overflow. Could you confirm the allocation before we label the crates, as the department code must appear on every label?</p><p class=\"mt-2\">Kind regards,<br>Rowena Adeyemi</p></div>","questionText":"Based on the notice and allocation notes, staff are required to do all of the following EXCEPT","options":[{"key":"A","text":"(A) disconnect and label desktop IT hardware prior to vendor pickup"},{"key":"B","text":"(B) identify each packed crate with an intranet department code and destination floor"},{"key":"C","text":"(C) schedule lift usage for moving crates outside daytime contractor hours"},{"key":"D","text":"(D) clear personal workstations before the end of May"}],"correct":"A","translation":"Dựa theo thông báo và ghi chú phân bổ, nhân viên được yêu cầu làm tất cả các việc sau NGOẠI TRỪ: tự ngắt kết nối và dán nhãn thiết bị IT để bàn trước khi nhà cung cấp đến lấy.","explanation":"Thông báo nêu rõ thiết bị IT (màn hình, dock, điện thoại bàn) 'must not be disconnected or packed by staff. The approved vendor will dismantle, label and transport all such items', nên A trái với quy định. Các ý D (rời đi trước 30/5 và dọn đồ cá nhân trên bàn), B (dán nhãn mã bộ phận trên danh bạ nội bộ và tầng đích) và C (chỉ dùng thang hàng ngoài khung 07:00–16:00) đều được yêu cầu.","vocab":[{"word":"approved vendor","pos":"n. phr.","meaning":"nhà cung cấp được phê duyệt"},{"word":"dismantle","pos":"v.","meaning":"tháo dỡ"},{"word":"workstation","pos":"n.","meaning":"bàn/vị trí làm việc"}]}]);
})();
